;IjDvG3B,qCAAA;EH+nIF;AACF","file":"app.css","sourcesContent":["@charset \"UTF-8\";\n@import url(\"https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,100..900;1,100..900&display=swap\");\nhtml {\n  line-height: 1.15; /* 1 */\n  -webkit-text-size-adjust: 100%; /* 2 */\n}\n\n/* Sections\n   ========================================================================== */\n/**\n * Remove the margin in all browsers.\n */\nbody {\n  margin: 0;\n}\n\n/**\n * Render the `main` element consistently in IE.\n */\nmain {\n  display: block;\n}\n\n/**\n * Correct the font size and margin on `h1` elements within `section` and\n * `article` contexts in Chrome, Firefox, and Safari.\n */\nh1 {\n  font-size: 2em;\n  margin: 0.67em 0;\n}\n\n/* Grouping content\n   ========================================================================== */\n/**\n * 1. Add the correct box sizing in Firefox.\n * 2. Show the overflow in Edge and IE.\n */\nhr {\n  box-sizing: content-box; /* 1 */\n  height: 0; /* 1 */\n  overflow: visible; /* 2 */\n}\n\n/**\n * 1. Correct the inheritance and scaling of font size in all browsers.\n * 2. Correct the odd `em` font sizing in all browsers.\n */\npre {\n  font-family: monospace, monospace; /* 1 */\n  font-size: 1em; /* 2 */\n}\n\n/* Text-level semantics\n   ========================================================================== */\n/**\n * Remove the gray background on active links in IE 10.\n */\na {\n  background-color: transparent;\n}\n\n/**\n * 1. Remove the bottom border in Chrome 57-\n * 2. Add the correct text decoration in Chrome, Edge, IE, Opera, and Safari.\n */\nabbr[title] {\n  border-bottom: none; /* 1 */\n  text-decoration: underline; /* 2 */\n  text-decoration: underline dotted; /* 2 */\n}\n\n/**\n * Add the correct font weight in Chrome, Edge, and Safari.\n */\nb,\nstrong {\n  font-weight: bolder;\n}\n\n/**\n * 1. Correct the inheritance and scaling of font size in all browsers.\n * 2. Correct the odd `em` font sizing in all browsers.\n */\ncode,\nkbd,\nsamp {\n  font-family: monospace, monospace; /* 1 */\n  font-size: 1em; /* 2 */\n}\n\n/**\n * Add the correct font size in all browsers.\n */\nsmall {\n  font-size: 80%;\n}\n\n/**\n * Prevent `sub` and `sup` elements from affecting the line height in\n * all browsers.\n */\nsub,\nsup {\n  font-size: 75%;\n  line-height: 0;\n  position: relative;\n  vertical-align: baseline;\n}\n\nsub {\n  bottom: -0.25em;\n}\n\nsup {\n  top: -0.5em;\n}\n\n/* Embedded content\n   ========================================================================== */\n/**\n * Remove the border on images inside links in IE 10.\n */\nimg {\n  border-style: none;\n}\n\n/* Forms\n   ========================================================================== */\n/**\n * 1. Change the font styles in all browsers.\n * 2. Remove the margin in Firefox and Safari.\n */\nbutton,\ninput,\noptgroup,\nselect,\ntextarea {\n  font-family: inherit; /* 1 */\n  font-size: 100%; /* 1 */\n  line-height: 1.15; /* 1 */\n  margin: 0; /* 2 */\n}\n\n/**\n * Show the overflow in IE.\n * 1. Show the overflow in Edge.\n */\nbutton,\ninput { /* 1 */\n  overflow: visible;\n}\n\n/**\n * Remove the inheritance of text transform in Edge, Firefox, and IE.\n * 1. Remove the inheritance of text transform in Firefox.\n */\nbutton,\nselect { /* 1 */\n  text-transform: none;\n}\n\n/**\n * Correct the inability to style clickable types in iOS and Safari.\n */\nbutton,\n[type=button],\n[type=reset],\n[type=submit] {\n  -webkit-appearance: button;\n}\n\n/**\n * Remove the inner border and padding in Firefox.\n */\nbutton::-moz-focus-inner,\n[type=button]::-moz-focus-inner,\n[type=reset]::-moz-focus-inner,\n[type=submit]::-moz-focus-inner {\n  border-style: none;\n  padding: 0;\n}\n\n/**\n * Restore the focus styles unset by the previous rule.\n */\nbutton:-moz-focusring,\n[type=button]:-moz-focusring,\n[type=reset]:-moz-focusring,\n[type=submit]:-moz-focusring {\n  outline: 1px dotted ButtonText;\n}\n\n/**\n * Correct the padding in Firefox.\n */\nfieldset {\n  padding: 0.35em 0.75em 0.625em;\n}\n\n/**\n * 1. Correct the text wrapping in Edge and IE.\n * 2. Correct the color inheritance from `fieldset` elements in IE.\n * 3. Remove the padding so developers are not caught out when they zero out\n *    `fieldset` elements in all browsers.\n */\nlegend {\n  box-sizing: border-box; /* 1 */\n  color: inherit; /* 2 */\n  display: table; /* 1 */\n  max-width: 100%; /* 1 */\n  padding: 0; /* 3 */\n  white-space: normal; /* 1 */\n}\n\n/**\n * Add the correct vertical alignment in Chrome, Firefox, and Opera.\n */\nprogress {\n  vertical-align: baseline;\n}\n\n/**\n * Remove the default vertical scrollbar in IE 10+.\n */\ntextarea {\n  overflow: auto;\n}\n\n/**\n * 1. Add the correct box sizing in IE 10.\n * 2. Remove the padding in IE 10.\n */\n[type=checkbox],\n[type=radio] {\n  box-sizing: border-box; /* 1 */\n  padding: 0; /* 2 */\n}\n\n/**\n * Correct the cursor style of increment and decrement buttons in Chrome.\n */\n[type=number]::-webkit-inner-spin-button,\n[type=number]::-webkit-outer-spin-button {\n  height: auto;\n}\n\n/**\n * 1. Correct the odd appearance in Chrome and Safari.\n * 2. Correct the outline style in Safari.\n */\n[type=search] {\n  -webkit-appearance: textfield; /* 1 */\n  outline-offset: -2px; /* 2 */\n}\n\n/**\n * Remove the inner padding in Chrome and Safari on macOS.\n */\n[type=search]::-webkit-search-decoration {\n  -webkit-appearance: none;\n}\n\n/**\n * 1. Correct the inability to style clickable types in iOS and Safari.\n * 2. Change font properties to `inherit` in Safari.\n */\n::-webkit-file-upload-button {\n  -webkit-appearance: button; /* 1 */\n  font: inherit; /* 2 */\n}\n\n/* Interactive\n   ========================================================================== */\n/*\n * Add the correct display in Edge, IE 10+, and Firefox.\n */\ndetails {\n  display: block;\n}\n\n/*\n * Add the correct display in all browsers.\n */\nsummary {\n  display: list-item;\n}\n\n/* Misc\n   ========================================================================== */\n/**\n * Add the correct display in IE 10+.\n */\ntemplate {\n  display: none;\n}\n\n/**\n * Add the correct display in IE 10.\n */\n[hidden] {\n  display: none;\n}\n\n/** Media Queries **/\nhtml {\n  font-size: 62.5%;\n  box-sizing: border-box;\n  height: 100%;\n}\n\n*, *:before, *:after {\n  box-sizing: inherit;\n}\n\nbody {\n  font-family: \"Outfit\", sans-serif;\n  font-size: 1.8rem;\n}\n\na {\n  text-decoration: none;\n}\n\nimg {\n  width: 100%;\n  height: auto;\n}\n\n.swal2-popup {\n  font-size: 2rem !important;\n}\n\nh1, h2, h3 {\n  font-family: \"Outfit\", sans-serif;\n  font-weight: 900;\n  margin: 2rem 0;\n}\n\nh1 {\n  font-size: 4rem;\n}\n\nh2 {\n  font-size: 3.6rem;\n}\n\nh3 {\n  font-size: 3rem;\n}\n\n.text-center {\n  text-align: center;\n}\n\n[class$=__heading] {\n  font-family: \"Outfit\", sans-serif;\n  font-weight: 900;\n  margin: 2rem 0;\n  margin: 6rem 0 3rem 0;\n  text-align: center;\n}\n\n[class$=__descripcion] {\n  text-align: center;\n  font-size: 1.8rem;\n  font-weight: 300;\n  color: #1E293B;\n  margin-bottom: 5rem;\n}\n\n@property --gradient-angle {\n  syntax: \"<angle>\";\n  initial-value: 0turn;\n  inherits: false;\n}\n.tarjeta {\n  animation: 2s gradient-angle infinite linear;\n  border: 2px solid transparent;\n  background-image: linear-gradient(#584827, #2d230f), conic-gradient(from var(--gradient-angle), #584827 0%, #c7a03c 37%, #f9de90 30%, #c7a03c 33%, #584827 40%, #584827 50%, #c7a03c 77%, #f9de90 80%, #c7a03c 83%, #584827 90%);\n  background-clip: padding-box, border-box;\n  background-origin: padding-box, border-box;\n}\n\n@keyframes gradient-angle {\n  to {\n    --gradient-angle: 1turn;\n  }\n}\n/* その他 */\n.tarjetas {\n  background: #141819;\n}\n\n.tarjetas {\n  font-family: \"游ゴシック Medium\", YuGothic, YuGothicM, \"Hiragino Kaku Gothic ProN\", Meiryo, sans-serif;\n  line-height: 1.6;\n  display: grid;\n  align-content: center;\n  min-height: 100svh;\n  padding: 24px;\n  color: #d5cec0;\n  gap: 24px;\n}\n@media (width < 970px) {\n  .tarjetas {\n    align-content: start;\n  }\n}\n\n.tarjetas__cuerpo {\n  display: grid;\n  justify-content: center;\n  margin-inline: auto;\n  grid-auto-flow: column;\n  gap: 16px 40px;\n}\n@media (width < 970px) {\n  .tarjetas__cuerpo {\n    grid-auto-flow: row;\n  }\n}\n\n.tarjeta {\n  display: grid;\n  max-width: 240px;\n  padding: 20px;\n  text-decoration: none;\n  color: currentColor;\n  border-radius: 20px;\n  place-content: center;\n  place-items: center;\n  aspect-ratio: 1/1;\n  row-gap: 16px;\n}\n\n.tarjeta h2 {\n  font-family: \"Comfortaa\", sans-serif;\n  font-size: 18px;\n  font-weight: 700;\n  font-style: normal;\n  font-optical-sizing: auto;\n}\n\n.tarjeta p {\n  font-size: 12px;\n}\n\n*,\n*::after,\n*::before {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\n.body-slider {\n  min-block-size: 68vh;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n  background-color: #e1e3e5;\n}\n\n.image-slider {\n  display: flex;\n  flex-flow: column;\n  width: clamp(360px, 96vw, 830px);\n  aspect-ratio: 16/9;\n  min-height: 300px;\n  overflow: hidden;\n  border-radius: 8px;\n  container-type: inline-size;\n  contain: content;\n  background-color: rgba(0, 0, 0, 0.4);\n  box-shadow: rgba(0, 0, 0, 0.2) 0px 1px 2px, rgba(0, 0, 0, 0.3) 0px 2px 4px, rgba(0, 0, 0, 0.25) 0px 4px 8px, rgba(0, 0, 0, 0.2) 0px 8px 16px, rgba(0, 0, 0, 0.15) 0px 16px 32px;\n}\n\n.slider__content {\n  flex-grow: 1;\n  display: flex;\n  justify-content: space-between;\n}\n\n.slider-control--button {\n  border: 0;\n  background: 0;\n  outline: 0;\n  cursor: pointer;\n  place-content: center;\n  padding-inline: 3vw;\n  z-index: 1;\n  display: grid;\n}\n\n.icon {\n  height: 2rem;\n  width: 2rem;\n  fill: var(hsl(203, 5%, 75%));\n  border-radius: 50%;\n}\n\n.slider-control--button:where(:hover) {\n  background-image: linear-gradient(to var(--position), rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.1333333333), 80%, rgba(0, 0, 0, 0.4) 100%);\n}\n.slider-control--button:where(:hover) .icon {\n  fill: hsl(203, 15%, 98%);\n  background: rgba(0, 0, 0, 0.0666666667);\n}\n\n.slider-control--button:active {\n  outline: 0.2em solid hsl(204, 100%, 53%);\n  outline-offset: -0.5em;\n}\n\n.prev-button {\n  --position: left;\n}\n\n.next-button {\n  --position: right;\n}\n\n.image-display {\n  position: fixed;\n  inset: 0;\n}\n\n.slider-navigation {\n  z-index: 10;\n  display: grid;\n  grid-auto-flow: column;\n  grid-template-columns: repeat(6, 1fr);\n  grid-auto-columns: 100%;\n  gap: 1.25rem;\n  padding: 1rem;\n  place-content: center;\n  background-color: hsla(203, 5%, 25%, 0.3);\n  backdrop-filter: blur(6px);\n}\n\n.nav-button {\n  display: grid;\n  width: 100%;\n  height: 100%;\n  border-radius: 0.5em;\n  overflow: hidden;\n  align-items: center;\n  justify-content: center;\n  border: 0;\n  aspect-ratio: 16/9;\n  transition: filter 150ms linear, scale 266ms ease;\n}\n\n.thumbnail {\n  display: block;\n  max-width: 100%;\n  width: 100%;\n  object-fit: cover;\n  height: 100%;\n}\n\n.nav-button[aria-selected=true] {\n  scale: 1.1;\n}\n\n.nav-button[aria-selected=true],\n.nav-button:focus-visible {\n  outline: 0.2em solid hsl(204, 100%, 53%);\n  outline-offset: 0.2em;\n}\n\n.nav-button[aria-selected=false] {\n  filter: opacity(0.7);\n}\n\n.nav-button[aria-selected=false]:where(:hover, :focus-visible) {\n  filter: opacity(1);\n}\n\n@container (max-width: 660px) {\n  .nav-button:not(:has(img)) {\n    background-color: rgb(241, 235, 232);\n  }\n  .slider-navigation {\n    display: flex;\n    justify-content: center;\n    padding-block: 1.5em;\n  }\n  .nav-button {\n    inline-size: 0.625rem;\n    aspect-ratio: 1;\n    border-radius: 50%;\n  }\n  .nav-button > .thumbnail {\n    display: none;\n  }\n  .nav-button[aria-selected=true] {\n    background-color: black;\n    scale: 1.5;\n  }\n}\n.carrusel {\n  background: #eaeaea;\n  overflow: hidden;\n  position: relative; /* Asegura que el carrusel permanezca dentro de esta sección */\n  height: 100vh; /* Asegura que cubra toda la pantalla si es necesario */\n}\n\n.carrusel_contenedor {\n  margin-top: 0;\n  position: relative; /* Mantiene el carrusel dentro de su sección */\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 1000px;\n  height: 600px;\n  background: #f5f5f5;\n  box-shadow: 0 30px 50px #dbdbdb;\n}\n\n.carrusel_contenedor .slide .item {\n  width: 200px;\n  height: 300px;\n  position: absolute;\n  top: 50%;\n  transform: translate(0, -50%);\n  border-radius: 20px;\n  box-shadow: 0 30px 50px #505050;\n  background-position: 50% 50%;\n  background-size: cover;\n  background-repeat: no-repeat;\n  display: inline-block;\n  transition: 0.5s;\n}\n\n.slide .item:nth-child(1),\n.slide .item:nth-child(2) {\n  top: 0;\n  left: 0;\n  transform: translate(0, 0);\n  border-radius: 0;\n  width: 100%;\n  height: 100%;\n}\n\n.slide .item:nth-child(2) .content {\n  display: block;\n}\n\n.slide .item:nth-child(3) {\n  left: 50%;\n}\n\n.slide .item:nth-child(4) {\n  left: calc(50% + 220px);\n}\n\n.slide .item:nth-child(5) {\n  left: calc(50% + 440px);\n}\n\n.slide .item:nth-child(n+6) {\n  left: calc(50% + 440px);\n  overflow: hidden;\n}\n\n.item .content {\n  position: absolute;\n  top: 50%;\n  left: 100px;\n  width: 300px;\n  text-align: left;\n  color: #eee;\n  transform: translate(0, -50%);\n  font-family: system-ui;\n  display: none;\n}\n\n.content .name {\n  font-size: 40px;\n  text-transform: uppercase;\n  font-weight: bold;\n  opacity: 0;\n  animation: animate 1s ease-in-out 1 forwards;\n}\n\n.content .description {\n  margin-top: 10px;\n  margin-bottom: 20px;\n  opacity: 0;\n  animation: animate 1s ease-in-out 0.3s 1 forwards;\n}\n\n.content button {\n  padding: 10px 20px;\n  border: none;\n  cursor: pointer;\n  opacity: 0;\n  animation: animate 1s ease-in-out 0.6s 1 forwards;\n}\n\n@keyframes animate {\n  from {\n  