n  /**\n   * Remove the inheritance of text transform in Edge, Firefox, and IE.\n   * 1. Remove the inheritance of text transform in Firefox.\n   */\n  \n  button,\n  select { /* 1 */\n    text-transform: none;\n  }\n  \n  /**\n   * Correct the inability to style clickable types in iOS and Safari.\n   */\n  \n  button,\n  [type=\"button\"],\n  [type=\"reset\"],\n  [type=\"submit\"] {\n    -webkit-appearance: button;\n  }\n  \n  /**\n   * Remove the inner border and padding in Firefox.\n   */\n  \n  button::-moz-focus-inner,\n  [type=\"button\"]::-moz-focus-inner,\n  [type=\"reset\"]::-moz-focus-inner,\n  [type=\"submit\"]::-moz-focus-inner {\n    border-style: none;\n    padding: 0;\n  }\n  \n  /**\n   * Restore the focus styles unset by the previous rule.\n   */\n  \n  button:-moz-focusring,\n  [type=\"button\"]:-moz-focusring,\n  [type=\"reset\"]:-moz-focusring,\n  [type=\"submit\"]:-moz-focusring {\n    outline: 1px dotted ButtonText;\n  }\n  \n  /**\n   * Correct the padding in Firefox.\n   */\n  \n  fieldset {\n    padding: 0.35em 0.75em 0.625em;\n  }\n  \n  /**\n   * 1. Correct the text wrapping in Edge and IE.\n   * 2. Correct the color inheritance from `fieldset` elements in IE.\n   * 3. Remove the padding so developers are not caught out when they zero out\n   *    `fieldset` elements in all browsers.\n   */\n  \n  legend {\n    box-sizing: border-box; /* 1 */\n    color: inherit; /* 2 */\n    display: table; /* 1 */\n    max-width: 100%; /* 1 */\n    padding: 0; /* 3 */\n    white-space: normal; /* 1 */\n  }\n  \n  /**\n   * Add the correct vertical alignment in Chrome, Firefox, and Opera.\n   */\n  \n  progress {\n    vertical-align: baseline;\n  }\n  \n  /**\n   * Remove the default vertical scrollbar in IE 10+.\n   */\n  \n  textarea {\n    overflow: auto;\n  }\n  \n  /**\n   * 1. Add the correct box sizing in IE 10.\n   * 2. Remove the padding in IE 10.\n   */\n  \n  [type=\"checkbox\"],\n  [type=\"radio\"] {\n    box-sizing: border-box; /* 1 */\n    padding: 0; /* 2 */\n  }\n  \n  /**\n   * Correct the cursor style of increment and decrement buttons in Chrome.\n   */\n  \n  [type=\"number\"]::-webkit-inner-spin-button,\n  [type=\"number\"]::-webkit-outer-spin-button {\n    height: auto;\n  }\n  \n  /**\n   * 1. Correct the odd appearance in Chrome and Safari.\n   * 2. Correct the outline style in Safari.\n   */\n  \n  [type=\"search\"] {\n    -webkit-appearance: textfield; /* 1 */\n    outline-offset: -2px; /* 2 */\n  }\n  \n  /**\n   * Remove the inner padding in Chrome and Safari on macOS.\n   */\n  \n  [type=\"search\"]::-webkit-search-decoration {\n    -webkit-appearance: none;\n  }\n  \n  /**\n   * 1. Correct the inability to style clickable types in iOS and Safari.\n   * 2. Change font properties to `inherit` in Safari.\n   */\n  \n  ::-webkit-file-upload-button {\n    -webkit-appearance: button; /* 1 */\n    font: inherit; /* 2 */\n  }\n  \n  /* Interactive\n     ========================================================================== */\n  \n  /*\n   * Add the correct display in Edge, IE 10+, and Firefox.\n   */\n  \n  details {\n    display: block;\n  }\n  \n  /*\n   * Add the correct display in all browsers.\n   */\n  \n  summary {\n    display: list-item;\n  }\n  \n  /* Misc\n     ========================================================================== */\n  \n  /**\n   * Add the correct display in IE 10+.\n   */\n  \n  template {\n    display: none;\n  }\n  \n  /**\n   * Add the correct display in IE 10.\n   */\n  \n  [hidden] {\n    display: none;\n  }\n  ","@use 'variables' as v;\n\n/** Media Queries **/\n@mixin telefono {\n    @media (min-width: v.$telefono) {\n        @content;\n    }\n}\n\n@mixin tablet {\n    @media (min-width: v.$tablet) {\n        @content;\n    }\n}\n\n@mixin desktop {\n    @media (min-width: v.$desktop) {\n        @content;\n    }\n}\n\n@mixin xl_desktop {\n    @media (min-width: v.$xl_desktop) {\n        @content;\n    }\n}\n\n@mixin boton($bgColor, $colorTexto) {\n    background-color: $bgColor;\n    padding: 1.5rem 4rem;\n    color: $colorTexto;\n    font-size: 1.8rem;\n    font-weight: 700;\n    border: none;\n    transition-property: background-color;\n    transition-duration: .3s;\n    text-align: center;\n    width: 100%;\n    display: inline-block;\n\n    &:hover {\n        background-color: darken($bgColor, 10%);\n        cursor: pointer;\n    }\n}\n\n@mixin grid($columnas, $espaciado ) {\n    display: grid;\n    gap: $espaciado;\n    grid-template-columns: repeat($columnas, 1fr);\n}\n\n@mixin contenedor {\n    width: min(95%, 140rem);\n    margin: 0 auto;\n}\n\n@mixin contenedor-l {\n    width: min(95%, 100rem);\n    margin: 0 auto;\n}\n\n@mixin contenedor-md {\n    width: min(95%, 80rem);\n    margin: 0 auto;\n}\n\n@mixin contenedor-sm {\n    width: min(95%, 60rem);\n    margin: 0 auto;\n}\n\n@mixin headings {\n    font-family: v.$fuente_principal;\n    font-weight: v.$black;\n    margin: 2rem 0;\n}\n\n@mixin nombre-pagina {\n    @include headings;\n    margin: 6rem 0 3rem 0;\n    text-align: center;\n}\n\n@mixin descripcion-pagina {\n    text-align: center;\n    font-size: 1.8rem;\n    font-weight: v.$delgada;\n    color: v.$gris-oscuro;\n    margin-bottom: 5rem;\n}\n\n@mixin texto-fluido($min, $max) {\n    font-size: clamp($min, -0.8rem + 10vw, $max);\n}\n\n@mixin texto-degradado($inicio, $final) {\n    background: linear-gradient(to right, $inicio, $final);\n    background-clip: text;\n    color: transparent;\n}\n\n@mixin logo {\n    color: v.$blanco;\n    text-align: center;\n    margin-bottom: 2rem;\n    white-space: nowrap; //evitar salto\n\n    @include desktop {\n        text-align: left;\n        margin: 0;\n    }\n}\n\n@mixin menu-social($color, $size) {\n\n    &__enlace {\n\n        &::before {\n            color: $color;\n            font-size: $size;\n            display: inline-block;\n            font-style: normal;\n            text-rendering: auto;\n            -webkit-font-smoothing: antialiased;\n            font-family: \"Font Awesome 6 Brands\";\n        }\n\n        &[href*=\"facebook.com\"]::before {\n            content: \"\\f39e\";\n        }\n\n        &[href*=\"github.com\"]::before {\n            content: \"\\f09b\";\n        }\n\n        &[href*=\"tiktok.com\"]::before {\n            content: \"\\e07b\";\n        }\n\n        &[href*=\"instagram.com\"]::before {\n            content: \"\\f16d\";\n        }\n\n        &[href*=\"youtube.com\"]::before {\n            content: \"\\f167\";\n        }\n\n        &[href*=\"twitter.com\"]::before {\n            content: \"\\f099\";\n        }\n    }\n\n    &__ocultar {\n        display: none;\n    }\n}\n\n@mixin enlace {\n    all: unset;\n    color: v.$blanco;\n    font-size: 1.4rem;\n    text-transform: uppercase;\n    font-weight: v.$bold;\n\n    &:hover {\n        color: v.$azul;\n        cursor: pointer;\n    }\n}\n\n@mixin shadow {\n    box-shadow: rgba(50, 50, 93, 0.25) 0px 13px 27px -5px, rgba(0, 0, 0, 0.3) 0px 8px 16px -8px;\n}\n\n@mixin shadow-lg {\n    box-shadow:\n        0 20px 35px rgba(0, 119, 182, 0.25),\n        0 10px 15px rgba(0, 0, 0, 0.15);\n}\n\n@mixin reset-lista {\n    margin: 0;\n    padding: 0;\n    list-style: none;\n}\n\n@mixin tags {\n    @include reset-lista;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 1.5rem;\n    margin-top: 1.5rem;\n\n    >li {\n        background-color: v.$azul;\n        padding: 1rem;\n        border-radius: .5rem;\n        font-size: 1.4rem;\n        font-weight: v.$bold;\n        color: v.$blanco;\n    }\n}\n\n@mixin card {\n    border: 1px solid lighten(v.$gris, 10);\n    padding: 3rem;\n\n    &__nombre {\n        font-weight: v.$black;\n        font-size: 2.6rem;\n        margin: 2rem 0;\n    }\n}\n\n@mixin bg-gradient($bg_color) {\n    background-image: linear-gradient(to left top, $bg_color, lighten($bg_color, 15%));\n}","@use 'variables' as v;\n@use 'mixins' as m;\n\nhtml {\n    font-size: 62.5%;\n    box-sizing: border-box;\n    height: 100%;\n}\n*, *:before, *:after {\n    box-sizing: inherit;\n}\nbody {\n    font-family: v.$fuente_principal;\n    font-size: 1.8rem;\n}\na {\n    text-decoration: none;\n}\nimg {\n    width: 100%;\n    height: auto;\n}\n.swal2-popup{\n    font-size: 2rem!important;\n}","// Fuentes\n$fuente-principal: 'Outfit', sans-serif;\n\n// Tamaño de Media Queries\n$telefono: 480px;\n$tablet: 768px;\n$desktop: 1024px;\n$xl_desktop: 1200px;\n\n// Colores\n$azul: #007df4;\n$secundario: #00c8c2;\n$celeste: #4ac4f5;\n\n$tecnico: #58d68d;\n\n$tesorero: #ec7063;\n\n$lecturador:#de1609;\n\n$primario: #0077b6;    \n$secundario: #00b4d8;  \n\n\n$negro: #1a1b15;\n$blanco: #FFFFFF;\n$gris: #64748B;\n$gris-claro: #F8FAFC;\n$gris-oscuro: #1E293B;\n\n$rojo: rgb(169, 0, 0);\n$verde: #02db02;\n$amarillo: #e5b214;\n\n\n// Fuentes\n$delgada: 300;\n$regular: 400;\n$bold: 700;\n$black: 900","@use 'variables' as v;\n@use 'mixins' as m;\n\nh1, h2, h3 {\n    @include m.headings;\n}\n\nh1 {\n    font-size: 4rem;\n}\nh2 {\n    font-size: 3.6rem;\n}\nh3 {\n    font-size: 3rem;\n}\n.text-center {\n    text-align: center;\n}\n\n[class$=\"__heading\"] {\n    @include m.nombre-pagina;\n}\n[class$=\"__descripcion\"] {\n    @include m.descripcion-pagina;\n}","@property --gradient-angle {\r\n    syntax: \"<angle>\";\r\n    initial-value: 0turn;\r\n    inherits: false;\r\n}\r\n\r\n.tarjeta {\r\n    animation: 2s gradient-angle infinite linear;\r\n    border: 2px solid transparent;\r\n    background-image: linear-gradient(#584827, #2d230f),\r\n        conic-gradient(from var(--gradient-angle),\r\n            #584827 0%,\r\n            #c7a03c 37%,\r\n            #f9de90 30%,\r\n            #c7a03c 33%,\r\n            #584827 40%,\r\n            #584827 50%,\r\n            #c7a03c 77%,\r\n            #f9de90 80%,\r\n            #c7a03c 83%,\r\n            #584827 90%);\r\n    background-clip: padding-box, border-box;\r\n    background-origin: padding-box, border-box;\r\n}\r\n\r\n@keyframes gradient-angle {\r\n    to {\r\n        --gradient-angle: 1turn;\r\n    }\r\n}\r\n\r\n/* その他 */\r\n.tarjetas {\r\n    background: #141819;\r\n}\r\n\r\n.tarjetas {\r\n    font-family: \"游ゴシック Medium\", YuGothic, YuGothicM,\r\n        \"Hiragino Kaku Gothic ProN\", Meiryo, sans-serif;\r\n    line-height: 1.6;\r\n    display: grid;\r\n    align-content: center;\r\n    min-height: 100svh;\r\n    padding: 24px;\r\n    color: #d5cec0;\r\n    gap: 24px;\r\n\r\n    @media (width < 970px) {\r\n        align-content: start;\r\n    }\r\n}\r\n\r\n.tarjetas__cuerpo {\r\n    display: grid;\r\n    justify-content: center;\r\n    margin-inline: auto;\r\n    grid-auto-flow: column;\r\n    gap: 16px 40px;\r\n\r\n    @media (width < 970px) {\r\n        grid-auto-flow: row;\r\n    }\r\n}\r\n\r\n.tarjeta {\r\n    display: grid;\r\n    max-width: 240px;\r\n    padding: 20px;\r\n    text-decoration: none;\r\n    color: currentColor;\r\n    border-radius: 20px;\r\n    place-content: center;\r\n    place-items: center;\r\n    aspect-ratio: 1/1;\r\n    row-gap: 16px;\r\n}\r\n\r\n.tarjeta h2 {\r\n    font-family: \"Comfortaa\", sans-serif;\r\n    font-size: 18px;\r\n    font-weight: 700;\r\n    font-style: normal;\r\n    font-optical-sizing: auto;\r\n}\r\n\r\n.tarjeta p {\r\n    font-size: 12px;\r\n}","*,\r\n*::after,\r\n*::before {\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n}\r\n\r\n.body-slider {\r\n    min-block-size: 68vh;\r\n    display: flex;\r\n    flex-direction: column;\r\n    justify-content: center;\r\n    align-items: center;\r\n    background-color: #e1e3e5;\r\n}\r\n\r\n.image-slider {\r\n    display: flex;\r\n    flex-flow: column;\r\n    width: clamp(360px, 96vw, 830px);\r\n    aspect-ratio: 16 / 9;\r\n    min-height: 300px;\r\n    overflow: hidden;\r\n    border-radius: 8px;\r\n    container-type: inline-size;\r\n    contain: content;\r\n    background-color: #0006;\r\n    box-shadow: rgba(0, 0, 0, 0.2) 0px 1px 2px, rgba(0, 0, 0, 0.3) 0px 2px 4px,\r\n        rgba(0, 0, 0, 0.25) 0px 4px 8px, rgba(0, 0, 0, 0.2) 0px 8px 16px,\r\n        rgba(0, 0, 0, 0.15) 0px 16px 32px;\r\n}\r\n\r\n.slider__content {\r\n    flex-grow: 1;\r\n    display: flex;\r\n    justify-content: space-between;\r\n}\r\n\r\n.slider-control--button {\r\n    border: 0;\r\n    background: 0;\r\n    outline: 0;\r\n    cursor: pointer;\r\n    place-content: center;\r\n    padding-inline: 3vw;\r\n    z-index: 1;\r\n    display: grid;\r\n}\r\n\r\n.icon {\r\n    height: 2rem;\r\n    width: 2rem;\r\n    fill: var(hsl(203 5 75));\r\n    border-radius: 50%;\r\n}\r\n\r\n.slider-control--button:where(:hover) {\r\n    background-image: linear-gradient(\r\n        to var(--position),\r\n        #0000 0%,\r\n        #0002,\r\n        80%,\r\n        #0006 100%\r\n    );\r\n    .icon {\r\n        fill: hsl(203 15 98);\r\n        background: #0001;\r\n    }\r\n}\r\n\r\n.slider-control--button:active {\r\n    outline: 0.2em solid hsl(204 100 53);\r\n    outline-offset: -0.5em;\r\n}\r\n\r\n.prev-button {\r\n    --position: left;\r\n}\r\n.next-button {\r\n    --position: right;\r\n}\r\n\r\n.image-display {\r\n    position: fixed;\r\n    inset: 0;\r\n}\r\n\r\n.slider-navigation {\r\n    z-index: 10;\r\n    display: grid;\r\n    grid-auto-flow: column;\r\n    grid-template-columns: repeat(6, 1fr);\r\n    grid-auto-columns: 100%;\r\n    gap: 1.25rem;\r\n    padding: 1rem;\r\n    place-content: center;\r\n    background-color: hsl(203 5 25 / 0.3);\r\n    backdrop-filter: blur(6px);\r\n}\r\n\r\n.nav-button {\r\n    display: grid;\r\n    width: 100%;\r\n    height: 100%;\r\n    border-radius: 0.5em;\r\n    overflow: hidden;\r\n    align-items: center;\r\n    justify-content: center;\r\n    border: 0;\r\n    aspect-ratio: 16 / 9;\r\n    transition: filter 150ms linear, scale 266ms ease;\r\n}\r\n\r\n.thumbnail {\r\n    display: block;\r\n    max-width: 100%;\r\n    width: 100%;\r\n    object-fit: cover;\r\n    height: 100%;\r\n}\r\n\r\n.nav-button[aria-selected=\"true\"] {\r\n    scale: 1.1;\r\n}\r\n\r\n.nav-button[aria-selected=\"true\"],\r\n.nav-button:focus-visible {\r\n    outline: 0.2em solid  hsl(204 100 53);\r\n    outline-offset: 0.2em;\r\n}\r\n\r\n.nav-button[aria-selected=\"false\"] {\r\n    filter: opacity(0.7);\r\n}\r\n\r\n.nav-button[aria-selected=\"false\"]:where(:hover, :focus-visible) {\r\n    filter: opacity(1);\r\n}\r\n\r\n@container (max-width: 660px) {\r\n    .nav-button:not(:has(img)) {\r\n        background-color: rgb(241, 235, 232);\r\n    }\r\n\r\n    .slider-navigation {\r\n        display: flex;\r\n        justify-content: center;\r\n        padding-block: 1.5em;\r\n    }\r\n\r\n    .nav-button {\r\n        inline-size: 0.625rem;\r\n        aspect-ratio: 1;\r\n        border-radius: 50%;\r\n    }\r\n\r\n    .nav-button > .thumbnail {\r\n        display: none;\r\n    }\r\n\r\n    .nav-button[aria-selected=\"true\"] {\r\n        background-color: black;\r\n        scale: 1.5;\r\n    }\r\n}\r\n","\r\n\r\n.carrusel {\r\n\r\n    background: #eaeaea;\r\n    overflow: hidden;\r\n    position: relative; /* Asegura que el carrusel permanezca dentro de esta sección */\r\n    height: 100vh; /* Asegura que cubra toda la pantalla si es necesario */\r\n\r\n\r\n}\r\n\r\n.carrusel_contenedor {\r\n    margin-top: 0;\r\n    position: relative; /* Mantiene el carrusel dentro de su sección */\r\n    top: 50%;\r\n    left: 50%;\r\n    transform: translate(-50%, -50%);\r\n    width: 1000px;\r\n    height: 600px;\r\n    background: #f5f5f5;\r\n    box-shadow: 0 30px 50px #dbdbdb;\r\n}\r\n\r\n\r\n.carrusel_contenedor .slide .item {\r\n    width: 200px;\r\n    height: 300px;\r\n    position: absolute;\r\n    top: 50%;\r\n    transform: translate(0, -50%);\r\n    border-radius: 20px;\r\n    box-shadow: 0 30px 50px #505050;\r\n    background-position: 50% 50%;\r\n    background-size: cover;\r\n    background-repeat: no-repeat;\r\n    display: inline-block;\r\n    transition: .5s;\r\n}\r\n\r\n.slide .item:nth-child(1),\r\n.slide .item:nth-child(2) {\r\n    top: 0;\r\n    left: 0;\r\n    transform: translate(0, 0);\r\n    border-radius: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n}\r\n\r\n.slide .item:nth-child(2) .content {\r\n    display: block;\r\n}\r\n\r\n.slide .item:nth-child(3) {\r\n    left: 50%;\r\n}\r\n\r\n.slide .item:nth-child(4) {\r\n    left: calc(50% + 220px);\r\n}\r\n\r\n.slide .item:nth-child(5) {\r\n    left: calc(50% + 440px);\r\n}\r\n\r\n.slide .item:nth-child(n + 6) {\r\n    left: calc(50% + 440px);\r\n    overflow: hidden;\r\n}\r\n\r\n.item .content {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 100px;\r\n    width: 300px;\r\n    text-align: left;\r\n    color: #eee;\r\n    transform: translate(0, -50%);\r\n    font-family: system-ui;\r\n    display: none;\r\n}\r\n\r\n.content .name {\r\n    font-size: 40px;\r\n    text-transform: uppercase;\r\n    font-weight: bold;\r\n    opacity: 0;\r\n    animation: animate 1s ease-in-out 1 forwards;\r\n}\r\n\r\n.content .description {\r\n    margin-top: 10px;\r\n    margin-bottom: 20px;\r\n    opacity: 0;\r\n    animation: animate 1s ease-in-out .3s 1 forwards;\r\n}\r\n\r\n.content button {\r\n    padding: 10px 20px;\r\n    border: none;\r\n    cursor: pointer;\r\n    opacity: 0;\r\n    animation: animate 1s ease-in-out .6s 1 forwards;\r\n}\r\n\r\n@keyframes animate {\r\n    from {\r\n        opacity: 0;\r\n        transform: translate(0, 100px);\r\n        filter: blur(33px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translate(0);\r\n        filter: blur(0);\r\n    }\r\n}\r\n\r\n.button {\r\n    width: 100%;\r\n    text-align: center;\r\n    position: absolute;\r\n    bottom: 20px;\r\n}\r\n\r\n.button button {\r\n    width: 40px;\r\n    height: 35px;\r\n    border-radius: 8px;\r\n    border: none;\r\n    cursor: pointer;\r\n    margin: 0 5px;\r\n    border: 1px solid #000;\r\n    transition: .3s;\r\n}\r\n\r\n.button button:hover {\r\n    background: #ababab;\r\n    color: #fff;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n\r\n.cloneable {\r\n    margin: 5rem 0 5rem 0;\r\n    padding: var(--container-padding);\r\n    justify-content: center;\r\n    align-items: center;\r\n    min-height: 15rem;\r\n    display: flex;\r\n    position: relative;\r\n}\r\n\r\n.looping-words {\r\n    height: 2.7em;\r\n    padding-left: 0.1em;\r\n    padding-right: 0.1em;\r\n    font-size: 10rem;\r\n    line-height: 0.9;\r\n    position: relative;\r\n    color: v.$azul;\r\n}\r\n\r\n.looping-words__list {\r\n    text-align: center;\r\n    text-transform: uppercase;\r\n    white-space: nowrap;\r\n    flex-flow: column;\r\n    align-items: center;\r\n    margin: 0;\r\n    padding: 0;\r\n    font-family: PP Neue Corp, sans-serif;\r\n    font-weight: 700;\r\n    list-style: none;\r\n    display: flex;\r\n    position: relative;\r\n}\r\n\r\n.looping-words__list.is--primary {\r\n    color: v.$rojo;\r\n}\r\n\r\n.looping-words__list.is--gray {\r\n    color: v.$rojo;\r\n}\r\n\r\n.looping-words__fade {\r\n    background-image: linear-gradient(180deg,\r\n            var(--color-neutral-300) 5%,\r\n            transparent 40%,\r\n            transparent 60%,\r\n            var(--color-neutral-300) 95%);\r\n    pointer-events: none;\r\n    width: 100%;\r\n    height: 100%;\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n}\r\n\r\n.looping-words__fade.is--radial {\r\n    background-image: radial-gradient(circle closest-side at 50% 50%,\r\n            transparent 64%,\r\n            v.$rojo 93%);\r\n    width: 140%;\r\n    display: block;\r\n    left: -20%;\r\n}\r\n\r\n.looping-words__selector {\r\n    pointer-events: none;\r\n    width: 100%;\r\n    height: 0.9em;\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    transform: translate(-50%, -50%);\r\n}\r\n\r\n.looping-words__edge {\r\n    border-top: 0.035em solid v.$rojo;\r\n    border-left: 0.035em solid v.$rojo;\r\n    width: 0.125em;\r\n    height: 0.125em;\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n}\r\n\r\n.looping-words__edge.is--2 {\r\n    left: auto;\r\n    right: 0;\r\n    transform: rotate(90deg);\r\n}\r\n\r\n.looping-words__edge.is--3 {\r\n    inset: auto 0 0 auto;\r\n    transform: rotate(180deg);\r\n}\r\n\r\n.looping-words__edge.is--4 {\r\n    top: auto;\r\n    bottom: 0;\r\n    transform: rotate(270deg);\r\n}\r\n\r\n.looping-words__containers {\r\n    width: 100%;\r\n    height: 100%;\r\n    position: relative;\r\n    overflow: hidden;\r\n}\r\n\r\n.looping-words__p {\r\n    margin: 0;\r\n}\r\n\r\n@font-face {\r\n    font-family: \"PP Neue Corp\";\r\n    src: url(\"https://cdn.prod.website-files.com/6717aac16c9ea22eeef1e79e/6717de2d56e40b921572d2d9_PPNeueCorp-TightUltrabold.woff2\") format(\"woff2\");\r\n    font-weight: 700;\r\n    font-style: normal;\r\n    font-display: swap;\r\n}","@use 'base/mixins' as m;\r\n\r\n.auth {\r\n    @include m.grid(2, 2rem);\r\n\r\n    &__1 {\r\n        @include m.contenedor-sm;\r\n        padding-bottom: 10rem;\r\n    }\r\n\r\n    &__2 {\r\n        @include m.contenedor-sm;\r\n        padding-top: 10rem;\r\n        padding-bottom: 10rem;\r\n    }\r\n    &__3 {\r\n        @include m.contenedor-sm;\r\n        padding-top: 10rem;\r\n        padding-bottom: 20rem;\r\n    }\r\n    &__4 {\r\n        @include m.contenedor-sm;\r\n        padding-top: 10rem;\r\n        padding-bottom: 30rem;\r\n    }\r\n}\r\n\r\n\r\n.auth__texto {\r\n    font-size: 2rem;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.devwebcamp {\r\n\r\n    padding-bottom:6rem;\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 3rem);\r\n        @include m.tablet {\r\n            @include m.grid(2, 5rem);\r\n            align-items: center;\r\n        }\r\n    }\r\n\r\n    &__texto {\r\n        line-height: 2;\r\n    }\r\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.paquetes {\n\n    &__grid {\n        padding-bottom: 20rem;\n        @include m.contenedor;\n        @include m.grid(1, 3rem);\n\n        @include m.tablet {\n            @include m.grid(3, 3rem);\n            align-items: flex-start;\n        }\n    }\n\n    &__submit {\n        @include m.boton(v.$azul, v.$blanco);\n        margin-top: 3rem;\n    }\n}\n\n.paquete {\n    @include m.card;\n\n    &:nth-child(2) {\n        order: -1; //ordenar en celular el paquete mas caro es el primero \n\n        @include m.tablet {\n            order: unset;\n        }\n    }\n\n    &__lista {\n        @include m.reset-lista;\n        line-height: 2;\n    }\n\n    &__precio {\n        font-size: 6rem;\n        margin: 3rem 0;\n        color: v.$azul;\n        font-weight: v.$black;\n        text-align: center;\n    }\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.agenda {\r\n    padding: 6rem 0;\r\n    @include m.contenedor;\r\n}\r\n\r\n.eventos {\r\n    $modificador: &; //cambio de color a titulo workshops\r\n\r\n    &__heading {\r\n        color: v.$azul;\r\n        margin: 5rem 0;\r\n        text-align: left;\r\n        font-size: clamp(2rem, -0.8rem + 8vw, 6rem);\r\n    }\r\n\r\n    &__fecha {\r\n        color: v.$gris;\r\n        margin: 3rem 0 1rem 0;\r\n    }\r\n\r\n    &--workshops {\r\n\r\n        #{$modificador}__heading {\r\n            //cambio de color de workshops\r\n            color: v.$secundario;\r\n        }\r\n\r\n        .evento__informacion {\r\n            background-color: v.$secundario;//cambiar de color\r\n\r\n            &:hover {\r\n                background-color: darken(v.$secundario, 10%);\r\n            }\r\n        }\r\n    }\r\n\r\n    .swiper-button-next,\r\n    .swiper-button-prev {\r\n        color: rgba(v.$blanco, .5);\r\n    }\r\n\r\n    .swiper-pagination {\r\n        position: relative;\r\n        margin-top: 2rem;\r\n\r\n        /* ajusta el valor según sea necesario */\r\n        &--conferencias {\r\n            color: darken(v.$azul, 20%);\r\n\r\n        }\r\n        &--workshops {\r\n            color: darken(v.$secundario, 20%);\r\n        }\r\n\r\n    }\r\n}\r\n\r\n.evento {\r\n    \r\n    &__hora {\r\n        font-weight: v.$bold;\r\n    }\r\n    &__enlace{\r\n        all: unset;\r\n    }\r\n    &__informacion {\r\n        padding: 2rem;\r\n        border-radius: 1rem;\r\n        background-color: v.$azul;\r\n        color: v.$blanco;\r\n        transition: 300ms background-color ease;\r\n\r\n        &:hover {\r\n            background-color: darken(v.$azul, 10%);\r\n        }\r\n    }\r\n\r\n    &__nombre {\r\n        font-size: 2rem;\r\n        margin: 0;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 1;\r\n        -webkit-box-orient: vertical;\r\n        overflow: hidden;\r\n    }\r\n\r\n    &__introduccion {\r\n        //recortar texto\r\n        font-size: 1.6rem;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 2; //cuantas lineas de texto quieres\r\n        -webkit-box-orient: vertical;\r\n        overflow: hidden;\r\n    }\r\n\r\n    &__autor-info {\r\n        display: flex;\r\n        gap: 2rem;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n    }\r\n\r\n    &__imagen-autor {\r\n        width: 5rem;\r\n        background-color: v.$blanco;\r\n        border-radius: 50%;\r\n    }\r\n\r\n    &__autor-nombre {\r\n        font-weight: v.$bold;\r\n    }\r\n    &__agregar {\r\n        @include m.boton(v.$blanco,v.$negro);\r\n        margin-top: 1rem;\r\n    }\r\n\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.resumen {\r\n    background-image: linear-gradient(to right, rgba(v.$azul, .7), rgba(v.$azul, .9)), url(../img/resumen_index.jpg);\r\n    background-image: linear-gradient(to right, rgba(v.$azul, .7), rgba(v.$azul, .9)), image-set(\r\n        url('../img/resumen_index.avif') 1x,\r\n        url('../img/resumen_index.webp') 1x,\r\n        url('../img/resumen_index.jpg') 1x,\r\n    );\r\n    padding: 12rem 0;\r\n    background-size: cover;\r\n    background-position: center;\r\n\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 5rem);\r\n        @include m.tablet {\r\n            @include m.grid(2, 5rem);\r\n        }\r\n    }\r\n\r\n    &__bloque {\r\n        text-align: center;\r\n        color: v.$blanco;\r\n    }\r\n\r\n    &__texto {\r\n        font-weight: v.$black;\r\n        line-height: 1;\r\n        margin: 0;\r\n        font-size: 2.4rem;\r\n        text-transform: uppercase;\r\n\r\n        &--numero {\r\n            @extend .resumen__texto;\r\n            font-size: 8rem;\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.speakers {\r\n    margin-bottom: 6rem;\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 5rem);\r\n        @include m.tablet {\r\n            @include m.grid(2, 5rem);\r\n        }\r\n        @include m.xl_desktop {\r\n            @include m.grid(3, 5rem);\r\n        }\r\n    }\r\n}\r\n\r\n.speaker {\r\n    @include m.card;\r\n    background-position: center top;\r\n    background-size: 350px;\r\n    background-repeat: no-repeat;\r\n\r\n    @for $i from 1 through 4 {//fondos aleatorios \r\n        &:nth-child(4n + #{$i}) {\r\n            background-image: image-set(\r\n                url('../img/bg_#{$i}.avif') 1x,\r\n                url('../img/bg_#{$i}.webp') 1x,\r\n                url('../img/bg_#{$i}.png') 1x\r\n            );\r\n        }\r\n    }\r\n\r\n    &__imagen {\r\n        min-width: 350px;\r\n        @include m.tablet {\r\n            min-width: unset;\r\n        }\r\n    }\r\n\r\n    &__ubicacion {\r\n        color: v.$gris;\r\n        margin: 1rem 0;\r\n        font-size: 2rem;\r\n        line-height: 1.5;\r\n    }\r\n    &__listado-skills {\r\n        @include m.tags;\r\n    }\r\n}\r\n\r\n.speaker-sociales {\r\n    @include m.menu-social(v.$negro, 3rem);\r\n    display: flex;\r\n    gap: 2rem;\r\n    margin-top: 2rem;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.mapa {\r\n    padding-top: 3rem;\r\n\r\n    &__heading {\r\n        margin: 0;\r\n        text-align: center;\r\n        margin-bottom: 2rem;\r\n\r\n    }\r\n\r\n    &__texto {\r\n        font-size: 1.8rem;\r\n        margin: 0;\r\n        padding-bottom: 2rem\r\n    }\r\n\r\n    &__descripcion {\r\n        @include m.contenedor-md;\r\n        text-align: justify;\r\n    }\r\n    &__mapa{\r\n        height: 45rem;\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.masinformacion {\r\n    padding-bottom: 6rem;\r\n\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(2, 3rem);\r\n\r\n    }\r\n}\r\n\r\n.masinformacion__informacion {\r\n\r\n    @include m.contenedor-sm;\r\n    \r\n\r\n    @include m.card;\r\n    background-position: center top;\r\n    background-size: 250px;\r\n    background-repeat: no-repeat;\r\n    background-image: image-set(url('../img/bg_4.avif') 1x,\r\n            url('../img/bg_4.webp') 1x,\r\n            url('../img/bg_4.png') 1x);\r\n\r\n\r\n\r\n    &__imagen {\r\n        max-width: 90rem;\r\n        max-height: 90rem;\r\n    }\r\n\r\n    &__texto {\r\n        text-align: justify;\r\n        line-height: 2;\r\n\r\n    }\r\n\r\n\r\n\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.boletos {\r\n    margin-bottom: 10rem;\r\n\r\n    &__grid {\r\n        @include m.contenedor-sm;\r\n        @include m.grid(1, 5rem);\r\n    }\r\n}\r\n\r\n.boleto {\r\n    width: min(100% - 5rem, 65rem);\r\n    margin: 0 auto;\r\n    padding: 6rem;\r\n    border-radius: 2rem;\r\n    color: v.$blanco;\r\n    position: relative;\r\n\r\n    &::before,\r\n    &::after {\r\n        position: absolute;\r\n        content: '';\r\n        background-color: v.$blanco;\r\n        width: 5rem;\r\n        height: 5rem;\r\n        top: calc(50% - 2.5rem); //en el centro\r\n    }\r\n\r\n    &::before {\r\n        clip-path: circle(50% at 25% 50%);\r\n        left: 0; //pegado a la izquierda\r\n    }\r\n\r\n    &::after {\r\n        clip-path: circle(50% at 75% 50%);\r\n        right: 0; //pegado a la derecha\r\n    }\r\n\r\n    &--presencial {\r\n        background-color: hsla(178, 100%, 39%, 1);\r\n        background-image:\r\n            radial-gradient(at 40% 20%, hsla(209, 100%, 47%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 80% 0%, hsla(178, 100%, 39%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 69% 82%, hsla(209, 100%, 47%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 26% 91%, hsla(178, 100%, 39%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 100%, hsla(209, 100%, 47%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 27% 22%, hsla(178, 100%, 39%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 0%, hsla(209, 100%, 47%, 1) 0px, transparent 50%);\r\n    }\r\n\r\n    &--virtual {\r\n        background-color: v.$secundario;\r\n    }\r\n\r\n    &--gratis {\r\n        background-color: v.$azul;\r\n    }\r\n    &--pendiente {\r\n        background-color: hsla(39, 100%, 50%, 1); // Amarillo intenso\r\n    }\r\n    \r\n    &--aprobado {\r\n        background-color: hsla(120, 100%, 40%, 1); // Verde intenso\r\n    }\r\n    \r\n    &--rechazado {\r\n        background-color: hsla(0, 100%, 50%, 1); // Rojo vibrante\r\n    }\r\n    \r\n    &--proceso {\r\n        background-color: hsla(220, 100%, 50%, 1); // Azul fuerte\r\n    }\r\n    \r\n    &--realizado {\r\n        background-color: hsla(260, 100%, 50%, 1); // Púrpura brillante\r\n    }\r\n    \r\n    \r\n\r\n\r\n\r\n    &__logo {\r\n        @include m.logo;\r\n        @include m.texto-fluido(2rem, 4rem);\r\n    }\r\n\r\n    &__plan {\r\n        font-size: 2rem;\r\n        text-transform: uppercase;\r\n        margin: 3rem 0 0 0;\r\n    }\r\n    &__observacion {\r\n        font-size: 1.5rem;\r\n        text-transform: uppercase;\r\n        margin: 1rem 0 0 0;\r\n    }\r\n\r\n    &__precio {\r\n        margin: 3rem 0 0 0;\r\n        font-weight: v.$black;\r\n        font-size: 4rem;\r\n    }\r\n\r\n    &__enlace-contenedor {\r\n        margin-top: 5rem;\r\n        display: flex;\r\n        justify-content: center;\r\n    }\r\n\r\n    &__enlace {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        width: auto;\r\n    }\r\n\r\n    $modificador: &;\r\n\r\n    &--acceso {\r\n        width: 30rem;\r\n        height: 50rem;\r\n        padding: 10rem 3rem;\r\n\r\n        @include m.tablet {\r\n            width: 60rem;\r\n            height: 30rem;\r\n            padding: 6rem;\r\n            display: flex;\r\n            flex-direction: column;\r\n            justify-content: center;\r\n\r\n        }\r\n\r\n        #{$modificador}__logo {\r\n            @include m.texto-fluido(2rem, 3rem);\r\n            margin: 0;\r\n            text-align: left;\r\n\r\n        }\r\n\r\n        #{$modificador}__nombre {\r\n            font-size: 2.4rem;\r\n            text-transform: uppercase;\r\n            font-weight: v.$black;\r\n\r\n        }\r\n\r\n        #{$modificador}__codigo {\r\n            font-size: 3rem;\r\n            font-weight: bold;\r\n            text-align: center;\r\n            position: absolute;\r\n            bottom: 7rem;\r\n            margin: 0;\r\n            left: 0;\r\n            width: 100%;\r\n\r\n            @include m.tablet {\r\n\r\n                rotate: 90deg;\r\n                transform-origin: 0 0;//resetear posicion absoluta\r\n                width: 30rem;\r\n                top: 0;\r\n                left: calc(100% - 5rem);\r\n\r\n            }\r\n        }\r\n\r\n    }\r\n\r\n    &::before {\r\n        clip-path: circle(50% at 50% 25%);\r\n        left: calc(50% - 2.5rem);\r\n        top: 0;\r\n\r\n        @include m.tablet {\r\n            clip-path: circle(50% at 25% 50%);\r\n            left: 0; //pegado a la izquierda\r\n            top: calc(50% - 2.5rem); //en el centro\r\n\r\n        }\r\n    }\r\n\r\n    &::after {\r\n        clip-path: circle(50% at 50% 75%);\r\n        left: calc(50% - 2.5rem);\r\n        top: calc(100% - 5rem);\r\n\r\n        @include m.tablet {\r\n            clip-path: circle(50% at 75% 50%);\r\n            left: calc(100% - 5rem);\r\n            top: calc(50% - 2.5rem); //en el centro\r\n        }\r\n    }\r\n\r\n}\r\n\r\n.boleto-virtual {\r\n    margin-bottom: 6rem;\r\n}","@use 'base/variables' as v;\r\n\r\n.pagina_404 {\r\n\r\n    min-height: 60rem;\r\n    margin-top: 0;\r\n    \r\n    background-image: image-set(\r\n        url(../img/404.avif) 1x,\r\n        url(../img/404.webp) 1x,\r\n        url(../img/404.jpg) 1x\r\n    );\r\n    \r\n    background-repeat: no-repeat;\r\n    background-size: cover;\r\n    background-position: center;\r\n\r\n    &__contenedor {\r\n\r\n        text-align: center;\r\n    }\r\n\r\n    &__heading {\r\n        margin-top: 0;\r\n        color: v.$blanco;\r\n        padding-top: 3rem;\r\n    }\r\n\r\n    &__texto {\r\n        color: v.$blanco;\r\n        font-size: 2rem;\r\n        margin-bottom: 2rem;\r\n\r\n    }\r\n\r\n    &__enlace {\r\n        color: v.$azul;\r\n        font-size: 3rem;\r\n    }\r\n \r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.nosotros {\r\n\r\n    padding-bottom:6rem;\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 3rem);\r\n        @include m.tablet {\r\n            @include m.grid(2, 5rem);\r\n            align-items: center;\r\n        }\r\n    }\r\n\r\n    &__texto {\r\n        line-height: 2;\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.quehacemos {\r\n\r\n    &__grid {\r\n        padding-bottom: 20rem;\r\n        @include m.contenedor;\r\n        @include m.grid(1, 3rem);\r\n\r\n        @include m.tablet {\r\n            @include m.grid(3, 3rem);\r\n            align-items: flex-start;\r\n        }\r\n    }\r\n\r\n    &__submit {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        margin-top: 3rem;\r\n    }\r\n\r\n    &__descripcion{\r\n        text-align: center;\r\n        font-size: 1.8rem;\r\n        font-weight: v.$delgada;\r\n        color: v.$gris-oscuro;\r\n        margin-bottom: 5rem;\r\n    }\r\n}\r\n\r\n.hacemos {\r\n    @include m.card;\r\n\r\n    &:nth-child(2) {\r\n        order: -1; //ordenar en celular el paquete mas caro es el primero \r\n\r\n        @include m.tablet {\r\n            order: unset;\r\n        }\r\n    }\r\n\r\n    &__lista {\r\n        @include m.reset-lista;\r\n        line-height: 2;\r\n    }\r\n\r\n\r\n    i {\r\n        margin-top: 2rem;\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        color: v.$azul;\r\n        font-size: 6rem;\r\n\r\n    }\r\n    &__imagen {\r\n        padding-top: 3rem;\r\n        margin: 0 auto;\r\n        max-width: 20rem;\r\n\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.agenda {\r\n    padding: 6rem 0;\r\n    @include m.contenedor;\r\n}\r\n\r\n.noticias {\r\n    $modificador: &; //cambio de color a titulo workshops\r\n\r\n    &__heading {\r\n        color: v.$azul;\r\n        margin: 5rem 0;\r\n        text-align: center;\r\n        font-size: clamp(2rem, -0.8rem + 8vw, 6rem);\r\n    }\r\n\r\n    &__fecha {\r\n        color: v.$gris;\r\n        margin: 3rem 0 1rem 0;\r\n    }\r\n\r\n\r\n\r\n    .swiper-button-next,\r\n    .swiper-button-prev {\r\n        color: v.$secundario;\r\n    }\r\n\r\n    .swiper-pagination {\r\n        position: relative;\r\n        margin-top: 2rem;\r\n    }\r\n}\r\n\r\n.noticia {\r\n    \r\n    &__enlace{\r\n        all: unset;\r\n    }\r\n    &__informacion {\r\n        padding: 2rem;\r\n        border-radius: 1rem;\r\n        background-color: v.$azul;\r\n        color: v.$blanco;\r\n        transition: 300ms background-color ease;\r\n\r\n        &:hover {\r\n            background-color: darken(v.$azul, 10%);\r\n        }\r\n    }\r\n    &__imagen{\r\n\r\n        margin-left: 0.2rem;\r\n        margin-top: 3rem;\r\n        width: 40rem;\