ttom: 1px solid #ccc;\r\n    }\r\n\r\n    &__nota {\r\n        font-size: 1.5rem;\r\n        color: #666;\r\n        text-align: center;\r\n        margin-top: 1rem;\r\n    }\r\n\r\n    &__botones {\r\n        padding: 2rem 0;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 1rem;\r\n        justify-content: center;\r\n    }\r\n\r\n    &__boton {\r\n        background-color: v.$azul;\r\n        padding: 1.5rem 4rem;\r\n        color: v.$blanco;\r\n        font-size: 1.8rem;\r\n        font-weight: 700;\r\n        border: none;\r\n        transition-property: background-color;\r\n        transition-duration: .3s;\r\n        text-align: center;\r\n        width: 30rem;\r\n        display: inline-block;\r\n        border-radius: 1rem;\r\n\r\n        &:hover {\r\n            background-color: v.$celeste;\r\n            cursor: pointer;\r\n        }\r\n    }\r\n\r\n}\r\n\r\n.nuevaconexion__formulario {\r\n    background-color: v.$blanco;\r\n\r\n    margin-top: 5rem;\r\n    @include m.contenedor;\r\n\r\n    &__boton {\r\n        margin: 0 auto;\r\n        margin-top: 2rem;\r\n        background-color: v.$azul;\r\n        padding: 1.5rem 4rem;\r\n        color: v.$blanco;\r\n        font-size: 1.8rem;\r\n        font-weight: 700;\r\n        border: none;\r\n        transition-property: background-color;\r\n        transition-duration: .3s;\r\n        text-align: center;\r\n        width: 30rem;\r\n        display: inline-block;\r\n        border-radius: 1rem;\r\n\r\n        &:hover {\r\n            background-color: v.$celeste;\r\n            cursor: pointer;\r\n        }\r\n\r\n        &--rechazar {\r\n            background-color: v.$rojo;\r\n        }\r\n\r\n        &--asignar {\r\n            background-color: hsla(39, 100%, 50%, 1); // Amarillo intenso\r\n        }\r\n        &--aceptar {\r\n            background-color: v.$verde;\r\n        }\r\n\r\n    }\r\n}\r\n\r\n.nuevaconexion__contenedor-botones {\r\n    @include m.grid(1, 2rem);\r\n\r\n    @include m.tablet {\r\n        @include m.grid(2, 2rem);\r\n    }\r\n\r\n}\r\n\r\n.nuevaconexion__modal {\r\n    display: none;\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: rgba(0, 0, 0, 0.5);\r\n    justify-content: center;\r\n    align-items: center;\r\n    z-index: 1000;\r\n\r\n    &--contenido {\r\n        background: v.$blanco;\r\n        padding: 2rem;\r\n        width: 90%;\r\n        max-width: 600px;\r\n        border-radius: 10px;\r\n        box-shadow: 0px 5px 15px rgba(0, 0, 0, 0.2);\r\n        text-align: center;\r\n        animation: fadeIn 0.3s ease-in-out;\r\n\r\n        h2 {\r\n            font-size: 3rem;\r\n            color: v.$negro;\r\n            margin-bottom: 1rem;\r\n        }\r\n\r\n        p {\r\n            font-size: 2rem;\r\n            color: v.$gris-oscuro;\r\n            margin-bottom: 1.5rem;\r\n            line-height: 1.5;\r\n        }\r\n\r\n        .requisitos__boton {\r\n            background-color: v.$azul;\r\n            color: v.$blanco;\r\n            padding: 10px 20px;\r\n            border: none;\r\n            border-radius: 5px;\r\n            cursor: pointer;\r\n            transition: background 0.3s ease-in-out;\r\n\r\n            &:hover {\r\n                background-color: v.$celeste;\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n// Animación para la aparición del modal\r\n@keyframes fadeIn {\r\n    from {\r\n        opacity: 0;\r\n        transform: scale(0.9);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: scale(1);\r\n    }\r\n}\r\n\r\n.formulario_nueva_conexion__fieldset {\r\n    @include m.grid(2, 1rem);\r\n\r\n    @include m.desktop {\r\n        @include m.grid(3, 1rem);\r\n    }\r\n}\r\n\r\n.estadoconexion {\r\n    &__contenedor {\r\n        @include m.contenedor-sm;\r\n        padding-left: 10rem;\r\n\r\n        &--ticket {\r\n            @include m.contenedor;\r\n            margin-bottom: 10rem;\r\n        }\r\n    }\r\n\r\n    &__formulario {\r\n        @include m.contenedor-sm;\r\n\r\n        @include m.tablet {\r\n            display: flex;\r\n            justify-content: start;\r\n            margin-bottom: 5rem;\r\n        }\r\n    }\r\n\r\n    &__boton-buscador {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        margin: 3rem;\r\n        margin-left: 1rem;\r\n        text-transform: uppercase;\r\n        font-size: 1.4rem;\r\n\r\n        @include m.tablet {\r\n            width: auto;\r\n        }\r\n    }\r\n\r\n    &__contenedor-boton {\r\n        padding-top: 2.5rem;\r\n    }\r\n}\r\n\r\n.modalnuevaconexion {\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: rgba(0, 0, 0, 0.5);\r\n    display: none;\r\n    justify-content: center;\r\n    align-items: center;\r\n}\r\n.modalnuevaconexion-contenido {\r\n    background: white;\r\n    padding: 20px;\r\n    border-radius: 5px;\r\n    text-align: center;\r\n    display: flex;\r\n    flex-direction: column;\r\n    \r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.recibo {\r\n    &__contenedor {\r\n        padding-bottom: 15rem;\r\n        @include m.contenedor-l;\r\n    }\r\n\r\n    &__heading {\r\n        font-size: 3rem;\r\n        text-align: center;\r\n        color: v.$primario;\r\n        margin-bottom: 3rem;\r\n        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.2);\r\n    }\r\n\r\n    &__contenido {\r\n        padding: 3rem;\r\n        border-radius: 2rem;\r\n        background: linear-gradient(to right, #ffffff, #f0f4ff);\r\n        border: 2px solid v.$secundario;\r\n        @include m.shadow-lg;\r\n        display: grid;\r\n        grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\r\n        gap: 3rem;\r\n    }\r\n\r\n    &__datos,\r\n    &__contribuyente,\r\n    &__consumo {\r\n        background-color: #fff;\r\n        padding: 2rem;\r\n        border-radius: 1.5rem;\r\n        border-left: 8px solid v.$primario;\r\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\r\n\r\n        &:hover {\r\n            transform: translateY(-5px);\r\n            box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.15);\r\n        }\r\n    }\r\n\r\n    &__subtitulo {\r\n        font-size: 2rem;\r\n        color: v.$secundario;\r\n        margin-bottom: 1.5rem;\r\n        border-bottom: 2px solid v.$secundario;\r\n        padding-bottom: 0.5rem;\r\n    }\r\n\r\n    &__dato {\r\n        font-size: 1.6rem;\r\n        margin-bottom: 1rem;\r\n        color: #333;\r\n        line-height: 1.6;\r\n        padding-left: 0.5rem;\r\n        position: relative;\r\n\r\n        &::before {\r\n            content: \"•\";\r\n            color: v.$primario;\r\n            position: absolute;\r\n            left: 0;\r\n        }\r\n    }\r\n\r\n    &__label {\r\n        font-weight: bold;\r\n        color: v.$negro;\r\n    }\r\n\r\n    &__mensaje {\r\n        background-color: v.$secundario;\r\n        color: v.$blanco;\r\n        padding: 2rem;\r\n        margin: 2rem 0;\r\n        border-left: 1rem solid v.$primario;\r\n        border-radius: 1rem;\r\n        font-size: 2.4rem;\r\n        font-weight: bold;\r\n        text-align: center;\r\n        text-transform: uppercase;\r\n        @include m.shadow;\r\n\r\n        animation: mensajeAnimado 0.8s ease-in-out both;\r\n    }\r\n}\r\n\r\n@keyframes mensajeAnimado {\r\n    0% {\r\n        transform: scale(0.8);\r\n        opacity: 0;\r\n    }\r\n\r\n    100% {\r\n        transform: scale(1);\r\n        opacity: 1;\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.formulario {\r\n\r\n    display: flex;\r\n    flex-direction: column;\r\n\r\n    &__fieldset {\r\n        border: none;\r\n        margin-top: 1rem;\r\n        padding: 0;\r\n    }\r\n\r\n    &__legend {\r\n        color: v.$gris;\r\n        font-size: 2.2rem;\r\n        margin-bottom: 2rem;\r\n    }\r\n\r\n    &__campo {\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 1rem;\r\n        margin: 1.5rem 0;\r\n    }\r\n\r\n    &__contenedor-icono {\r\n        display: flex;\r\n        border-radius: .5rem;\r\n        overflow: hidden;\r\n    }\r\n\r\n    &__icono {\r\n        background-color: v.$gris-oscuro;\r\n        width: 4rem;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n\r\n        i {\r\n            color: v.$blanco;\r\n            font-size: 2rem;\r\n        }\r\n    }\r\n\r\n    &__label {\r\n        display: block;\r\n        font-size: 1.8rem;\r\n        color: rgba(v.$negro, .8);\r\n    }\r\n\r\n    &__input,\r\n    &__select {\r\n        padding: 1rem;\r\n        border: 1px solid darken(v.$gris-claro, 20);\r\n        border-radius: .5rem;\r\n\r\n        &--file {\r\n            border: none;\r\n        }\r\n\r\n        &--sociales {\r\n            @extend .formulario__input;\r\n            flex: 1;\r\n            border-top-left-radius: 0;\r\n            border-bottom-left-radius: 0;\r\n        }\r\n    }\r\n\r\n    &__radio {\r\n        display: flex;\r\n        gap: 2rem;\r\n    }\r\n\r\n    &__texto {\r\n        margin-top: 3rem;\r\n    }\r\n\r\n    &__imagen {\r\n        max-width: 20rem;\r\n    }\r\n\r\n    &__listado {\r\n        @include m.tags;\r\n    }\r\n\r\n    &__submit {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        width: auto;\r\n        align-self: flex-start;\r\n\r\n        &--registrar,\r\n        &--full {\r\n            width: 100%;\r\n        }\r\n\r\n        &--registrarU {\r\n            width: 100%;\r\n            @include m.boton(v.$celeste, v.$blanco);\r\n\r\n        }\r\n    }\r\n}\r\n\r\n","@use 'base/variables' as v;\r\n\r\n.acciones {\r\n    margin-top: 3rem;\r\n    display: flex;\r\n    justify-content: space-between;\r\n\r\n    &--centrar {\r\n        @extend .acciones;\r\n        justify-content: center;\r\n    }\r\n\r\n    &__enlace {\r\n        color: v.$negro;\r\n        font-size: 1.4rem;\r\n        font-weight: v.$delgada;\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.horas {\r\n    @include m.reset-lista;\r\n    @include m.grid(1, 1rem);\r\n    @include m.tablet {\r\n        @include m.grid(2, 1rem);\r\n    }\r\n\r\n    &__hora {\r\n        color: v.$azul;\r\n        border: 1px solid v.$azul;\r\n        border-radius: 1rem;\r\n        padding: 1rem;\r\n        text-align: center;\r\n\r\n        &:hover { \r\n            cursor: pointer;\r\n        }\r\n\r\n        &--seleccionada {\r\n            @extend .horas__hora;\r\n            background-color: v.$azul;\r\n            color: v.$blanco;\r\n        }\r\n\r\n        &--deshabilitada {\r\n            @extend .horas__hora;\r\n            border: 1px solid v.$gris;\r\n            color: v.$gris;\r\n            opacity: .5;\r\n\r\n            &:hover {\r\n                cursor: not-allowed;\r\n            }\r\n        }\r\n    }\r\n}","/* 🔹 Miniaturas en el formulario */\r\n.formulario__imagenes img {\r\n    width: 100px; /* 🔥 Tamaño pequeño */\r\n    height: auto;\r\n    cursor: pointer;\r\n    transition: transform 0.3s ease-in-out;\r\n    border-radius: 5px;\r\n}\r\n\r\n.formulario__imagenes img:hover {\r\n    transform: scale(1.1);\r\n}\r\n\r\n/* 🔹 Modal (Imágenes en tamaño original) */\r\n.modal {\r\n    display: none;\r\n    position: fixed;\r\n    z-index: 1000;\r\n    left: 0;\r\n    top: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background-color: rgba(0, 0, 0, 0.8);\r\n    align-items: center;\r\n    justify-content: center;\r\n    flex-direction: column;\r\n}\r\n\r\n/* 🔹 Imagen dentro del modal sin reducirse */\r\n.modal img {\r\n    max-width: 90%;\r\n    max-height: 90vh;\r\n    object-fit: contain;\r\n}\r\n\r\n/* 🔹 Botón de cierre */\r\n.close {\r\n    position: absolute;\r\n    top: 15px;\r\n    right: 20px;\r\n    color: white;\r\n    font-size: 40px;\r\n    cursor: pointer;\r\n}\r\n\r\n/* 🔹 Botón de descarga visible */\r\n.descargar-btn {\r\n    margin-top: 20px;\r\n    background: #ffcc00;\r\n    color: #333;\r\n    font-size: 18px;\r\n    font-weight: bold;\r\n    padding: 10px 20px;\r\n    border-radius: 10px;\r\n    text-decoration: none;\r\n    transition: 0.3s;\r\n    box-shadow: 0px 0px 10px rgba(255, 204, 0, 0.8);\r\n}\r\n\r\n.descargar-btn:hover {\r\n    background: #ffaa00;\r\n    box-shadow: 0px 0px 20px rgba(255, 204, 0, 1);\r\n}\r\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.header {\r\n    min-height: 60rem;\r\n    background-image: url(../img/grafico.svg), url(../img/grafico.svg), linear-gradient(to right, rgba(v.$negro, 1), rgba(v.$negro, .5)  ), image-set( url(../img/header-huaro.avif) 1x, url(../img/header-huaro.webp) 1x, url(../img/header-huaro.jpg) 1x );\r\n\r\n    background-repeat: no-repeat;\r\n    background-size: 400px, 400px, cover, cover;\r\n    background-position: top left, bottom right, center center, center center ;\r\n\r\n\r\n    &__contenedor {\r\n        @include m.contenedor;\r\n    }\r\n\r\n    &__navegacion {\r\n        padding: 5rem 0;\r\n        display: flex;\r\n        justify-content: center;\r\n        gap: 2rem;\r\n        @include m.tablet {\r\n            justify-content: flex-end;\r\n        }\r\n    }\r\n\r\n    &__enlace {\r\n        @include m.enlace;\r\n    }\r\n    &__form {\r\n        display: flex;\r\n    }\r\n    &__submit {\r\n        @extend .header__enlace;\r\n    }\r\n    &__contenido {\r\n        padding-top: 10rem;\r\n        @include m.tablet {\r\n            padding-top: 5rem;\r\n        }\r\n    }\r\n    &__logo {\r\n        @include m.texto-fluido(2rem, 8rem);\r\n        @include m.texto-degradado(v.$azul, v.$secundario);\r\n        text-align: center;\r\n        @include m.tablet {\r\n            text-align: left;\r\n            display: inline-block;\r\n        }\r\n    }\r\n    &__texto {\r\n        font-size: 3rem;\r\n        font-weight: v.$bold;\r\n        color: v.$blanco;\r\n        margin: 2rem 0;\r\n        text-align: center;\r\n        text-transform: uppercase;\r\n        @include m.tablet {\r\n            text-align: left;\r\n        }\r\n\r\n        &--modalidad {\r\n            font-size: 2rem;\r\n        }\r\n    }\r\n\r\n    &__boton {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        text-transform: uppercase;\r\n        margin: 2rem 0;\r\n        @include m.tablet {\r\n            width: auto;\r\n        }\r\n    }\r\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.barra {\n    background-color: v.$azul;\n    &__contenido {\n        @include m.contenedor;\n        display: flex;\n        flex-direction: column;\n\n        @include m.desktop {\n            flex-direction: row;\n            align-items: center;\n            justify-content: space-between;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(1rem, 3rem);\n    }\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.navegacion {\n    display: flex;\n    flex-direction: column;\n\n    @include m.desktop {\n        flex-direction: row;\n    }\n\n    &__enlace {\n        color: v.$blanco;\n        font-size: 1.8rem;\n        padding: 2rem;\n        font-weight: v.$black;\n        text-transform: uppercase;\n        text-align: center;\n\n        &--actual,\n        &:hover {\n            background-color: v.$blanco;\n            color: v.$azul;\n        }\n    }\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.footer {\n    background-color: v.$azul;\n    // margin-top: 5rem;\n    padding-top: 3rem;\n    color: v.$blanco;\n\n    &__grid {\n        padding-top: 3rem;\n        z-index: 2;\n        @include m.contenedor;\n        @include m.tablet {\n            @include m.grid(2, 3rem);\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 4rem);\n    }\n\n    &__texto {\n        line-height: 2;\n        text-align: center;\n        color: v.$blanco;\n        @include m.tablet {\n            text-align: left;\n        }\n    }\n\n    &__copyright {\n        background-color: darken(v.$azul, 10);\n        margin: 3rem 0 0 0;\n        padding: 2rem 0;\n        text-align: center;\n        font-size: 1.4rem;\n        font-weight: v.$black;\n\n        &--regular {\n            font-weight: v.$regular;\n        }\n    }\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.footer__bubbles {\r\n    z-index: 1;\r\n    background-color: v.$azul;\r\n    display: grid;\r\n    position: relative;\r\n    grid-area: footer;\r\n    min-height: 12rem;\r\n    .bubbles {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        right: 12rem;\r\n        height: 1rem;\r\n        background: v.$azul;\r\n        filter: url(\"#blob\");\r\n\r\n        .bubble {\r\n            position: absolute;\r\n            left: var(--position, 50%);\r\n            background: v.$azul;\r\n            border-radius: 100%;\r\n            animation: bubble-size var(--time, 4s) ease-in infinite var(--delay, 0s),\r\n                bubble-move var(--time, 4s) ease-in infinite var(--delay, 0s);\r\n            transform: translate(-50%, 100%);\r\n        }\r\n    }\r\n}\r\n\r\n\r\n@keyframes bubble-size {\r\n\r\n    0%,\r\n    75% {\r\n        width: var(--size, 4rem);\r\n        height: var(--size, 4rem);\r\n    }\r\n\r\n    100% {\r\n        width: 0rem;\r\n        height: 0rem;\r\n    }\r\n}\r\n\r\n@keyframes bubble-move {\r\n    0% {\r\n        bottom: -4rem;\r\n    }\r\n\r\n    100% {\r\n        bottom: var(--distance, 10rem);\r\n    }\r\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.menu-redes {\n    @include m.menu-social(v.$blanco, 2rem);\n    display: flex;\n    justify-content: center;\n    gap: 2rem;\n    margin: 4rem 0;\n    @include m.tablet {\n        justify-content: flex-end;\n    }\n}","@use 'base/variables' as v;\n\n.alerta {\n\n    padding: 1.5rem 1.5rem 1.5rem 3rem;\n    text-transform: uppercase;\n    margin: 1rem 0;\n    font-size: 1.2rem;\n    font-weight: v.$bold;\n\n    &__error {\n        background-color: lighten(v.$rojo, 60%);\n        border-left: .5rem solid v.$rojo;\n        color: v.$rojo;\n    }\n\n    &__exito {\n        background-color: lighten(v.$verde, 40%);\n        border-left: .5rem solid v.$verde;\n        color: darken(v.$verde, 20);\n    }\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboard {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: v.$gris-oscuro;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__nav {}\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__grid {\n        display: flex;\n        flex: 1;\n        overflow-y: auto;\n    }\n\n    &__sidebar {\n        background-color: lighten(v.$gris-oscuro, 10);\n        width: 12rem;\n    }\n\n    &__menu {\n        padding: 1rem;\n        display: flex;\n        flex-direction: column;\n        gap: 1rem;\n    }\n\n    &__enlace {\n        color: lighten(v.$gris-oscuro, 40);\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 2rem;\n        transition: 300ms background-color ease-in-out, 300ms color ease, 300ms border-radius ease;\n\n        &:hover,\n        &--actual {\n            background-color: lighten(v.$gris-oscuro, 20);\n            color: v.$blanco;\n            border-radius: 1rem;\n        }\n    }\n\n    &__icono {\n        font-size: 2rem;\n    }\n\n    &__menu-texto {\n        font-size: 1.1rem;\n        text-transform: uppercase;\n        font-weight: v.$bold;\n        margin-top: .5rem;\n    }\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n        overflow-y: scroll;\n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n    \n    &__boton {\n        @include m.boton(v.$azul, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        @include m.shadow;\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n    }\n\n    &__formulario {\n        @extend .dashboard__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__grafica {\n        @include m.contenedor-sm;\n    }\n\n    &__contenedor-buscador {\n        @include m.tablet {\n            display: flex;\n            justify-content: start;\n            margin-bottom: 5rem;\n        }\n    }\n    &__formulario__buscardor {\n        @include m.tablet {\n            display: flex;\n            justify-content: start;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton__buscardor {\n        @include m.boton(v.$azul, v.$blanco);\n        margin: 3rem;\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n    &__contenedor__boton{\n        padding-top: 2.5rem;\n    }\n\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n\r\n    &__thead {\r\n        background-color: v.$gris;\r\n        color: v.$blanco;\r\n    }\r\n\r\n    &__th {\r\n        padding: 1rem;\r\n        text-align: left;\r\n        \r\n    }\r\n\r\n    &__tr {\r\n\r\n        &:nth-child(even) {\r\n            background-color:  darken($color: v.$gris-claro, $amount: 20%);\r\n\r\n        }\r\n    }\r\n    &__td {\r\n        padding: 1.5rem 1rem;\r\n\r\n        &:hover {\r\n            background-color: darken($color: v.$blanco, $amount: 30%);\r\n\r\n        }\r\n\r\n        &--acciones {\r\n            @extend .table__td;\r\n            display: flex;\r\n            justify-content: flex-start;\r\n            align-items: flex-start;\r\n            gap: 2rem;\r\n        }\r\n\r\n        button {\r\n            border: none;\r\n            font-size: 1.5rem;\r\n            padding: .5rem 1rem;\r\n            text-transform: uppercase;\r\n            font-weight: 700;\r\n            border-radius: 1rem;\r\n        }\r\n    }\r\n\r\n    &__accion {\r\n        all: unset;\r\n        text-transform: uppercase;\r\n        font-size: 1.4rem;\r\n        font-weight: bold;\r\n\r\n        &--editar {\r\n            color: v.$azul;\r\n\r\n        }\r\n\r\n        &--eliminar {\r\n            color: v.$rojo;\r\n        }\r\n        &--asignar {\r\n            color: v.$negro;\r\n        }\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n        }\r\n    }\r\n\r\n    &__pendiente {\r\n        background-color: v.$amarillo;\r\n        color: v.$blanco;\r\n        border: none;\r\n        font-size: 1.5rem;\r\n        padding: .5rem 1rem;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        border-radius: 1rem;\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n        }\r\n    }\r\n\r\n    &__completa {\r\n        background-color: v.$verde;\r\n        color: v.$blanco;\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.paginacion {\r\n    margin-top: 5rem;\r\n    margin-bottom: 3rem;\r\n    display: flex;\r\n    gap: 1rem;\r\n    flex-wrap: wrap;\r\n    justify-content: center;\r\n    align-items: center;\r\n\r\n    @include m.tablet {\r\n        justify-content: flex-end;\r\n    }\r\n\r\n    &__enlace {\r\n        color: v.$azul;\r\n        font-size: 1.6rem;\r\n\r\n        &--texto {\r\n            padding: 1rem;\r\n            border-radius: .5rem;\r\n            border: 1px solid v.$azul;\r\n\r\n            &:hover {\r\n                background-color: v.$azul;\r\n                color: v.$blanco;\r\n            }\r\n        }\r\n        &--numero {\r\n            font-weight: v.$bold;\r\n            display: none;\r\n            @include m.tablet {\r\n                display: inline;\r\n            }\r\n        }\r\n        &--actual {\r\n            color: v.$gris;\r\n            font-weight: v.$bold;\r\n            display: none;\r\n            @include m.tablet {\r\n                display: inline;\r\n            }\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.listado-ponentes {\r\n    @include m.reset-lista;\r\n    @include m.grid(1, 1rem);\r\n\r\n    &__ponente {\r\n        color: v.$azul;\r\n        border: 1px solid v.$azul;\r\n        padding: 1rem;\r\n        border-radius: 1rem;\r\n        text-align: center;\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n            background-color: v.$azul;\r\n            color: v.$blanco;\r\n        }\r\n\r\n        &--seleccionado {\r\n            @extend .listado-ponentes__ponente;\r\n            background-color: v.$azul;\r\n            color: v.$blanco;\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.bloques {\r\n    @include m.contenedor;\r\n\r\n    @include m.tablet {\r\n        margin-top: 10rem;\r\n    }\r\n\r\n    &__grid {\r\n        @include m.grid(1, 3rem);\r\n\r\n        @include m.desktop {\r\n            @include m.grid(2, 3rem);\r\n        }\r\n    }\r\n}\r\n\r\n.bloque {\r\n    padding: 3rem;\r\n    color: v.$blanco;\r\n    border-radius: 1rem;\r\n\r\n    &:nth-child(1) {\r\n        background-color: hsla(0, 100%, 50%, 1);\r\n        background-image:\r\n            radial-gradient(at 40% 20%, hsla(28, 100%, 74%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 80% 0%, hsla(189, 100%, 56%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 50%, hsla(355, 100%, 93%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 16% 20%, hsla(340, 100%, 76%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 100%, hsla(22, 100%, 77%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 80% 100%, hsla(242, 100%, 70%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 0%, hsla(343, 100%, 76%, 1) 0px, transparent 50%);\r\n    }\r\n\r\n    &:nth-child(2) {\r\n        background-color: hsla(0, 100%, 50%, 1);\r\n        background-image:\r\n            radial-gradient(at 40% 20%, hsla(274, 74%, 47%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 80% 0%, hsla(267, 82%, 32%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 50%, hsla(272, 73%, 41%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 16% 20%, hsla(340, 39%, 11%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 100%, hsla(254, 52%, 40%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 80% 100%, hsla(242, 100%, 70%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 0%, hsla(264, 80%, 42%, 1) 0px, transparent 50%);\r\n    }\r\n\r\n    &:nth-child(3) {\r\n        background-color: hsla(190, 100%, 50%, 1);\r\n        background-image:\r\n            radial-gradient(at 40% 20%, hsla(137, 100%, 74%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 80% 0%, hsla(72, 100%, 56%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 50%, hsla(121, 39%, 37%, 1) 0px, transparent 50%);\r\n    }\r\n\r\n    &:nth-child(4) {\r\n        background-color:hsla(243,78%,46%,1);\r\n        background-image:\r\n        radial-gradient(at 80% 0%, hsla(189,100%,56%,1) 0px, transparent 50%),\r\n        radial-gradient(at 0% 50%, hsla(355,43%,44%,1) 0px, transparent 50%),\r\n        radial-gradient(at 0% 100%, hsla(22,100%,77%,1) 0px, transparent 50%),\r\n        radial-gradient(at 80% 100%, hsla(242,100%,70%,1) 0px, transparent 50%);\r\n    }\r\n\r\n    &__heading {\r\n        margin: 1rem 0 2rem 0;\r\n        font-size: 3.6rem;\r\n    }\r\n\r\n    &__texto {\r\n        margin: 1rem 0;\r\n\r\n        &--cantidad {\r\n            margin-top: 5rem;\r\n            font-weight: v.$black;\r\n            font-size: 6rem;\r\n            text-align: center;\r\n        }\r\n    }\r\n}",".noticia__introduccion{\r\n    //recortar texto\r\n    font-size: 1.6rem;\r\n    display: -webkit-box;\r\n    -webkit-line-clamp: 10; //cuantas lineas de texto quieres\r\n    -webkit-box-orient: vertical;\r\n    overflow: hidden;\r\n    font-weight: normal;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n\r\n.eventos-registro {\r\n    @include m.contenedor;\r\n    margin-bottom: 6rem;\r\n    @include m.tablet {\r\n        display: flex;\r\n        align-items: flex-start; //alinear hacia arriba\r\n        gap: 2rem;\r\n    }\r\n    &__listado {\r\n        @include m.tablet {\r\n            flex: 0 0 60%;\r\n        }\r\n    }\r\n    &__grid {\r\n        @include m.grid(1, 3rem);\r\n        @include m.desktop {\r\n            @include m.grid(2, 3rem);\r\n        }\r\n    }\r\n    &__heading {\r\n        &--conferencias,\r\n        &--workshops {\r\n            white-space: nowrap;\r\n            @include m.texto-fluido(2rem, 5rem);\r\n        }\r\n        &--conferencias {\r\n            color: v.$azul;\r\n        }\r\n        &--workshops {\r\n            color: v.$secundario;\r\n            margin-top: 5rem;\r\n        }\r\n    }\r\n    &__fecha {\r\n        margin: 6rem 0 3rem 0;\r\n    }\r\n}\r\n\r\n.registro {//aside\r\n    background-color: v.$gris-claro;\r\n    padding: 3rem;\r\n    border-radius: 1rem;\r\n    @include m.tablet {\r\n        flex: 0 0 40%;\r\n        position: -webkit-sticky;//mantener fija el aside\r\n        position: sticky;\r\n        top: 3rem;\r\n    }\r\n    &__heading {\r\n        margin: 0 0 3rem 0;\r\n    }\r\n    &__evento { //de scripting con js \r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n        padding: 1rem;\r\n        &:nth-child(even) {\r\n            background-color: darken(v.$gris-claro, 3);//intercalar colores en el listado\r\n        }\r\n    }\r\n    &__nombre {\r\n        font-size: 2rem;\r\n        font-weight: v.$bold;\r\n        margin: 0;\r\n    }\r\n    &__eliminar {\r\n        all: unset;\r\n        color: v.$rojo;\r\n        &:hover {\r\n            cursor: pointer;\r\n        }\r\n    }\r\n\r\n    &__texto {\r\n        text-align: center;\r\n    }\r\n\r\n    &__regalo {\r\n        margin-top: 3rem;\r\n    }\r\n\r\n    &__label {\r\n        display: block;\r\n        font-size: 2.2rem;\r\n        font-weight: v.$bold;\r\n        margin-bottom: 1rem;\r\n    }\r\n    &__select {\r\n        width: 100%;\r\n        background-color: v.$blanco;\r\n        border: 1px solid v.$gris;\r\n        padding: 1rem;\r\n        border-radius: .5rem;\r\n    }\r\n}\r\n\r\n","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardUser {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: #4ac4f5;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n        overflow-y: scroll;\n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton {\n        @include m.boton(v.$celeste, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        @include m.shadow;\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n\n        &--solicitud {\n            @extend .dashboardUser__contenedor;\n            @include m.contenedor;\n\n        }\n    }\n\n\n    &__formulario {\n        @extend .dashboardUser__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__mensaje {\n        padding-top: 3rem;\n        text-align: center;\n    }\n\n    //nav\n    &__navegacion {\n        padding-top: 4rem;\n        @include m.contenedor-md;\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            @include m.grid(3, 2rem);\n\n        }\n    }\n\n    &__navegacion-enlace {\n        all: unset;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        background-color: v.$celeste;\n        border-radius: 2rem;\n        padding: 2rem;\n\n        &:hover {\n            cursor: pointer;\n            background-color: darken($color: v.$celeste, $amount: 20%);\n        }\n    }\n\n\n    &__navegacion-icono {\n        color: v.$blanco;\n        font-size: 6rem;\n        padding-bottom: 1rem;\n    }\n\n    &__navegacion-texto {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    &__navegacion-etiqueta {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    //division en crear\n    &__gridCreate {\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            @include m.grid(2, 2rem);\n\n        }\n    }\n\n    &__panel {\n        @include m.contenedor;\n    }\n\n\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.authUser__body {\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    min-height: 90vh;\r\n    background: linear-gradient(90deg, #e2e2e2, #c9d6ff);\r\n}\r\n\r\n.authUser {\r\n\r\n    @include m.desktop {\r\n        position: relative;\r\n        width: 1050px;\r\n        height: 750px;\r\n        background: #fff;\r\n        margin: 20px;\r\n        border-radius: 30px;\r\n        box-shadow: 0 0 30px rgba(0, 0, 0, .2);\r\n        overflow: hidden;\r\n    }\r\n    @include m.telefono{\r\n    }\r\n\r\n\r\n    &__titulo {\r\n        font-size: 36px;\r\n        margin: -10px 0;\r\n    }\r\n\r\n    &__texto {\r\n        font-size: 14.5px;\r\n        margin: 15px 0;\r\n    }\r\n\r\n    &__form {\r\n        position: absolute;\r\n        right: 0;\r\n        width: 50%;\r\n        height: 100%;\r\n        background: #fff;\r\n        display: flex;\r\n        align-items: center;\r\n        color: #333;\r\n        text-align: center;\r\n        padding: 40px;\r\n        z-index: 1;\r\n        transition: .6s ease-in-out 1.2s, visibility 0s 1s;\r\n    }\r\n\r\n    &.active &__form {\r\n        right: 50%;\r\n    }\r\n\r\n    &__form--registrar {\r\n        visibility: hidden;\r\n    }\r\n\r\n    &.active &__form--registrar {\r\n        visibility: visible;\r\n    }\r\n\r\n\r\n    &__input {\r\n        position: relative;\r\n        margin: 30px 0;\r\n\r\n        input {\r\n            width: 100%;\r\n            padding: 13px 50px 13px 20px;\r\n            background: #eee;\r\n            border-radius: 8px;\r\n            border: none;\r\n            outline: none;\r\n            font-size: 16px;\r\n            color: #333;\r\n            font-weight: 500;\r\n\r\n            &::placeholder {\r\n                color: #888;\r\n                font-weight: 400;\r\n            }\r\n        }\r\n\r\n        .authUser__icono {\r\n            position: absolute;\r\n            right: 20px;\r\n            top: 50%;\r\n            transform: translateY(-50%);\r\n            font-size: 20px;\r\n        }\r\n    }\r\n\r\n    &__recuperar {\r\n        margin: -15px 0 15px;\r\n\r\n        &-enlace {\r\n            font-size: 14.5px;\r\n            color: #333;\r\n        }\r\n    }\r\n\r\n    &__boton {\r\n        width: 100%;\r\n        height: 48px;\r\n        background: v.$azul;\r\n        border-radius: 8px;\r\n        box-shadow: 0 0 10px rgba(0, 0, 0, .1);\r\n        border: none;\r\n        cursor: pointer;\r\n        font-size: 16px;\r\n        color: v.$blanco;\r\n        font-weight: 600;\r\n\r\n        &:hover {\r\n            background-color: v.$blanco;\r\n            color: v.$azul;\r\n            cursor: pointer;\r\n            border: 2px solid v.$negro;\r\n            /* Borde blanco y no tan grueso */\r\n        }\r\n\r\n        &--ingresar {\r\n            margin-top: 1rem;\r\n            width: 30%;\r\n        }\r\n\r\n        &--registrar {\r\n            margin-top: 1rem;\r\n            width: 30%;\r\n        }\r\n    }\r\n\r\n    &__alternar {\r\n        position: absolute;\r\n        width: 100%;\r\n        height: 100%;\r\n\r\n        &::before {\r\n            content: '';\r\n            position: absolute;\r\n            left: -250%;\r\n            width: 300%;\r\n            height: 100%;\r\n            background: v.$azul;\r\n            border-radius: 150px;\r\n            z-index: 2;\r\n            transition: 1.8s ease-in-out;\r\n        }\r\n    }\r\n\r\n    &.active &__alternar::before {\r\n        left: 50%;\r\n    }\r\n\r\n    &__alternar-panel {\r\n        position: absolute;\r\n        width: 50%;\r\n        height: 100%;\r\n        color: #fff;\r\n        display: flex;\r\n        flex-direction: column;\r\n        justify-content: center;\r\n        align-items: center;\r\n        z-index: 2;\r\n        transition: .6s ease-in-out;\r\n\r\n        &--izquierda {\r\n            left: 0;\r\n            transition-delay: 1.2s;\r\n        }\r\n\r\n        &--derecha {\r\n            right: -50%;\r\n            transition-delay: .6s;\r\n        }\r\n    }\r\n\r\n    &.active &__alternar-panel--izquierda {\r\n        left: -50%;\r\n        transition-delay: .6s;\r\n    }\r\n\r\n    &.active &__alternar-panel--derecha {\r\n        right: 0;\r\n        transition-delay: 1.2s;\r\n    }\r\n}\r\n\r\n@media screen and (max-width: 650px) {\r\n    .authUser {\r\n        height: calc(100vh - 40px);\r\n\r\n        &__form {\r\n            bottom: 0;\r\n            width: 100%;\r\n            height: 70%;\r\n        }\r\n\r\n        &.active &__form {\r\n            right: 0;\r\n            bottom: 30%;\r\n        }\r\n\r\n        &__alternar::before {\r\n            left: 0;\r\n            top: -270%;\r\n            width: 100%;\r\n            height: 300%;\r\n            border-radius: 20vw;\r\n        }\r\n\r\n        &.active &__alternar::before {\r\n            left: 0;\r\n            top: 70%;\r\n        }\r\n    }\r\n}\r\n\r\n@media screen and (max-width: 400px) {\r\n    .authUser__form {\r\n        padding: 20px;\r\n    }\r\n\r\n    .authUser__alternar-panel h1 {\r\n        font-size: 30px;\r\n    }\r\n}\r\n\r\n@include m.telefono {}",".userPerfil__contenedor {\r\n    background-color: #ffd399;\r\n    background-image:\r\n        radial-gradient(at 43% 24%, hsla(38, 62%, 78%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 2% 21%, hsla(20, 64%, 79%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 89% 57%, hsla(292, 79%, 70%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 32% 61%, hsla(326, 78%, 63%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 0% 97%, hsla(217, 89%, 63%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 74% 52%, hsla(86, 67%, 72%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 98% 87%, hsla(144, 95%, 79%, 1) 0px, transparent 50%);\r\n    border-radius: 20px;\r\n\r\n    padding-bottom: 10rem;\r\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardtecnico {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: v.$tecnico;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton {\n        @include m.boton(v.$tecnico, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n    }\n\n\n    &__formulario {\n        @extend .dashboardtecnico__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__mensaje {\n        padding-top: 3rem;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n    }\n\n    //nav\n    &__grid {\n        padding-top: 6rem;\n        @include m.contenedor-l;\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            // Asigna más espacio a la primera columna (por ejemplo, 2/3 del ancho total)\n            display: grid;\n            grid-template-columns: 2fr 1fr;\n            gap: 2rem;\n        }\n    }\n\n    &__recomendaciones {\n        line-height: 3rem;\n    }\n\n    &__navegacion {\n        padding-top: 3rem;\n\n        @include m.grid(1, .5rem);\n\n        @include m.tablet {\n            @include m.grid(2, 1rem);\n\n        }\n    }\n\n    &__navegacion-enlace {\n        all: unset;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        background-color: v.$tecnico;\n        border-radius: 2rem;\n        padding: 2rem;\n        width: 25rem;\n        margin: 0 auto;\n\n        &:hover {\n            cursor: pointer;\n            background-color: darken($color: v.$tecnico, $amount: 20%);\n        }\n    }\n\n\n\n    &__navegacion-icono {\n        color: v.$blanco;\n        font-size: 6rem;\n        padding-bottom: 1rem;\n    }\n\n    &__navegacion-texto {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    &__navegacion-etiqueta {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    //division en crear\n    &__gridCreate {\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            @include m.grid(2, 2rem);\n\n        }\n    }\n\n\n\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardTesorero {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: v.$tesorero;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__nav {}\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__grid {\n        display: flex;\n        flex: 1;\n        overflow-y: auto;\n    }\n\n    &__sidebar {\n        background-color: lighten(v.$tesorero, 10);\n        width: 12rem;\n    }\n\n    &__menu {\n        padding: 1rem;\n        display: flex;\n        flex-direction: column;\n        gap: 1rem;\n    }\n\n    &__enlace {\n        color: lighten(v.$tesorero, 40);\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 2rem;\n        transition: 300ms background-color ease-in-out, 300ms color ease, 300ms border-radius ease;\n\n        &:hover,\n        &--actual {\n            background-color: lighten(v.$tesorero, 20);\n            color: v.$blanco;\n            border-radius: 1rem;\n        }\n    }\n\n    &__icono {\n        font-size: 2rem;\n    }\n\n    &__menu-texto {\n        font-size: 1.1rem;\n        text-transform: uppercase;\n        font-weight: v.$bold;\n        margin-top: .5rem;\n    }\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n        overflow-y: scroll;\n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n    \n    &__boton {\n        @include m.boton(v.$azul, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        @include m.shadow;\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n    }\n\n    &__formulario {\n        @extend .dashboardTesorero__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__grafica {\n        @include m.contenedor-sm;\n    }\n\n    &__contenedor-buscador {\n        @include m.tablet {\n            display: flex;\n            justify-content: start;\n            margin-bottom: 5rem;\n        }\n    }\n    &__formulario__buscardor {\n        @include m.tablet {\n            display: flex;\n            justify-content: start;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton__buscardor {\n        @include m.boton(v.$azul, v.$blanco);\n        margin: 3rem;\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n    &__contenedor__boton{\n        padding-top: 2.5rem;\n    }\n\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n.headerIntranet{\r\n    height: 100%;\r\n    display: flex;\r\n    flex-direction: column;\r\n    background-color: v.$gris-claro;\r\n    &__header {\r\n        background-color: v.$azul;\r\n        padding: 2rem;\r\n    }\r\n    &__grid {\r\n        display: flex;\r\n        flex-direction: column;\r\n\r\n        @include m.tablet {\r\n            flex-direction: row;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n        }\r\n    }\r\n    &__logo {\r\n        @include m.logo;\r\n        @include m.texto-fluido(2rem, 3rem);\r\n    }\r\n   \r\n\r\n    &__enlace {\r\n        @include m.enlace;\r\n    }\r\n}\r\n","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardAgua {\n\n    &__contenedor {\n        height: 100%;\n        display: flex;\n        flex-direction: column;\n        background-color: v.$blanco;\n    }\n\n    &__menu {\n        @include m.contenedor;\n        @include m.grid(1, 3rem);\n\n        @include m.desktop {\n            @include m.grid(3, 3rem);\n        }\n    }\n\n    &__enlace {\n        padding: 3rem;\n        color: v.$blanco;\n        border-radius: 1rem;\n        text-align: center;\n        font-size: 2rem;\n        transition: filter .3s ease, transform .2s ease;\n\n        // Tus 11 variantes…\n        @for $i from 1 through 11 {\n            &:nth-child(#{$i}) {\n                $hue: 200 + ($i - 1) * 5;\n                $base: hsl($hue, 70%, 50%);\n                background-color: $base;\n                background-image:\n                    radial-gradient(circle at 15% 15%, lighten($base, 20%) 0%, transparent 60%),\n                    radial-gradient(circle at 85% 10%, adjust-hue($base, -15) 0%, transparent 50%),\n                    radial-gradient(circle at 50% 85%, darken($base, 10%) 0%, transparent 70%),\n                    radial-gradient(circle at center, rgba(255, 255, 255, 0.15) 0%, transparent 50%);\n            }\n        }\n\n        &:hover {\n            filter: brightness(1.2);\n            transform: translateY(-4px);\n            cursor: pointer;\n        }\n    }\n\n    &__recomendaciones {\n        margin: 2rem 0;\n        padding: 1.5rem;\n        background: v.$azul;\n        border-radius: 1rem;\n    }\n\n    &__recomendaciones-heading {\n        font-size: 3rem;\n        margin-bottom: 1rem;\n        color: v.$blanco;\n        text-align: center;\n    }\n\n    &__recomendaciones-lista {\n        list-style: disc inside;\n        color: v.$blanco;\n        line-height: 1.6;\n\n        li {\n            margin-bottom: 0.75rem;\n        }\n    }\n\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardlecturador {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: v.$lecturador;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n       \n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton {\n        @include m.boton(v.$lecturador, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n    }\n\n    &__formulario {\n        @extend .dashboardlecturador__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__mensaje {\n        padding-top: 3rem;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n    }\n\n    &__grid {\n        padding-top: 6rem;\n        @include m.contenedor-l;\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            display: grid;\n            grid-template-columns: 2fr 1fr;\n            gap: 2rem;\n        }\n    }\n\n    &__recomendaciones {\n        line-height: 3rem;\n    }\n\n    &__navegacion {\n        padding-top: 3rem;\n\n        @include m.grid(1, .5rem);\n\n        @include m.tablet {\n            @include m.grid(2, 1rem);\n        }\n    }\n\n    &__navegacion-enlace {\n        all: unset;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        background-color: v.$lecturador;\n        border-radius: 2rem;\n        padding: 2rem;\n        width: 25rem;\n        margin: 0 auto;\n\n        &:hover {\n            cursor: pointer;\n            background-color: darken($color: v.$lecturador, $amount: 20%);\n        }\n    }\n\n    &__navegacion-icono {\n        color: v.$blanco;\n        font-size: 6rem;\n        padding-bottom: 1rem;\n    }\n\n    &__navegacion-texto,\n    &__navegacion-etiqueta {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    &__gridCreate {\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            @include m.grid(2, 2rem);\n        }\n    }\n}\n"]}
