uD70LQ,mCACI,iBvD+0LZ,CMt3LI,yBiD2CA,uCAEQ,YAAA,CACA,wBAAA,CACA,kBvD60LV,CACF,CuD10LI,4BjDjCA,wBFRS,CEaT,WAAA,CAHA,UFHK,CEWL,oBAAA,CAPA,gBAAA,CiDkCI,gBAAA,CjDjCJ,eAAA,CiD+BI,gBAAA,CjDlCJ,mBAAA,CAOA,iBAAA,CiD4BI,wBAAA,CjD7BJ,uBAAA,CADA,oCAAA,CAGA,UNk3LJ,CM/2LI,kCACI,wBAAA,CACA,cNi3LR,CMj5LI,yBiDmDA,4BAOQ,UvD21LV,CACF,CuDx1LI,kEACI,qBnD9CC,CmDgDD,kBAAA,CACA,eAAA,CAFA,YvD41LR,CuDv1LI,iCjDfA,aAAA,CADA,oBN22LJ,CuDt1LI,8BAGI,kBAAA,CADA,YAAA,CAEA,sBAAA,CAHA,gBvD21LR,CuDr1LI,2BjD5CA,YAAA,CACA,QiD8CuB,CjD7CvB,mCAAA,CAUA,aAAA,CiDiCI,gBAAA,CjDlCJ,qBN83LJ,CM96LI,yBiDiFA,2BAMQ,YAAA,CAEA,QAAA,CADA,6BvD41LV,CACF,CuDx1LI,sCACI,gBvD01LR,CuDv1LI,iCjD5DA,YAAA,CACA,SiD8DuB,CjD7DvB,mCAAA,CiD2DI,gBvD41LR,CM97LI,yBiDiGA,iCjD5DA,YAAA,CACA,QiDiE2B,CjDhE3B,mCN65LF,CACF,CuD11LI,wCACI,SAAA,CAGA,kBAAA,CAEA,wBnDvGK,CmDwGL,kBAAA,CALA,YAAA,CACA,qBAAA,CAEA,sBAAA,CAKA,aAAA,CAFA,YAAA,CACA,WvD61LR,CuD11LQ,8CAEI,wBAAA,CADA,cvD61LZ,CuDx1LI,uCACI,UnD7GC,CmD8GD,cAAA,CACA,mBvD01LR,CuDv1LI,iFAEI,UnDpHC,CmDqHD,gBAAA,CACA,iBvDw1LR,CuDr1LI,iCjDrGA,YAAA,CACA,QiDqGuB,CjDpGvB,mCN67LJ,CMp+LI,yBiD0IA,iCjDrGA,YAAA,CACA,QiDwG2B,CjDvG3B,mCNm8LF,CACF","file":"app.css","sourcesContent":["@property --gradient-angle {\r\n    syntax: \"<angle>\";\r\n    initial-value: 0turn;\r\n    inherits: false;\r\n}\r\n\r\n.tarjeta {\r\n    animation: 2s gradient-angle infinite linear;\r\n    border: 2px solid transparent;\r\n    background-image: linear-gradient(#584827, #2d230f),\r\n        conic-gradient(from var(--gradient-angle),\r\n            #584827 0%,\r\n            #c7a03c 37%,\r\n            #f9de90 30%,\r\n            #c7a03c 33%,\r\n            #584827 40%,\r\n            #584827 50%,\r\n            #c7a03c 77%,\r\n            #f9de90 80%,\r\n            #c7a03c 83%,\r\n            #584827 90%);\r\n    background-clip: padding-box, border-box;\r\n    background-origin: padding-box, border-box;\r\n}\r\n\r\n@keyframes gradient-angle {\r\n    to {\r\n        --gradient-angle: 1turn;\r\n    }\r\n}\r\n\r\n/* その他 */\r\n.tarjetas {\r\n    background: #141819;\r\n}\r\n\r\n.tarjetas {\r\n    font-family: \"游ゴシック Medium\", YuGothic, YuGothicM,\r\n        \"Hiragino Kaku Gothic ProN\", Meiryo, sans-serif;\r\n    line-height: 1.6;\r\n    display: grid;\r\n    align-content: center;\r\n    min-height: 100svh;\r\n    padding: 24px;\r\n    color: #d5cec0;\r\n    gap: 24px;\r\n\r\n    @media (width < 970px) {\r\n        align-content: start;\r\n    }\r\n}\r\n\r\n.tarjetas__cuerpo {\r\n    display: grid;\r\n    justify-content: center;\r\n    margin-inline: auto;\r\n    grid-auto-flow: column;\r\n    gap: 16px 40px;\r\n\r\n    @media (width < 970px) {\r\n        grid-auto-flow: row;\r\n    }\r\n}\r\n\r\n.tarjeta {\r\n    display: grid;\r\n    max-width: 240px;\r\n    padding: 20px;\r\n    text-decoration: none;\r\n    color: currentColor;\r\n    border-radius: 20px;\r\n    place-content: center;\r\n    place-items: center;\r\n    aspect-ratio: 1/1;\r\n    row-gap: 16px;\r\n}\r\n\r\n.tarjeta h2 {\r\n    font-family: \"Comfortaa\", sans-serif;\r\n    font-size: 18px;\r\n    font-weight: 700;\r\n    font-style: normal;\r\n    font-optical-sizing: auto;\r\n}\r\n\r\n.tarjeta p {\r\n    font-size: 12px;\r\n}","@charset \"UTF-8\";\n@import url(\"https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,100..900;1,100..900&display=swap\");\nhtml {\n  line-height: 1.15; /* 1 */\n  -webkit-text-size-adjust: 100%; /* 2 */\n}\n\n/* Sections\n   ========================================================================== */\n/**\n * Remove the margin in all browsers.\n */\nbody {\n  margin: 0;\n}\n\n/**\n * Render the `main` element consistently in IE.\n */\nmain {\n  display: block;\n}\n\n/**\n * Correct the font size and margin on `h1` elements within `section` and\n * `article` contexts in Chrome, Firefox, and Safari.\n */\nh1 {\n  font-size: 2em;\n  margin: 0.67em 0;\n}\n\n/* Grouping content\n   ========================================================================== */\n/**\n * 1. Add the correct box sizing in Firefox.\n * 2. Show the overflow in Edge and IE.\n */\nhr {\n  box-sizing: content-box; /* 1 */\n  height: 0; /* 1 */\n  overflow: visible; /* 2 */\n}\n\n/**\n * 1. Correct the inheritance and scaling of font size in all browsers.\n * 2. Correct the odd `em` font sizing in all browsers.\n */\npre {\n  font-family: monospace, monospace; /* 1 */\n  font-size: 1em; /* 2 */\n}\n\n/* Text-level semantics\n   ========================================================================== */\n/**\n * Remove the gray background on active links in IE 10.\n */\na {\n  background-color: transparent;\n}\n\n/**\n * 1. Remove the bottom border in Chrome 57-\n * 2. Add the correct text decoration in Chrome, Edge, IE, Opera, and Safari.\n */\nabbr[title] {\n  border-bottom: none; /* 1 */\n  text-decoration: underline; /* 2 */\n  text-decoration: underline dotted; /* 2 */\n}\n\n/**\n * Add the correct font weight in Chrome, Edge, and Safari.\n */\nb,\nstrong {\n  font-weight: bolder;\n}\n\n/**\n * 1. Correct the inheritance and scaling of font size in all browsers.\n * 2. Correct the odd `em` font sizing in all browsers.\n */\ncode,\nkbd,\nsamp {\n  font-family: monospace, monospace; /* 1 */\n  font-size: 1em; /* 2 */\n}\n\n/**\n * Add the correct font size in all browsers.\n */\nsmall {\n  font-size: 80%;\n}\n\n/**\n * Prevent `sub` and `sup` elements from affecting the line height in\n * all browsers.\n */\nsub,\nsup {\n  font-size: 75%;\n  line-height: 0;\n  position: relative;\n  vertical-align: baseline;\n}\n\nsub {\n  bottom: -0.25em;\n}\n\nsup {\n  top: -0.5em;\n}\n\n/* Embedded content\n   ========================================================================== */\n/**\n * Remove the border on images inside links in IE 10.\n */\nimg {\n  border-style: none;\n}\n\n/* Forms\n   ========================================================================== */\n/**\n * 1. Change the font styles in all browsers.\n * 2. Remove the margin in Firefox and Safari.\n */\nbutton,\ninput,\noptgroup,\nselect,\ntextarea {\n  font-family: inherit; /* 1 */\n  font-size: 100%; /* 1 */\n  line-height: 1.15; /* 1 */\n  margin: 0; /* 2 */\n}\n\n/**\n * Show the overflow in IE.\n * 1. Show the overflow in Edge.\n */\nbutton,\ninput { /* 1 */\n  overflow: visible;\n}\n\n/**\n * Remove the inheritance of text transform in Edge, Firefox, and IE.\n * 1. Remove the inheritance of text transform in Firefox.\n */\nbutton,\nselect { /* 1 */\n  text-transform: none;\n}\n\n/**\n * Correct the inability to style clickable types in iOS and Safari.\n */\nbutton,\n[type=button],\n[type=reset],\n[type=submit] {\n  -webkit-appearance: button;\n}\n\n/**\n * Remove the inner border and padding in Firefox.\n */\nbutton::-moz-focus-inner,\n[type=button]::-moz-focus-inner,\n[type=reset]::-moz-focus-inner,\n[type=submit]::-moz-focus-inner {\n  border-style: none;\n  padding: 0;\n}\n\n/**\n * Restore the focus styles unset by the previous rule.\n */\nbutton:-moz-focusring,\n[type=button]:-moz-focusring,\n[type=reset]:-moz-focusring,\n[type=submit]:-moz-focusring {\n  outline: 1px dotted ButtonText;\n}\n\n/**\n * Correct the padding in Firefox.\n */\nfieldset {\n  padding: 0.35em 0.75em 0.625em;\n}\n\n/**\n * 1. Correct the text wrapping in Edge and IE.\n * 2. Correct the color inheritance from `fieldset` elements in IE.\n * 3. Remove the padding so developers are not caught out when they zero out\n *    `fieldset` elements in all browsers.\n */\nlegend {\n  box-sizing: border-box; /* 1 */\n  color: inherit; /* 2 */\n  display: table; /* 1 */\n  max-width: 100%; /* 1 */\n  padding: 0; /* 3 */\n  white-space: normal; /* 1 */\n}\n\n/**\n * Add the correct vertical alignment in Chrome, Firefox, and Opera.\n */\nprogress {\n  vertical-align: baseline;\n}\n\n/**\n * Remove the default vertical scrollbar in IE 10+.\n */\ntextarea {\n  overflow: auto;\n}\n\n/**\n * 1. Add the correct box sizing in IE 10.\n * 2. Remove the padding in IE 10.\n */\n[type=checkbox],\n[type=radio] {\n  box-s