% 0%, hsla(100, 60%, 30%, 0.7) 0px, transparent 50%), radial-gradient(at 0% 100%, hsla(160, 70%, 40%, 0.5) 0px, transparent 50%);\n}\n.bloque:nth-child(7) {\n  background-color: hsl(35, 100%, 30%);\n  background-image: radial-gradient(at 40% 20%, hsla(45, 100%, 40%, 0.8) 0px, transparent 50%), radial-gradient(at 80% 0%, hsla(20, 90%, 35%, 0.7) 0px, transparent 50%), radial-gradient(at 0% 50%, hsla(10, 100%, 45%, 0.6) 0px, transparent 50%), radial-gradient(at 80% 100%, hsla(55, 100%, 35%, 0.5) 0px, transparent 50%);\n}\n.bloque:nth-child(8) {\n  background-color: hsl(200, 80%, 25%);\n  background-image: radial-gradient(at 40% 20%, hsla(210, 90%, 35%, 0.8) 0px, transparent 50%), radial-gradient(at 80% 0%, hsla(190, 100%, 30%, 0.7) 0px, transparent 50%), radial-gradient(at 0% 50%, hsla(220, 70%, 40%, 0.6) 0px, transparent 50%), radial-gradient(at 80% 100%, hsla(180, 100%, 35%, 0.5) 0px, transparent 50%);\n}\n\n.noticia__introduccion {\n  font-size: 1.6rem;\n  display: -webkit-box;\n  -webkit-line-clamp: 10;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  font-weight: normal;\n}\n\n.eventos-registro {\n  width: min(95%, 140rem);\n  margin: 0 auto;\n  margin-bottom: 6rem;\n}\n@media (min-width: 768px) {\n  .eventos-registro {\n    display: flex;\n    align-items: flex-start;\n    gap: 2rem;\n  }\n}\n@media (min-width: 768px) {\n  .eventos-registro__listado {\n    flex: 0 0 60%;\n  }\n}\n.eventos-registro__grid {\n  display: grid;\n  gap: 3rem;\n  grid-template-columns: repeat(1, 1fr);\n}\n@media (min-width: 1024px) {\n  .eventos-registro__grid {\n    display: grid;\n    gap: 3rem;\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n.eventos-registro__heading--conferencias, .eventos-registro__heading--workshops {\n  white-space: nowrap;\n  font-size: clamp(2rem, -0.8rem + 10vw, 5rem);\n}\n.eventos-registro__heading--conferencias {\n  color: #007df4;\n}\n.eventos-registro__heading--workshops {\n  color: #00b4d8;\n  margin-top: 5rem;\n}\n.eventos-registro__fecha {\n  margin: 6rem 0 3rem 0;\n}\n\n.registro {\n  background-color: #F8FAFC;\n  padding: 3rem;\n  border-radius: 1rem;\n}\n@media (min-width: 768px) {\n  .registro {\n    flex: 0 0 40%;\n    position: -webkit-sticky;\n    position: sticky;\n    top: 3rem;\n  }\n}\n.registro__heading {\n  margin: 0 0 3rem 0;\n}\n.registro__evento {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 1rem;\n}\n.registro__evento:nth-child(even) {\n  background-color: rgb(237.29, 242.35, 247.41);\n}\n.registro__nombre {\n  font-size: 2rem;\n  font-weight: 700;\n  margin: 0;\n}\n.registro__eliminar {\n  all: unset;\n  color: rgb(169, 0, 0);\n}\n.registro__eliminar:hover {\n  cursor: pointer;\n}\n.registro__texto {\n  text-align: center;\n}\n.registro__regalo {\n  margin-top: 3rem;\n}\n.registro__label {\n  display: block;\n  font-size: 2.2rem;\n  font-weight: 700;\n  margin-bottom: 1rem;\n}\n.registro__select {\n  width: 100%;\n  background-color: #FFFFFF;\n  border: 1px solid #64748B;\n  padding: 1rem;\n  border-radius: 0.5rem;\n}\n\n.dashboardUser {\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  background-color: #F8FAFC;\n}\n.dashboardUser__header {\n  background-color: #4ac4f5;\n  padding: 2rem;\n}\n.dashboardUser__header-grid {\n  display: flex;\n  flex-direction: column;\n}\n@media (min-width: 768px) {\n  .dashboardUser__header-grid {\n    flex-direction: row;\n    justify-content: space-between;\n    align-items: center;\n  }\n}\n.dashboardUser__logo {\n  color: #FFFFFF;\n  text-align: center;\n  margin-bottom: 2rem;\n  white-space: nowrap;\n  font-size: clamp(2rem, -0.8rem + 10vw, 3rem);\n}\n@media (min-width: 1024px) {\n  .dashboardUser__logo {\n    text-align: left;\n    margin: 0;\n  }\n}\n.dashboardUser__form {\n  display: flex;\n  justify-content: center;\n}\n.dashboardUser__submit--logout {\n  all: unset;\n  color: #FFFFFF;\n  font-size: 1.4rem;\n  text-transform: uppercase;\n  font-weight: 700;\n}\n.dashboardUser__submit--logout:hover {\n  color: #007df4;\n  cursor: pointer;\n}\n.dashboardUser__contenido {\n  width: 100%;\n  padding: 1rem 1rem 3rem 1rem;\n  overflow-y: scroll;\n}\n@media (min-width: 768px) {\n  .dashboardUser__contenido {\n    padding: 1rem 5rem 3rem 5rem;\n  }\n}\n.dashboardUser__contenido h2 {\n  text-align: center;\n}\n@media (min-width: 768px) {\n  .dashboardUser__contenedor-boton {\n    display: flex;\n    justify-content: flex-end;\n    margin-bottom: 5rem;\n  }\n}\n.dashboardUser__boton {\n  background-color: #4ac4f5;\n  padding: 1.5rem 4rem;\n  color: #FFFFFF;\n  font-size: 1.8rem;\n  font-weight: 700;\n  border: none;\n  transition-property: background-color;\n  transition-duration: 0.3s;\n  text-align: center;\n  width: 100%;\n  display: inline-block;\n  margin-left: 1rem;\n  text-transform: uppercase;\n  font-size: 1.4rem;\n}\n.dashboardUser__boton:hover {\n  background-color: rgb(25.6701570681, 180.2460732984, 242.3298429319);\n  cursor: pointer;\n}\n@media (min-width: 768px) {\n  .dashboardUser__boton {\n    width: auto;\n  }\n}\n.dashboardUser__contenedor, .dashboardUser__formulario, .dashboardUser__contenedor--solicitud {\n  box-shadow: rgba(50, 50, 93, 0.25) 0px 13px 27px -5px, rgba(0, 0, 0, 0.3) 0px 8px 16px -8px;\n  background-color: #FFFFFF;\n  padding: 2rem;\n  border-radius: 1rem;\n  margin-top: 5rem;\n}\n.dashboardUser__contenedor--solicitud {\n  width: min(95%, 140rem);\n  margin: 0 auto;\n}\n.dashboardUser__formulario {\n  width: min(95%, 80rem);\n  margin: 0 auto;\n}\n.dashboardUser__mensaje {\n  padding-top: 3rem;\n  text-align: center;\n}\n.dashboardUser__navegacion {\n  padding-top: 4rem;\n  width: min(95%, 80rem);\n  margin: 0 auto;\n  display: grid;\n  gap: 2rem;\n  grid-template-columns: repeat(1, 1fr);\n}\n@media (min-width: 768px) {\n  .dashboardUser__navegacion {\n    display: grid;\n    gap: 2rem;\n    grid-template-columns: repeat(3, 1fr);\n  }\n}\n.dashboardUser__navegacion-enlace {\n  all: unset;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  background-color: #4ac4f5;\n  border-radius: 2rem;\n  padding: 2rem;\n}\n.dashboardUser__navegacion-enlace:hover {\n  cursor: pointer;\n  background-color: rgb(11.3612565445, 149.9685863874, 205.6387434555);\n}\n.dashboardUser__navegacion-icono {\n  color: #FFFFFF;\n  font-size: 6rem;\n  padding-bottom: 1rem;\n}\n.dashboardUser__navegacion-texto {\n  color: #FFFFFF;\n  padding-top: 1rem;\n  text-align: center;\n}\n.dashboardUser__navegacion-etiqueta {\n  color: #FFFFFF;\n  padding-top: 1rem;\n  text-align: center;\n}\n.dashboardUser__gridCreate {\n  display: grid;\n  gap: 2rem;\n  grid-template-columns: repeat(1, 1fr);\n}\n@media (min-width: 768px) {\n  .dashboardUser__gridCreate {\n    display: grid;\n    gap: 2rem;\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n.dashboardUser__panel {\n  width: min(95%, 140rem);\n  margin: 0 auto;\n}\n\n.authUser__body {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 90vh;\n  background: linear-gradient(90deg, #e2e2e2, #c9d6ff);\n}\n\n@media (min-width: 1024px) {\n  .authUser {\n    position: relative;\n    width: 1050px;\n    height: 750px;\n    background: #fff;\n    margin: 20px;\n    border-radius: 30px;\n    box-shadow: 0 0 30px rgba(0, 0, 0, 0.2);\n    overflow: hidden;\n  }\n}\n.authUser__titulo {\n  font-size: 36px;\n  margin: -10px 0;\n}\n.authUser__texto {\n  font-size: 14.5px;\n  margin: 15px 0;\n}\n.authUser__form {\n  position: absolute;\n  right: 0;\n  width: 50%;\n  height: 100%;\n  background: #fff;\n  display: flex;\n  align-items: center;\n  color: #333;\n  text-align: center;\n  padding: 40px;\n  z-index: 1;\n  transition: 0.6s ease-in-out 1.2s, visibility 0s 1s;\n}\n.authUser.active .authUser__form {\n  right: 50%;\n}\n.authUser__form--registrar {\n  visibility: hidden;\n}\n.authUser.active .authUser__form--registrar {\n  visibility: visible;\n}\n.authUser__input {\n  position: relative;\n  margin: 30px 0;\n}\n.authUser__input input {\n  width: 100%;\n  padding: 13px 50px 13px 20px;\n  background: #eee;\n  border-radius: 8px;\n  border: none;\n  outline: none;\n  font-size: 16px;\n  color: #333;\n  font-weight: 500;\n}\n.authUser__input input::placeholder {\n  color: #888;\n  font-weight: 400;\n}\n.authUser__input .authUser__icono {\n  position: absolute;\n  right: 20px;\n  top: 50%;\n  transform: translateY(-50%);\n  font-size: 20px;\n}\n.authUser__recuperar {\n  margin: -15px 0 15px;\n}\n.authUser__recuperar-enlace {\n  font-size: 14.5px;\n  color: #333;\n}\n.authUser__boton {\n  width: 100%;\n  height: 48px;\n  background: #007df4;\n  border-radius: 8px;\n  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\n  border: none;\n  cursor: pointer;\n  font-size: 16px;\n  color: #FFFFFF;\n  font-weight: 600;\n}\n.authUser__boton:hover {\n  background-color: #FFFFFF;\n  color: #007df4;\n  cursor: pointer;\n  border: 2px solid #1a1b15;\n  /* Borde blanco y no tan grueso */\n}\n.authUser__boton--ingresar {\n  margin-top: 1rem;\n  width: 30%;\n}\n.authUser__boton--registrar {\n  margin-top: 1rem;\n  width: 30%;\n}\n.authUser__alternar {\n  position: absolute;\n  width: 100%;\n  height: 100%;\n}\n.authUser__alternar::before {\n  content: \"\";\n  position: absolute;\n  left: -250%;\n  width: 300%;\n  height: 100%;\n  background: #007df4;\n  border-radius: 150px;\n  z-index: 2;\n  transition: 1.8s ease-in-out;\n}\n.authUser.active .authUser__alternar::before {\n  left: 50%;\n}\n.authUser__alternar-panel {\n  position: absolute;\n  width: 50%;\n  height: 100%;\n  color: #fff;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n  z-index: 2;\n  transition: 0.6s ease-in-out;\n}\n.authUser__alternar-panel--izquierda {\n  left: 0;\n  transition-delay: 1.2s;\n}\n.authUser__alternar-panel--derecha {\n  right: -50%;\n  transition-delay: 0.6s;\n}\n.authUser.active .authUser__alternar-panel--izquierda {\n  left: -50%;\n  transition-delay: 0.6s;\n}\n.authUser.active .authUser__alternar-panel--derecha {\n  right: 0;\n  transition-delay: 1.2s;\n}\n\n@media screen and (max-width: 650px) {\n  .authUser {\n    height: calc(100vh - 40px);\n  }\n  .authUser__form {\n    bottom: 0;\n    width: 100%;\n    height: 70%;\n  }\n  .authUser.active .authUser__form {\n    right: 0;\n    bottom: 30%;\n  }\n  .authUser__alternar::before {\n    left: 0;\n    top: -270%;\n    width: 100%;\n    height: 300%;\n    border-radius: 20vw;\n  }\n  .authUser.active .authUser__alternar::before {\n    left: 0;\n    top: 70%;\n  }\n}\n@media screen and (max-width: 400px) {\n  .authUser__form {\n    padding: 20px;\n  }\n  .authUser__alternar-panel h1 {\n    font-size: 30px;\n  }\n}\n/* Box model universal */\n*,\n*:after,\n*:before {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\n/* Clearfix */\n.clearfix::after {\n  content: \"\";\n  display: table;\n  clear: both;\n}\n\n/* Enlaces sin subrayado */\na {\n  color: inherit;\n  text-decoration: none;\n}\n\n/* Contenedor general */\n.login {\n  flex: 1;\n  width: 100%;\n  max-width: 525px;\n  min-height: 670px;\n  margin: auto;\n  position: relative;\n  background: url(../img/iglesia-huaro.jpg) no-repeat center;\n  background-size: cover;\n  box-shadow: 0 12px 15px rgba(0, 0, 0, 0.24), 0 17px 50px rgba(0, 0, 0, 0.19);\n  border-radius: 2rem;\n  margin-top: 1rem;\n  margin-bottom: 7rem;\n  display: flex;\n  /* Asegura comportamiento flexible */\n  align-items: center;\n}\n\n/* Contenedor interno */\n.login__inner {\n  width: 100%;\n  padding: 90px 70px 110px 70px;\n  background: rgba(40, 57, 101, 0.9);\n  border-radius: 2rem;\n  height: 100%;\n  /* Asegura que tome todo el alto del contenedor padre */\n  min-height: 670px;\n  /* Fuerza el alto mínimo igual en todas */\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  /* Centra el contenido verticalmente */\n}\n\n/* Ocultar radio buttons y checkbox */\n.login__tab,\n.login__check {\n  display: none;\n}\n\n/* Tabs superiores (Sign In / Sign Up) */\n.login__label--tab {\n  font-size: 22px;\n  margin-right: 15px;\n  display: inline-block;\n  padding-bottom: 5px;\n  border-bottom: 2px solid transparent;\n  color: #aaa;\n  cursor: pointer;\n}\n\n/* Tab activo */\n.login__tab--signin:checked + .login__label--tab,\n.login__tab--signup:checked + .login__label--tab {\n  color: #fff;\n  border-color: #1161ee;\n}\n\n/* Contenedor del formulario */\n.login__form {\n  padding-top: 2rem;\n  position: relative;\n}\n\n/* Secciones SignIn y SignUp ocultas inicialmente */\n.login__section {\n  display: none;\n  opacity: 0;\n  visibility: hidden;\n  transition: opacity 0.3s ease-in-out;\n}\n\n/* Mostrar sección correspondiente según tab activo */\n.login__tab--signin:checked ~ .login__form .login__section--signin,\n.login__tab--signup:checked ~ .login__form .login__section--signup {\n  display: block;\n  opacity: 1;\n  visibility: visible;\n}\n\n/* Agrupación de campos */\n.login__group {\n  margin-bottom: 15px;\n}\n\n/* Etiquetas e inputs */\n.login__label,\n.login__input,\n.login__button {\n  width: 100%;\n  display: block;\n  color: #fff;\n}\n\n.login__label {\n  font-size: 2rem;\n  color: #aaa;\n  margin-bottom: 5px;\n}\n\n.login__input,\n.login__button {\n  padding: 15px 20px;\n  border-radius: 25px;\n  border: none;\n  background: rgba(255, 255, 255, 0.1);\n}\n\n/* Ocultar texto de password */\n.login__input[data-type=password] {\n  -webkit-text-security: disc;\n}\n\n/* Botón de envío */\n.login__button {\n  background: #1161ee;\n  cursor: pointer;\n  text-transform: uppercase;\n  font-weight: bold;\n  transition: background 0.3s;\n}\n\n.login__button:hover {\n  background: #0d47c6;\n}\n\n/* Checkbox personalizado */\n.login__label--checkbox {\n  display: flex;\n  align-items: center;\n  font-size: 12px;\n  color: #aaa;\n  cursor: pointer;\n}\n\n.login__label--checkbox .login__icon {\n  width: 15px;\n  height: 15px;\n  margin-right: 8px;\n  border-radius: 2px;\n  background: rgba(255, 255, 255, 0.1);\n  position: relative;\n}\n\n.login__label--checkbox .login__icon::before,\n.login__label--checkbox .login__icon::after {\n  content: \"\";\n  position: absolute;\n  background: #fff;\n  transition: all 0.2s ease-in-out;\n}\n\n.login__label--checkbox .login__icon::before {\n  width: 5px;\n  height: 2px;\n  bottom: 6px;\n  left: 3px;\n  transform: scale(0) rotate(0deg);\n}\n\n.login__label--checkbox .login__icon::after {\n  width: 10px;\n  height: 2px;\n  top: 6px;\n  right: 0;\n  transform: scale(0) rotate(0deg);\n}\n\n/* Activación del checkbox */\n.login__check:checked + .login__label--checkbox .login__icon {\n  background: #1161ee;\n}\n\n.login__check:checked + .login__label--checkbox .login__icon::before {\n  transform: scale(1) rotate(45deg);\n}\n\n.login__check:checked + .login__label--checkbox .login__icon::after {\n  transform: scale(1) rotate(-45deg);\n}\n\n/* Línea divisora */\n.login__hr {\n  height: 2px;\n  margin: 60px 0 50px 0;\n  background: rgba(255, 255, 255, 0.2);\n}\n\n/* Footer del login */\n.login__foot-link {\n  text-align: center;\n}\n\n.login__link {\n  color: #fff;\n  font-size: 14px;\n}\n\n.login__label--switch {\n  cursor: pointer;\n  font-size: 14px;\n  color: #aaa;\n  display: block;\n  margin-top: 10px;\n}\n\n.userPerfil__contenedor {\n  background-color: #ffd399;\n  background-image: radial-gradient(at 43% 24%, hsl(38, 62%, 78%) 0px, transparent 50%), radial-gradient(at 2% 21%, hsl(20, 64%, 79%) 0px, transparent 50%), radial-gradient(at 89% 57%, hsl(292, 79%, 70%) 0px, transparent 50%), radial-gradient(at 32% 61%, hsl(326, 78%, 63%) 0px, transparent 50%), radial-gradient(at 0% 97%, hsl(217, 89%, 63%) 0px, transparent 50%), radial-gradient(at 74% 52%, hsl(86, 67%, 72%) 0px, transparent 50%), radial-gradient(at 98% 87%, hsl(144, 95%, 79%) 0px, transparent 50%);\n  border-radius: 20px;\n  padding-bottom: 10rem;\n}\n\n.estadoServicio {\n  width: min(95%, 80rem);\n  margin: 0 auto;\n  margin: 4rem auto;\n}\n.estado