n    box-sizing: content-box; /* 1 */\n    height: 0; /* 1 */\n    overflow: visible; /* 2 */\n  }\n  \n  /**\n   * 1. Correct the inheritance and scaling of font size in all browsers.\n   * 2. Correct the odd `em` font sizing in all browsers.\n   */\n  \n  pre {\n    font-family: monospace, monospace; /* 1 */\n    font-size: 1em; /* 2 */\n  }\n  \n  /* Text-level semantics\n     ========================================================================== */\n  \n  /**\n   * Remove the gray background on active links in IE 10.\n   */\n  \n  a {\n    background-color: transparent;\n  }\n  \n  /**\n   * 1. Remove the bottom border in Chrome 57-\n   * 2. Add the correct text decoration in Chrome, Edge, IE, Opera, and Safari.\n   */\n  \n  abbr[title] {\n    border-bottom: none; /* 1 */\n    text-decoration: underline; /* 2 */\n    text-decoration: underline dotted; /* 2 */\n  }\n  \n  /**\n   * Add the correct font weight in Chrome, Edge, and Safari.\n   */\n  \n  b,\n  strong {\n    font-weight: bolder;\n  }\n  \n  /**\n   * 1. Correct the inheritance and scaling of font size in all browsers.\n   * 2. Correct the odd `em` font sizing in all browsers.\n   */\n  \n  code,\n  kbd,\n  samp {\n    font-family: monospace, monospace; /* 1 */\n    font-size: 1em; /* 2 */\n  }\n  \n  /**\n   * Add the correct font size in all browsers.\n   */\n  \n  small {\n    font-size: 80%;\n  }\n  \n  /**\n   * Prevent `sub` and `sup` elements from affecting the line height in\n   * all browsers.\n   */\n  \n  sub,\n  sup {\n    font-size: 75%;\n    line-height: 0;\n    position: relative;\n    vertical-align: baseline;\n  }\n  \n  sub {\n    bottom: -0.25em;\n  }\n  \n  sup {\n    top: -0.5em;\n  }\n  \n  /* Embedded content\n     ========================================================================== */\n  \n  /**\n   * Remove the border on images inside links in IE 10.\n   */\n  \n  img {\n    border-style: none;\n  }\n  \n  /* Forms\n     ========================================================================== */\n  \n  /**\n   * 1. Change the font styles in all browsers.\n   * 2. Remove the margin in Firefox and Safari.\n   */\n  \n  button,\n  input,\n  optgroup,\n  select,\n  textarea {\n    font-family: inherit; /* 1 */\n    font-size: 100%; /* 1 */\n    line-height: 1.15; /* 1 */\n    margin: 0; /* 2 */\n  }\n  \n  /**\n   * Show the overflow in IE.\n   * 1. Show the overflow in Edge.\n   */\n  \n  button,\n  input { /* 1 */\n    overflow: visible;\n  }\n  \n  /**\n   * Remove the inheritance of text transform in Edge, Firefox, and IE.\n   * 1. Remove the inheritance of text transform in Firefox.\n   */\n  \n  button,\n  select { /* 1 */\n    text-transform: none;\n  }\n  \n  /**\n   * Correct the inability to style clickable types in iOS and Safari.\n   */\n  \n  button,\n  [type=\"button\"],\n  [type=\"reset\"],\n  [type=\"submit\"] {\n    -webkit-appearance: button;\n  }\n  \n  /**\n   * Remove the inner border and padding in Firefox.\n   */\n  \n  button::-moz-focus-inner,\n  [type=\"button\"]::-moz-focus-inner,\n  [type=\"reset\"]::-moz-focus-inner,\n  [type=\"submit\"]::-moz-focus-inner {\n    border-style: none;\n    padding: 0;\n  }\n  \n  /**\n   * Restore the focus styles unset by the previous rule.\n   */\n  \n  button:-moz-focusring,\n  [type=\"button\"]:-moz-focusring,\n  [type=\"reset\"]:-moz-focusring,\n  [type=\"submit\"]:-moz-focusring {\n    outline: 1px dotted ButtonText;\n  }\n  \n  /**\n   * Correct the padding in Firefox.\n   */\n  \n  fieldset {\n    padding: 0.35em 0.75em 0.625em;\n  }\n  \n  /**\n   * 1. Correct the text wrapping in Edge and IE.\n   * 2. Correct the color inheritance from `fieldset` elements in IE.\n   * 3. Remove the padding so developers are not caught out when they zero out\n   *    `fieldset` elements in all browsers.\n   */\n  \n  legend {\n    box-sizing: border-box; /* 1 */\n    color: inherit; /* 2 */\n    display: table; /* 1 */\n    max-width: 100%; /* 1 */\n    padding: 0; /* 3 */\n    white-space: normal; /* 1 */\n  }\n  \n  /**\n   * Add the correct vertical alignment in Chrome, Firefox, and Opera.\n   */\n  \n  progress {\n    vertical-align: baseline;\n  }\n  \n  /**\n   * Remove the default vertical scrollbar in IE 10+.\n   */\n  \n  textarea {\n    overflow: auto;\n  }\n  \n  /**\n   * 1. Add the correct box sizing in IE 10.\n   * 2. Remove the padding in IE 10.\n   */\n  \n  [type=\"checkbox\"],\n  [type=\"radio\"] {\n    box-sizing: border-box; /* 1 */\n    padding: 0; /* 2 */\n  }\n  \n  /**\n   * Correct the cursor style of increment and decrement buttons in Chrome.\n   */\n  \n  [type=\"number\"]::-webkit-inner-spin-button,\n  [type=\"number\"]::-webkit-outer-spin-button {\n    height: auto;\n  }\n  \n  /**\n   * 1. Correct the odd appearance in Chrome and Safari.\n   * 2. Correct the outline style in Safari.\n   */\n  \n  [type=\"search\"] {\n    -webkit-appearance: textfield; /* 1 */\n    outline-offset: -2px; /* 2 */\n  }\n  \n  /**\n   * Remove the inner padding in Chrome and Safari on macOS.\n   */\n  \n  [type=\"search\"]::-webkit-search-decoration {\n    -webkit-appearance: none;\n  }\n  \n  /**\n   * 1. Correct the inability to style clickable types in iOS and Safari.\n   * 2. Change font properties to `inherit` in Safari.\n   */\n  \n  ::-webkit-file-upload-button {\n    -webkit-appearance: button; /* 1 */\n    font: inherit; /* 2 */\n  }\n  \n  /* Interactive\n     ========================================================================== */\n  \n  /*\n   * Add the correct display in Edge, IE 10+, and Firefox.\n   */\n  \n  details {\n    display: block;\n  }\n  \n  /*\n   * Add the correct display in all browsers.\n   */\n  \n  summary {\n    display: list-item;\n  }\n  \n  /* Misc\n     ========================================================================== */\n  \n  /**\n   * Add the correct display in IE 10+.\n   */\n  \n  template {\n    display: none;\n  }\n  \n  /**\n   * Add the correct display in IE 10.\n   */\n  \n  [hidden] {\n    display: none;\n  }\n  ","@use 'variables' as v;\n@use 'mixins' as m;\n\nhtml {\n    font-size: 62.5%;\n    box-sizing: border-box;\n    height: 100%;\n}\n\n*,\n*:before,\n*:after {\n    box-sizing: inherit;\n}\n\n// body {\n//     font-family: v.$fuente_principal;\n//     font-size: 1.8rem;\n//     height: 100%;\n// }\n\nbody {\n    font-family: v.$fuente_principal;\n    font-size: 1.8rem;\n    min-height: 100%;\n    display: flex;\n    flex-direction: column;\n}\n\n\na {\n    text-decoration: none;\n}\n\nimg {\n    width: 100%;\n    height: auto;\n}\n\n.swal2-popup {\n    font-size: 2rem !important;\n}\n","// Fuentes\n$fuente-principal: 'Outfit', sans-serif;\n\n// Tamaño de Media Queries\n$telefono: 390px;\n$tablet: 768px;\n$desktop: 1024px;\n$xl_desktop: 1200px;\n\n// Colores\n$azul: #007df4;\n$azul-oscuro: #001f3f;\n\n$secundario: #00c8c2;\n$celeste: #4ac4f5;\n\n$tecnico: #58d68d;\n\n$tesorero: #ec7063;\n\n$lecturador: #de1609;\n\n$primario: #0077b6;\n$secundario: #00b4d8;\n\n\n$negro: #1a1b15;\n$blanco: #FFFFFF;\n$gris: #64748B;\n$gris-claro: #F8FAFC;\n$gris-oscuro: #1E293B;\n\n// Opciones alternativas si deseas otros tonos:\n$grisOscuroSuave: #3a3a3a;\n$grisOscuroMedio: #1f1f1f;\n$grisNegro: #121212;\n\n$rojo: rgb(169, 0, 0);\n$verde: #02db02;\n$amarillo: #e5b214;\n\n$rojo-alerta: #dc3545;\n$naranja-alerta: #ff8800; \n\n\n\n\n// Tipografías\n$light: 300;\n$regular: 400;\n$medium: 500;\n$bold: 700;\n$black: 900;\n\n\n$morado: #8e44ad;\n$naranja: #e67e22;\n$verde-suave: #2ecc71;\n// Fuentes\n$delgada: 300;\n$regular: 400;\n$bold: 700;\n$black: 900","@use 'variables' as v;\n@use 'mixins' as m;\n\nh1, h2, h3 {\n    @include m.headings;\n}\n\nh1 {\n    font-size: 4rem;\n}\nh2 {\n    font-size: 3.6rem;\n}\nh3 {\n    font-size: 3rem;\n}\n.text-center {\n    text-align: center;\n}\n\n[class$=\"__heading\"] {\n    @include m.nombre-pagina;\n}\n[class$=\"__descripcion\"] {\n    @include m.descripcion-pagina;\n}","@use 'variables' as v;\n\n/** Media Queries **/\n@mixin telefono {\n    @media (min-width: v.$telefono) {\n        @content;\n    }\n}\n\n@mixin tablet {\n    @media (min-width: v.$tablet) {\n        @content;\n    }\n}\n\n@mixin desktop {\n    @media (min-width: v.$desktop) {\n        @content;\n    }\n}\n\n@mixin xl_desktop {\n    @media (min-width: v.$xl_desktop) {\n        @content;\n    }\n}\n\n@mixin boton($bgColor, $colorTexto) {\n    background-color: $bgColor;\n    padding: 1.5rem 4rem;\n    color: $colorTexto;\n    font-size: 1.8rem;\n    font-weight: 700;\n    border: none;\n    transition-property: background-color;\n    transition-duration: .3s;\n    text-align: center;\n    width: 100%;\n    display: inline-block;\n\n    &:hover {\n        background-color: darken($bgColor, 10%);\n        cursor: pointer;\n    }\n}\n\n@mixin grid($columnas, $espaciado ) {\n    display: grid;\n    gap: $espaciado;\n    grid-template-columns: repeat($columnas, 1fr);\n}\n\n@mixin contenedor {\n    width: min(95%, 140rem);\n    margin: 0 auto;\n}\n\n@mixin contenedor-l {\n    width: min(95%, 100rem);\n    margin: 0 auto;\n}\n\n@mixin contenedor-md {\n    width: min(95%, 80rem);\n    margin: 0 auto;\n}\n\n@mixin contenedor-sm {\n    width: min(95%, 60rem);\n    margin: 0 auto;\n}\n\n@mixin headings {\n    font-family: v.$fuente_principal;\n    font-weight: v.$black;\n    margin: 2rem 0;\n}\n\n@mixin nombre-pagina {\n    @include headings;\n    margin: 6rem 0 3rem 0;\n    text-align: center;\n}\n\n@mixin descripcion-pagina {\n    text-align: center;\n    font-size: 1.8rem;\n    font-weight: v.$delgada;\n    color: v.$gris-oscuro;\n    margin-bottom: 5rem;\n}\n\n@mixin texto-fluido($min, $max) {\n    font-size: clamp($min, -0.8rem + 10vw, $max);\n}\n\n@mixin texto-degradado($inicio, $final) {\n    background: linear-gradient(to right, $inicio, $final);\n    background-clip: text;\n    color: transparent;\n}\n\n@mixin logo {\n    color: v.$blanco;\n    text-align: center;\n    margin-bottom: 2rem;\n    white-space: nowrap; //evitar salto\n\n    @include desktop {\n        text-align: left;\n        margin: 0;\n    }\n}\n\n@mixin menu-social($color, $size) {\n\n    &__enlace {\n\n        &::before {\n            color: $color;\n            font-size: $size;\n            display: inline-block;\n            font-style: normal;\n            text-rendering: auto;\n            -webkit-font-smoothing: antialiased;\n            font-family: \"Font Awesome 6 Brands\";\n        }\n\n        &[href*=\"facebook.com\"]::before {\n            content: \"\\f39e\";\n        }\n\n        &[href*=\"github.com\"]::before {\n            content: \"\\f09b\";\n        }\n\n        &[href*=\"tiktok.com\"]::before {\n            content: \"\\e07b\";\n        }\n\n        &[href*=\"instagram.com\"]::before {\n            content: \"\\f16d\";\n        }\n\n        &[href*=\"youtube.com\"]::before {\n            content: \"\\f167\";\n        }\n\n        &[href*=\"twitter.com\"]::before {\n            content: \"\\f099\";\n        }\n    }\n\n    &__ocultar {\n        display: none;\n    }\n}\n\n@mixin enlace {\n    all: unset;\n    color: v.$blanco;\n    font-size: 1.4rem;\n    text-transform: uppercase;\n    font-weight: v.$bold;\n\n    &:hover {\n        color: v.$azul;\n        cursor: pointer;\n    }\n}\n\n@mixin shadow {\n    box-shadow: rgba(50, 50, 93, 0.25) 0px 13px 27px -5px, rgba(0, 0, 0, 0.3) 0px 8px 16px -8px;\n}\n\n@mixin shadow-lg {\n    box-shadow:\n        0 20px 35px rgba(0, 119, 182, 0.25),\n        0 10px 15px rgba(0, 0, 0, 0.15);\n}\n\n@mixin reset-lista {\n    margin: 0;\n    padding: 0;\n    list-style: none;\n}\n\n@mixin tags {\n    @include reset-lista;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 1.5rem;\n    margin-top: 1.5rem;\n\n    >li {\n        background-color: v.$azul;\n        padding: 1rem;\n        border-radius: .5rem;\n        font-size: 1.4rem;\n        font-weight: v.$bold;\n        color: v.$blanco;\n    }\n}\n\n@mixin card {\n    border: 1px solid lighten(v.$gris, 10);\n    padding: 3rem;\n\n    &__nombre {\n        font-weight: v.$black;\n        font-size: 2.6rem;\n        margin: 2rem 0;\n    }\n}\n\n@mixin bg-gradient($bg_color) {\n    background-image: linear-gradient(to left top, $bg_color, lighten($bg_color, 15%));\n}","*,\r\n*::after,\r\n*::before {\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n}\r\n\r\n.body-slider {\r\n    min-block-size: 68vh;\r\n    display: flex;\r\n    flex-direction: column;\r\n    justify-content: center;\r\n    align-items: center;\r\n    background-color: #e1e3e5;\r\n}\r\n\r\n.image-slider {\r\n    display: flex;\r\n    flex-flow: column;\r\n    width: clamp(360px, 96vw, 830px);\r\n    aspect-ratio: 16 / 9;\r\n    min-height: 300px;\r\n    overflow: hidden;\r\n    border-radius: 8px;\r\n    container-type: inline-size;\r\n    contain: content;\r\n    background-color: #0006;\r\n    box-shadow: rgba(0, 0, 0, 0.2) 0px 1px 2px, rgba(0, 0, 0, 0.3) 0px 2px 4px,\r\n        rgba(0, 0, 0, 0.25) 0px 4px 8px, rgba(0, 0, 0, 0.2) 0px 8px 16px,\r\n        rgba(0, 0, 0, 0.15) 0px 16px 32px;\r\n}\r\n\r\n.slider__content {\r\n    flex-grow: 1;\r\n    display: flex;\r\n    justify-content: space-between;\r\n}\r\n\r\n.slider-control--button {\r\n    border: 0;\r\n    background: 0;\r\n    outline: 0;\r\n    cursor: pointer;\r\n    place-content: center;\r\n    padding-inline: 3vw;\r\n    z-index: 1;\r\n    display: grid;\r\n}\r\n\r\n.icon {\r\n    height: 2rem;\r\n    width: 2rem;\r\n    fill: var(hsl(203 5 75));\r\n    border-radius: 50%;\r\n}\r\n\r\n.slider-control--button:where(:hover) {\r\n    background-image: linear-gradient(\r\n        to var(--position),\r\n        #0000 0%,\r\n        #0002,\r\n        80%,\r\n        #0006 100%\r\n    );\r\n    .icon {\r\n        fill: hsl(203 15 98);\r\n        background: #0001;\r\n    }\r\n}\r\n\r\n.slider-control--button:active {\r\n    outline: 0.2em solid hsl(204 100 53);\r\n    outline-offset: -0.5em;\r\n}\r\n\r\n.prev-button {\r\n    --position: left;\r\n}\r\n.next-button {\r\n    --position: right;\r\n}\r\n\r\n.image-display {\r\n    position: fixed;\r\n    inset: 0;\r\n}\r\n\r\n.slider-navigation {\r\n    z-index: 10;\r\n    display: grid;\r\n    grid-auto-flow: column;\r\n    grid-template-columns: repeat(6, 1fr);\r\n    grid-auto-columns: 100%;\r\n    gap: 1.25rem;\r\n    padding: 1rem;\r\n    place-content: center;\r\n    background-color: hsl(203 5 25 / 0.3);\r\n    backdrop-filter: blur(6px);\r\n}\r\n\r\n.nav-button {\r\n    display: grid;\r\n    width: 100%;\r\n    height: 100%;\r\n    border-radius: 0.5em;\r\n    overflow: hidden;\r\n    align-items: center;\r\n    justify-content: center;\r\n    border: 0;\r\n    aspect-ratio: 16 / 9;\r\n    transition: filter 150ms linear, scale 266ms ease;\r\n}\r\n\r\n.thumbnail {\r\n    display: block;\r\n    max-width: 100%;\r\n    width: 100%;\r\n    object-fit: cover;\r\n    height: 100%;\r\n}\r\n\r\n.nav-button[aria-selected=\"true\"] {\r\n    scale: 1.1;\r\n}\r\n\r\n.nav-button[aria-selected=\"true\"],\r\n.nav-button:focus-visible {\r\n    outline: 0.2em solid  hsl(204 100 53);\r\n    outline-offset: 0.2em;\r\n}\r\n\r\n.nav-button[aria-selected=\"false\"] {\r\n    filter: opacity(0.7);\r\n}\r\n\r\n.nav-button[aria-selected=\"false\"]:where(:hover, :focus-visible) {\r\n    filter: opacity(1);\r\n}\r\n\r\n@container (max-width: 660px) {\r\n    .nav-button:not(:has(img)) {\r\n        background-color: rgb(241, 235, 232);\r\n    }\r\n\r\n    .slider-navigation {\r\n        display: flex;\r\n        justify-content: center;\r\n        padding-block: 1.5em;\r\n    }\r\n\r\n    .nav-button {\r\n        inline-size: 0.625rem;\r\n        aspect-ratio: 1;\r\n        border-radius: 50%;\r\n    }\r\n\r\n    .nav-button > .thumbnail {\r\n        display: none;\r\n    }\r\n\r\n    .nav-button[aria-selected=\"true\"] {\r\n        background-color: black;\r\n        scale: 1.5;\r\n    }\r\n}\r\n","\r\n\r\n.carrusel {\r\n\r\n    background: #eaeaea;\r\n    overflow: hidden;\r\n    position: relative; /* Asegura que el carrusel permanezca dentro de esta sección */\r\n    height: 100vh; /* Asegura que cubra toda la pantalla si es necesario */\r\n\r\n\r\n}\r\n\r\n.carrusel_contenedor {\r\n    margin-top: 0;\r\n    position: relative; /* Mantiene el carrusel dentro de su sección */\r\n    top: 50%;\r\n    left: 50%;\r\n    transform: translate(-50%, -50%);\r\n    width: 1000px;\r\n    height: 600px;\r\n    background: #f5f5f5;\r\n    box-shadow: 0 30px 50px #dbdbdb;\r\n}\r\n\r\n\r\n.carrusel_contenedor .slide .item {\r\n    width: 200px;\r\n    height: 300px;\r\n    position: absolute;\r\n    top: 50%;\r\n    transform: translate(0, -50%);\r\n    border-radius: 20px;\r\n    box-shadow: 0 30px 50px #505050;\r\n    background-position: 50% 50%;\r\n    background-size: cover;\r\n    background-repeat: no-repeat;\r\n    display: inline-block;\r\n    transition: .5s;\r\n}\r\n\r\n.slide .item:nth-child(1),\r\n.slide .item:nth-child(2) {\r\n    top: 0;\r\n    left: 0;\r\n    transform: translate(0, 0);\r\n    border-radius: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n}\r\n\r\n.slide .item:nth-child(2) .content {\r\n    display: block;\r\n}\r\n\r\n.slide .item:nth-child(3) {\r\n    left: 50%;\r\n}\r\n\r\n.slide .item:nth-child(4) {\r\n    left: calc(50% + 220px);\r\n}\r\n\r\n.slide .item:nth-child(5) {\r\n    left: calc(50% + 440px);\r\n}\r\n\r\n.slide .item:nth-child(n + 6) {\r\n    left: calc(50% + 440px);\r\n    overflow: hidden;\r\n}\r\n\r\n.item .content {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 100px;\r\n    width: 300px;\r\n    text-align: left;\r\n    color: #eee;\r\n    transform: translate(0, -50%);\r\n    font-family: system-ui;\r\n    display: none;\r\n}\r\n\r\n.content .name {\r\n    font-size: 40px;\r\n    text-transform: uppercase;\r\n    font-weight: bold;\r\n    opacity: 0;\r\n    animation: animate 1s ease-in-out 1 forwards;\r\n}\r\n\r\n.content .description {\r\n    margin-top: 10px;\r\n    margin-bottom: 20px;\r\n    opacity: 0;\r\n    animation: animate 1s ease-in-out .3s 1 forwards;\r\n}\r\n\r\n.content button {\r\n    padding: 10px 20px;\r\n    border: none;\r\n    cursor: pointer;\r\n    opacity: 0;\r\n    animation: animate 1s ease-in-out .6s 1 forwards;\r\n}\r\n\r\n@keyframes animate {\r\n    from {\r\n        opacity: 0;\r\n        transform: translate(0, 100px);\r\n        filter: blur(33px);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: translate(0);\r\n        filter: blur(0);\r\n    }\r\n}\r\n\r\n.button {\r\n    width: 100%;\r\n    text-align: center;\r\n    position: absolute;\r\n    bottom: 20px;\r\n}\r\n\r\n.button button {\r\n    width: 40px;\r\n    height: 35px;\r\n    border-radius: 8px;\r\n    border: none;\r\n    cursor: pointer;\r\n    margin: 0 5px;\r\n    border: 1px solid #000;\r\n    transition: .3s;\r\n}\r\n\r\n.button button:hover {\r\n    background: #ababab;\r\n    color: #fff;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n\r\n.cloneable {\r\n    margin: 5rem 0 5rem 0;\r\n    padding: var(--container-padding);\r\n    justify-content: center;\r\n    align-items: center;\r\n    min-height: 15rem;\r\n    display: flex;\r\n    position: relative;\r\n\r\n    @include m.telefono {\r\n        margin: 4rem 0;\r\n        padding: 2rem;\r\n    }\r\n\r\n    @include m.tablet {\r\n        margin: 5rem 0;\r\n        padding: 3rem;\r\n    }\r\n\r\n    @include m.desktop {\r\n        padding: 4rem;\r\n    }\r\n\r\n    @include m.xl_desktop {\r\n        padding: 5rem;\r\n    }\r\n\r\n}\r\n\r\n.looping-words {\r\n    height: 2.7em;\r\n    padding-left: 0.1em;\r\n    padding-right: 0.1em;\r\n    font-size: 10rem;\r\n    line-height: 0.9;\r\n    position: relative;\r\n    color: v.$azul;\r\n\r\n    @include m.telefono {\r\n        font-size: 4rem;\r\n        height: 2.7em;\r\n    }\r\n\r\n    @include m.tablet {\r\n        font-size: 6rem;\r\n        height: 3em;\r\n    }\r\n\r\n    @include m.desktop {\r\n        font-size: 10rem;\r\n        height: 2.7em;\r\n    }\r\n}\r\n\r\n.looping-words__list {\r\n    text-align: center;\r\n    text-transform: uppercase;\r\n    white-space: nowrap;\r\n    flex-flow: column;\r\n    align-items: center;\r\n    margin: 0;\r\n    padding: 0;\r\n    font-family: PP Neue Corp, sans-serif;\r\n    font-weight: 700;\r\n    list-style: none;\r\n    display: flex;\r\n    position: relative;\r\n\r\n    @include m.telefono {\r\n        font-size: 4rem;\r\n    }\r\n\r\n    @include m.tablet {\r\n        font-size: 6rem;\r\n    }\r\n\r\n    @include m.desktop {\r\n        font-size: 8rem;\r\n    }\r\n\r\n    @include m.xl_desktop {\r\n        font-size: 10rem;\r\n    }\r\n}\r\n\r\n.looping-words__list.is--primary {\r\n    color: v.$rojo;\r\n}\r\n\r\n.looping-words__list.is--gray {\r\n    color: v.$rojo;\r\n}\r\n\r\n.looping-words__fade {\r\n    background-image: linear-gradient(180deg,\r\n            var(--color-neutral-300) 5%,\r\n            transparent 40%,\r\n            transparent 60%,\r\n            var(--color-neutral-300) 95%);\r\n    pointer-events: none;\r\n    width: 100%;\r\n    height: 100%;\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n}\r\n\r\n.looping-words__fade.is--radial {\r\n    background-image: radial-gradient(circle closest-side at 50% 50%,\r\n            transparent 64%,\r\n            v.$rojo 93%);\r\n    width: 140%;\r\n    display: block;\r\n    left: -20%;\r\n}\r\n\r\n.looping-words__selector {\r\n    pointer-events: none;\r\n    width: 100%;\r\n    height: 0.9em;\r\n    position: absolute;\r\n    top: 50%;\r\n    left: 50%;\r\n    transform: translate(-50%, -50%);\r\n}\r\n\r\n.looping-words__edge {\r\n    border-top: 0.035em solid v.$rojo;\r\n    border-left: 0.035em solid v.$rojo;\r\n    width: 0.125em;\r\n    height: 0.125em;\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n}\r\n\r\n.looping-words__edge.is--2 {\r\n    left: auto;\r\n    right: 0;\r\n    transform: rotate(90deg);\r\n}\r\n\r\n.looping-words__edge.is--3 {\r\n    inset: auto 0 0 auto;\r\n    transform: rotate(180deg);\r\n}\r\n\r\n.looping-words__edge.is--4 {\r\n    top: auto;\r\n    bottom: 0;\r\n    transform: rotate(270deg);\r\n}\r\n\r\n.looping-words__containers {\r\n    width: 100%;\r\n    height: 100%;\r\n    position: relative;\r\n    overflow: hidden;\r\n}\r\n\r\n.looping-words__p {\r\n    margin: 0;\r\n}\r\n\r\n@font-face {\r\n    font-family: \"PP Neue Corp\";\r\n    src: url(\"https://cdn.prod.website-files.com/6717aac16c9ea22eeef1e79e/6717de2d56e40b921572d2d9_PPNeueCorp-TightUltrabold.woff2\") format(\"woff2\");\r\n    font-weight: 700;\r\n    font-style: normal;\r\n    font-display: swap;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.devwebcamp {\r\n\r\n    padding-bottom:6rem;\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 3rem);\r\n        @include m.tablet {\r\n            @include m.grid(2, 5rem);\r\n            align-items: center;\r\n        }\r\n    }\r\n\r\n    &__texto {\r\n        line-height: 2;\r\n    }\r\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.paquetes {\n\n    &__grid {\n        padding-bottom: 20rem;\n        @include m.contenedor;\n        @include m.grid(1, 3rem);\n\n        @include m.tablet {\n            @include m.grid(3, 3rem);\n            align-items: flex-start;\n        }\n    }\n\n    &__submit {\n        @include m.boton(v.$azul, v.$blanco);\n        margin-top: 3rem;\n    }\n}\n\n.paquete {\n    @include m.card;\n\n    &:nth-child(2) {\n        order: -1; //ordenar en celular el paquete mas caro es el primero \n\n        @include m.tablet {\n            order: unset;\n        }\n    }\n\n    &__lista {\n        @include m.reset-lista;\n        line-height: 2;\n    }\n\n    &__precio {\n        font-size: 6rem;\n        margin: 3rem 0;\n        color: v.$azul;\n        font-weight: v.$black;\n        text-align: center;\n    }\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.agenda {\r\n    padding: 6rem 0;\r\n    @include m.contenedor;\r\n}\r\n\r\n.eventos {\r\n    $modificador: &; //cambio de color a titulo workshops\r\n\r\n    &__heading {\r\n        color: v.$azul;\r\n        margin: 5rem 0;\r\n        text-align: left;\r\n        font-size: clamp(2rem, -0.8rem + 8vw, 6rem);\r\n    }\r\n\r\n    &__fecha {\r\n        color: v.$gris;\r\n        margin: 3rem 0 1rem 0;\r\n    }\r\n\r\n    &--workshops {\r\n\r\n        #{$modificador}__heading {\r\n            //cambio de color de workshops\r\n            color: v.$secundario;\r\n        }\r\n\r\n        .evento__informacion {\r\n            background-color: v.$secundario;//cambiar de color\r\n\r\n            &:hover {\r\n                background-color: darken(v.$secundario, 10%);\r\n            }\r\n        }\r\n    }\r\n\r\n    .swiper-button-next,\r\n    .swiper-button-prev {\r\n        color: rgba(v.$blanco, .5);\r\n    }\r\n\r\n    .swiper-pagination {\r\n        position: relative;\r\n        margin-top: 2rem;\r\n\r\n        /* ajusta el valor según sea necesario */\r\n        &--conferencias {\r\n            color: darken(v.$azul, 20%);\r\n\r\n        }\r\n        &--workshops {\r\n            color: darken(v.$secundario, 20%);\r\n        }\r\n\r\n    }\r\n}\r\n\r\n.evento {\r\n    \r\n    &__hora {\r\n        font-weight: v.$bold;\r\n    }\r\n    &__enlace{\r\n        all: unset;\r\n    }\r\n    &__informacion {\r\n        padding: 2rem;\r\n        border-radius: 1rem;\r\n        background-color: v.$azul;\r\n        color: v.$blanco;\r\n        transition: 300ms background-color ease;\r\n\r\n        &:hover {\r\n            background-color: darken(v.$azul, 10%);\r\n        }\r\n    }\r\n\r\n    &__nombre {\r\n        font-size: 2rem;\r\n        margin: 0;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 1;\r\n        -webkit-box-orient: vertical;\r\n        overflow: hidden;\r\n    }\r\n\r\n    &__introduccion {\r\n        //recortar texto\r\n        font-size: 1.6rem;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 2; //cuantas lineas de texto quieres\r\n        -webkit-box-orient: vertical;\r\n        overflow: hidden;\r\n    }\r\n\r\n    &__autor-info {\r\n        display: flex;\r\n        gap: 2rem;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n    }\r\n\r\n    &__imagen-autor {\r\n        width: 5rem;\r\n        background-color: v.$blanco;\r\n        border-radius: 50%;\r\n    }\r\n\r\n    &__autor-nombre {\r\n        font-weight: v.$bold;\r\n    }\r\n    &__agregar {\r\n        @include m.boton(v.$blanco,v.$negro);\r\n        margin-top: 1rem;\r\n    }\r\n\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.resumen {\r\n    background-image: linear-gradient(to right, rgba(v.$gris-oscuro, .7), rgba(v.$gris-oscuro, .9)), url(../img/resumen_index.jpg);\r\n    background-image: linear-gradient(to right, rgba(v.$gris-oscuro, .7), rgba(v.$gris-oscuro, .9)), image-set(\r\n        url('../img/resumen_index.avif') 1x,\r\n        url('../img/resumen_index.webp') 1x,\r\n        url('../img/resumen_index.jpg') 1x,\r\n    );\r\n    padding: 12rem 0 30rem;\r\n    background-size: cover;\r\n    background-position: center;\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 5rem);\r\n        @include m.tablet {\r\n            @include m.grid(2, 5rem);\r\n        }\r\n    }\r\n\r\n    &__bloque {\r\n        text-align: center;\r\n        color: v.$blanco;\r\n    }\r\n\r\n    &__texto {\r\n        font-weight: v.$black;\r\n        line-height: 1;\r\n        margin: 0;\r\n        font-size: 2.4rem;\r\n        text-transform: uppercase;\r\n\r\n        &--numero {\r\n            @extend .resumen__texto;\r\n            font-size: 8rem;\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.speakers {\r\n    margin-bottom: 6rem;\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 5rem);\r\n        @include m.tablet {\r\n            @include m.grid(2, 5rem);\r\n        }\r\n        @include m.xl_desktop {\r\n            @include m.grid(3, 5rem);\r\n        }\r\n    }\r\n}\r\n\r\n.speaker {\r\n    @include m.card;\r\n    background-position: center top;\r\n    background-size: 350px;\r\n    background-repeat: no-repeat;\r\n\r\n    @for $i from 1 through 4 {//fondos aleatorios \r\n        &:nth-child(4n + #{$i}) {\r\n            background-image: image-set(\r\n                url('../img/bg_#{$i}.avif') 1x,\r\n                url('../img/bg_#{$i}.webp') 1x,\r\n                url('../img/bg_#{$i}.png') 1x\r\n            );\r\n        }\r\n    }\r\n\r\n    &__imagen {\r\n        min-width: 350px;\r\n        @include m.tablet {\r\n            min-width: unset;\r\n        }\r\n    }\r\n\r\n    &__ubicacion {\r\n        color: v.$gris;\r\n        margin: 1rem 0;\r\n        font-size: 2rem;\r\n        line-height: 1.5;\r\n    }\r\n    &__listado-skills {\r\n        @include m.tags;\r\n    }\r\n}\r\n\r\n.speaker-sociales {\r\n    @include m.menu-social(v.$negro, 3rem);\r\n    display: flex;\r\n    gap: 2rem;\r\n    margin-top: 2rem;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.mapa {\r\n    &__heading {\r\n        margin: 0;\r\n        text-align: center;\r\n        margin-bottom: 2rem;\r\n    }\r\n    &__texto {\r\n        font-size: 1.8rem;\r\n        margin: 0;\r\n        padding-bottom: 2rem\r\n    }\r\n\r\n    &__descripcion {\r\n        @include m.contenedor-md;\r\n        text-align: justify;\r\n    }\r\n    &__mapa{\r\n        height: 45rem;\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.masinformacion {\r\n    flex: 1;\r\n    padding-bottom: 6rem;\r\n\r\n    &__grid {\r\n        @include m.contenedor;\r\n\r\n        @include m.telefono {\r\n            @include m.grid(1, 2rem);\r\n        }\r\n\r\n        @include m.desktop {\r\n            @include m.grid(2, 3rem);\r\n        }\r\n    }\r\n}\r\n\r\n.masinformacion__informacion {\r\n    @include m.contenedor-sm;\r\n    @include m.card;\r\n\r\n    background-image: image-set(url('../img/bg_4.avif') 1x,\r\n            url('../img/bg_4.webp') 1x,\r\n            url('../img/bg_4.png') 1x);\r\n    background-repeat: no-repeat;\r\n    background-size: cover;\r\n    background-position: center;\r\n    border-radius: 1.5rem;\r\n    overflow: hidden;\r\n    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.1);\r\n    transition: transform 0.4s ease, box-shadow 0.4s ease;\r\n\r\n    &:hover {\r\n        transform: translateY(-10px);\r\n        box-shadow: 0 25px 50px rgba(0, 0, 0, 0.15);\r\n    }\r\n\r\n    padding: 3rem;\r\n    backdrop-filter: blur(4px);\r\n    background-color: rgba(255, 255, 255, 0.75);\r\n\r\n    &__imagen {\r\n        max-width: 100%;\r\n        height: auto;\r\n        border-radius: 1rem;\r\n        box-shadow: 0 10px 20px rgba(0, 0, 0, 0.05);\r\n        margin-bottom: 2rem;\r\n\r\n    }\r\n\r\n    &__texto {\r\n        text-align: justify;\r\n        line-height: 1.8;\r\n        font-size: 2rem;\r\n        color: v.$gris-oscuro;\r\n        font-weight: 400;\r\n\r\n\r\n        p {\r\n            margin-bottom: 1.5rem;\r\n        }\r\n\r\n        strong {\r\n            color: v.$primario;\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.boletos {\r\n    margin-bottom: 10rem;\r\n\r\n    &__grid {\r\n        @include m.contenedor-sm;\r\n        @include m.grid(1, 5rem);\r\n    }\r\n}\r\n\r\n.boleto {\r\n    width: min(100% - 5rem, 65rem);\r\n    margin: 0 auto;\r\n    padding: 6rem;\r\n    border-radius: 2rem;\r\n    color: v.$blanco;\r\n    position: relative;\r\n\r\n    &::before,\r\n    &::after {\r\n        position: absolute;\r\n        content: '';\r\n        background-color: v.$blanco;\r\n        width: 5rem;\r\n        height: 5rem;\r\n        top: calc(50% - 2.5rem); //en el centro\r\n    }\r\n\r\n    &::before {\r\n        clip-path: circle(50% at 25% 50%);\r\n        left: 0; //pegado a la izquierda\r\n    }\r\n\r\n    &::after {\r\n        clip-path: circle(50% at 75% 50%);\r\n        right: 0; //pegado a la derecha\r\n    }\r\n\r\n    &--presencial {\r\n        background-color: hsla(178, 100%, 39%, 1);\r\n        background-image:\r\n            radial-gradient(at 40% 20%, hsla(209, 100%, 47%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 80% 0%, hsla(178, 100%, 39%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 69% 82%, hsla(209, 100%, 47%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 26% 91%, hsla(178, 100%, 39%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 100%, hsla(209, 100%, 47%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 27% 22%, hsla(178, 100%, 39%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 0% 0%, hsla(209, 100%, 47%, 1) 0px, transparent 50%);\r\n    }\r\n\r\n\r\n    &--virtual {\r\n        background-color: v.$secundario;\r\n    }\r\n\r\n    &--gratis {\r\n        background-color: v.$azul;\r\n    }\r\n\r\n    // ANIMACIONES POR ESTADO\r\n    @keyframes parpadeo-pendiente {\r\n\r\n        0%,\r\n        100% {\r\n            background-color: #ffd500;\r\n            box-shadow: 0 0 5px #ffd500;\r\n        }\r\n\r\n        50% {\r\n            background-color: darken(#ffd500, 10%);\r\n            box-shadow: 0 0 20px #ffd500;\r\n        }\r\n    }\r\n\r\n    @keyframes parpadeo-aprobado {\r\n\r\n        0%,\r\n        100% {\r\n            background-color: #8e24aa;\r\n            box-shadow: 0 0 5px #8e24aa;\r\n        }\r\n\r\n        50% {\r\n            background-color: darken(#8e24aa, 10%);\r\n            box-shadow: 0 0 20px #8e24aa;\r\n        }\r\n    }\r\n\r\n    @keyframes parpadeo-rechazado {\r\n\r\n        0%,\r\n        100% {\r\n            background-color: #d50000;\r\n            box-shadow: 0 0 5px #d50000;\r\n        }\r\n\r\n        50% {\r\n            background-color: darken(#d50000, 10%);\r\n            box-shadow: 0 0 20px #d50000;\r\n        }\r\n    }\r\n\r\n    @keyframes parpadeo-proceso {\r\n\r\n        0%,\r\n        100% {\r\n            background-color: #2979ff;\r\n            box-shadow: 0 0 5px #2979ff;\r\n        }\r\n\r\n        50% {\r\n            background-color: darken(#2979ff, 10%);\r\n            box-shadow: 0 0 20px #2979ff;\r\n        }\r\n    }\r\n\r\n    @keyframes parpadeo-realizado {\r\n\r\n        0%,\r\n        100% {\r\n            background-color: #00c853;\r\n            box-shadow: 0 0 5px #00c853;\r\n        }\r\n\r\n        50% {\r\n            background-color: darken(#00c853, 10%);\r\n            box-shadow: 0 0 20px #00c853;\r\n        }\r\n    }\r\n\r\n    // ESTILOS POR ESTADO\r\n    &--pendiente {\r\n        background-color: #ffd500;\r\n        color: #000;\r\n        animation: parpadeo-pendiente 1s infinite;\r\n    }\r\n\r\n    &--aprobado {\r\n        background-color: #8e24aa;\r\n        color: #fff;\r\n        animation: parpadeo-aprobado 1s infinite;\r\n    }\r\n\r\n    &--rechazado {\r\n        background-color: #d50000;\r\n        color: #fff;\r\n        animation: parpadeo-rechazado 1s infinite;\r\n    }\r\n\r\n    &--proceso {\r\n        background-color: #2979ff;\r\n        color: #fff;\r\n        animation: parpadeo-proceso 1s infinite;\r\n    }\r\n\r\n    &--realizado {\r\n        background-color: #00c853;\r\n        color: #fff;\r\n        animation: parpadeo-realizado 1s infinite;\r\n    }\r\n\r\n\r\n\r\n    &__logo {\r\n        @include m.logo;\r\n        @include m.texto-fluido(2rem, 4rem);\r\n    }\r\n\r\n    &__plan {\r\n        font-size: 2rem;\r\n        text-transform: uppercase;\r\n        margin: 3rem 0 0 0;\r\n    }\r\n\r\n    &__observacion {\r\n        font-size: 1.5rem;\r\n        text-transform: uppercase;\r\n        margin: 1rem 0 0 0;\r\n    }\r\n\r\n    &__precio {\r\n        margin: 3rem 0 0 0;\r\n        font-weight: v.$black;\r\n        font-size: 4rem;\r\n    }\r\n\r\n    &__enlace-contenedor {\r\n        margin-top: 5rem;\r\n        display: flex;\r\n        justify-content: center;\r\n    }\r\n\r\n    &__enlace {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        width: auto;\r\n    }\r\n\r\n    $modificador: &;\r\n\r\n    &--acceso {\r\n        width: 30rem;\r\n        height: 50rem;\r\n        padding: 10rem 3rem;\r\n\r\n        @include m.tablet {\r\n            width: 60rem;\r\n            height: 30rem;\r\n            padding: 6rem;\r\n            display: flex;\r\n            flex-direction: column;\r\n            justify-content: center;\r\n\r\n        }\r\n\r\n        #{$modificador}__logo {\r\n            @include m.texto-fluido(2rem, 3rem);\r\n            margin: 0;\r\n            text-align: left;\r\n\r\n        }\r\n\r\n        #{$modificador}__nombre {\r\n            font-size: 2.4rem;\r\n            text-transform: uppercase;\r\n            font-weight: v.$black;\r\n\r\n        }\r\n\r\n        #{$modificador}__codigo {\r\n            font-size: 3rem;\r\n            font-weight: bold;\r\n            text-align: center;\r\n            position: absolute;\r\n            bottom: 7rem;\r\n            margin: 0;\r\n            left: 0;\r\n            width: 100%;\r\n\r\n            @include m.tablet {\r\n\r\n                rotate: 90deg;\r\n                transform-origin: 0 0; //resetear posicion absoluta\r\n                width: 30rem;\r\n                top: 0;\r\n                left: calc(100% - 5rem);\r\n\r\n            }\r\n        }\r\n\r\n    }\r\n\r\n    &::before {\r\n        clip-path: circle(50% at 50% 25%);\r\n        left: calc(50% - 2.5rem);\r\n        top: 0;\r\n\r\n        @include m.tablet {\r\n            clip-path: circle(50% at 25% 50%);\r\n            left: 0; //pegado a la izquierda\r\n            top: calc(50% - 2.5rem); //en el centro\r\n\r\n        }\r\n    }\r\n\r\n    &::after {\r\n        clip-path: circle(50% at 50% 75%);\r\n        left: calc(50% - 2.5rem);\r\n        top: calc(100% - 5rem);\r\n\r\n        @include m.tablet {\r\n            clip-path: circle(50% at 75% 50%);\r\n            left: calc(100% - 5rem);\r\n            top: calc(50% - 2.5rem); //en el centro\r\n        }\r\n    }\r\n\r\n}\r\n\r\n.boleto-virtual {\r\n    margin-bottom: 6rem;\r\n}","@use 'base/variables' as v;\r\n\r\n.pagina_404 {\r\n\r\n    min-height: 60rem;\r\n    margin-top: 0;\r\n    \r\n    background-image: image-set(\r\n        url(../img/404.avif) 1x,\r\n        url(../img/404.webp) 1x,\r\n        url(../img/404.jpg) 1x\r\n    );\r\n    \r\n    background-repeat: no-repeat;\r\n    background-size: cover;\r\n    background-position: center;\r\n\r\n    &__contenedor {\r\n\r\n        text-align: center;\r\n    }\r\n\r\n    &__heading {\r\n        margin-top: 0;\r\n        color: v.$blanco;\r\n        padding-top: 3rem;\r\n    }\r\n\r\n    &__texto {\r\n        color: v.$blanco;\r\n        font-size: 2rem;\r\n        margin-bottom: 2rem;\r\n\r\n    }\r\n\r\n    &__enlace {\r\n        color: v.$azul;\r\n        font-size: 3rem;\r\n    }\r\n \r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.nosotros {\r\n    flex: 1;\r\n    position: relative;\r\n    background: linear-gradient(135deg, v.$blanco 0%, v.$celeste 100%);\r\n    padding: 2rem 2rem 12rem;\r\n    color: #222; // texto negro suave para mejor lectura\r\n    overflow: hidden;\r\n\r\n    @include m.tablet {\r\n        padding: 2rem 4rem 12rem;\r\n    }\r\n\r\n    &__heading {\r\n        @include m.texto-fluido(3rem, 5rem);\r\n        font-weight: 900;\r\n        color: v.$negro;\r\n        margin: 0 auto 3rem auto; // centrado horizontal\r\n        position: relative;\r\n        text-align: center;\r\n        text-transform: uppercase;\r\n        letter-spacing: 0.2em;\r\n\r\n        &::after {\r\n            content: '';\r\n            position: absolute;\r\n            left: 50%;\r\n            transform: translateX(-50%); // centrado de la línea decorativa\r\n            bottom: -0.75rem;\r\n            width: 6rem;\r\n            height: 0.5rem;\r\n            background: linear-gradient(90deg, v.$rojo, v.$amarillo);\r\n            border-radius: 1rem;\r\n            transition: width 0.4s ease;\r\n        }\r\n\r\n        &:hover::after {\r\n            width: 100%;\r\n        }\r\n    }\r\n\r\n    &__descripcion {\r\n        max-width: 600px;\r\n        font-size: 1.6rem;\r\n        font-weight: 600;\r\n        margin: 0 auto 4rem auto; // centrado horizontal\r\n        color: v.$negro;\r\n        text-align: center;\r\n    }\r\n\r\n    &__grid {\r\n        @include m.contenedor;\r\n        @include m.grid(1, 3rem);\r\n\r\n        @include m.tablet {\r\n            @include m.grid(2, 6rem);\r\n            align-items: center;\r\n        }\r\n    }\r\n\r\n    &__imagen {\r\n        width: 100%;\r\n        border-radius: 2rem;\r\n        box-shadow: 0 12px 25px rgba(0, 0, 0, 0.12);\r\n        transition: transform 0.5s ease, box-shadow 0.3s ease;\r\n\r\n        &:hover {\r\n            transform: scale(1.05) rotate(1deg);\r\n            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.18);\r\n            cursor: pointer;\r\n        }\r\n    }\r\n\r\n    &__contenido {\r\n        animation: fadeInUp 1.2s ease forwards;\r\n        color: v.$negro;\r\n        font-size: 1.7rem;\r\n        line-height: 1.7;\r\n    }\r\n\r\n    &__texto {\r\n        margin-bottom: 2rem;\r\n        color: #333;\r\n    }\r\n\r\n    &__btn {\r\n        display: inline-block;\r\n        background: linear-gradient(90deg, v.$rojo, v.$amarillo);\r\n        padding: 1rem 3rem;\r\n        color: v.$blanco;\r\n        font-weight: 700;\r\n        font-size: 1.8rem;\r\n        border-radius: 3rem;\r\n        text-transform: uppercase;\r\n        box-shadow: 0 8px 15px rgba(255, 100, 50, 0.3);\r\n        transition: background 0.3s ease, transform 0.2s ease;\r\n        user-select: none;\r\n        text-decoration: none;\r\n\r\n        &:hover {\r\n            background: linear-gradient(90deg, v.$amarillo, v.$rojo);\r\n            transform: scale(1.05);\r\n            cursor: pointer;\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.quehacemos {\r\n    flex: 1;\r\n\r\n    &__grid {\r\n        padding-bottom: 12rem;\r\n        @include m.contenedor;\r\n        @include m.grid(1, 3rem);\r\n\r\n        @include m.tablet {\r\n            @include m.grid(2, 3rem);\r\n        }\r\n\r\n        @include m.desktop {\r\n            @include m.grid(3, 3rem);\r\n        }\r\n    }\r\n\r\n    &__submit {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        margin-top: 3rem;\r\n    }\r\n\r\n    &__descripcion {\r\n        @include m.descripcion-pagina;\r\n    }\r\n}\r\n\r\n.hacemos {\r\n    @include m.card;\r\n\r\n    &:nth-child(2) {\r\n        order: -1;\r\n\r\n        @include m.tablet {\r\n            order: unset;\r\n        }\r\n    }\r\n\r\n    &__lista {\r\n        @include m.reset-lista;\r\n        line-height: 2;\r\n    }\r\n\r\n    i {\r\n        margin-top: 2rem;\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        color: v.$azul;\r\n        font-size: 6rem;\r\n    }\r\n\r\n    &__imagen {\r\n        padding-top: 3rem;\r\n        margin: 0 auto;\r\n        max-width: 20rem;\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.agenda {\r\n    flex: 1;\r\n    padding: 6rem 0;\r\n\r\n    @include m.telefono {\r\n        padding: 4rem 2rem;\r\n    }\r\n\r\n    @include m.tablet {\r\n        padding: 5rem 2rem;\r\n    }\r\n\r\n    @include m.desktop {\r\n        padding: 6rem 0;\r\n    }\r\n\r\n    @include m.contenedor;\r\n}\r\n\r\n.noticias {\r\n    $modificador: &;\r\n\r\n    &__heading {\r\n        color: v.$azul;\r\n        margin: 5rem 0;\r\n        text-align: center;\r\n        font-size: clamp(2.4rem, 4vw, 6rem);\r\n        font-weight: 700;\r\n    }\r\n\r\n    &__fecha {\r\n        color: v.$gris;\r\n        margin: 3rem 0 1rem 0;\r\n        font-size: 1.4rem;\r\n\r\n        @include m.tablet {\r\n            font-size: 1.6rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 1.8rem;\r\n        }\r\n    }\r\n\r\n    .swiper-button-next,\r\n    .swiper-button-prev {\r\n        color: v.$secundario;\r\n    }\r\n\r\n    .swiper-pagination {\r\n        position: relative;\r\n        margin-top: 2rem;\r\n    }\r\n}\r\n\r\n.noticia {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 2rem;\r\n    align-items: center;\r\n\r\n    @include m.tablet {\r\n        flex-direction: row;\r\n        gap: 4rem;\r\n    }\r\n\r\n    &__enlace {\r\n        all: unset;\r\n        cursor: pointer;\r\n        display: block;\r\n        width: 100%;\r\n    }\r\n\r\n    &__imagen {\r\n        width: 100%;\r\n        max-width: 40rem;\r\n        height: auto;\r\n        aspect-ratio: 2 / 1;\r\n        background-color: v.$blanco;\r\n        border-radius: 1rem;\r\n        object-fit: cover;\r\n        box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);\r\n\r\n        @include m.tablet {\r\n            height: 20rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            height: 22rem;\r\n        }\r\n    }\r\n\r\n    &__informacion {\r\n        background-color: v.$azul;\r\n        color: v.$blanco;\r\n        border-radius: 1rem;\r\n        padding: 2rem;\r\n        width: 100%;\r\n        transition: background-color 300ms ease;\r\n\r\n        &:hover {\r\n            background-color: darken(v.$azul, 10%);\r\n        }\r\n    }\r\n\r\n    &__nombre {\r\n        font-size: 2rem;\r\n        margin: 0 0 2rem 0;\r\n        font-weight: 600;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 3;\r\n        -webkit-box-orient: vertical;\r\n        overflow: hidden;\r\n\r\n        @include m.tablet {\r\n            font-size: 2.2rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 2.4rem;\r\n        }\r\n    }\r\n\r\n    &__resumen {\r\n        padding-bottom: 1rem;\r\n        font-size: 1.4rem;\r\n        text-align: justify;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 5;\r\n        -webkit-box-orient: vertical;\r\n        overflow: hidden;\r\n\r\n        @include m.tablet {\r\n            font-size: 1.6rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 1.8rem;\r\n        }\r\n    }\r\n}\r\n","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.contacto {\r\n    flex: 1;\r\n\r\n    @include m.contenedor;\r\n\r\n    &__informacion {\r\n        @include m.contenedor-md;\r\n        @include m.grid(1, 2rem);\r\n\r\n        @include m.tablet {\r\n            @include m.grid(3, 2rem);\r\n\r\n        }\r\n    }\r\n\r\n    &__dato {\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n    }\r\n\r\n    &__icono {\r\n        color: v.$azul;\r\n        font-size: 6rem;\r\n        padding-bottom: 1rem;\r\n    }\r\n\r\n    &__texto {\r\n        padding-top: 1rem;\r\n        text-align: center;\r\n    }\r\n\r\n    &__contenido {\r\n        @include m.contenedor;\r\n\r\n        @include m.grid(1, 2rem);\r\n\r\n        @include m.tablet {\r\n            @include m.grid(2, 2rem);\r\n        }\r\n        margin: 2rem 0 6rem 0;\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.servicios-linea {\r\n    flex: 1;\r\n\r\n    @include m.contenedor;\r\n    padding: 2rem 2rem 12rem;\r\n\r\n    &__title {\r\n        text-align: center;\r\n        font-size: 3rem;\r\n        color: v.$azul;\r\n        margin-bottom: 4rem;\r\n\r\n        @include m.tablet {\r\n            font-size: 3.6rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 4rem;\r\n        }\r\n    }\r\n\r\n    &__grid {\r\n        @include m.grid(1, 2rem);\r\n\r\n        @include m.tablet {\r\n            @include m.grid(2, 3rem);\r\n        }\r\n\r\n        @include m.desktop {\r\n            @include m.grid(4, 3rem);\r\n        }\r\n    }\r\n}\r\n\r\n.servicios-linea__item {\r\n    background-color: hsla(229, 71%, 62%, 1);\r\n    background-image:\r\n        radial-gradient(at 89% 86%, hsla(359, 80%, 66%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 95% 65%, hsla(140, 64%, 64%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 13% 79%, hsla(335, 68%, 65%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 67% 8%, hsla(219, 75%, 72%, 1) 0px, transparent 50%);\r\n    padding: 4rem 2rem;\r\n    border-radius: 2rem;\r\n    transition: transform 0.3s ease-in-out, background 0.3s ease-in-out;\r\n    text-align: center;\r\n\r\n    @include m.tablet {\r\n        padding: 5rem 3rem;\r\n    }\r\n\r\n    &:hover {\r\n        background-color: #ff999c;\r\n        background-image:\r\n            radial-gradient(at 62% 99%, hsla(56, 62%, 72%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 50% 27%, hsla(101, 81%, 67%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 64% 41%, hsla(301, 61%, 69%, 1) 0px, transparent 50%),\r\n            radial-gradient(at 61% 86%, hsla(83, 67%, 73%, 1) 0px, transparent 50%);\r\n        cursor: pointer;\r\n        transform: scale(1.05);\r\n    }\r\n\r\n    &-icono {\r\n        font-size: 6rem;\r\n        color: v.$blanco;\r\n        margin-bottom: 2rem;\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n\r\n        @include m.tablet {\r\n            font-size: 7rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 8rem;\r\n        }\r\n    }\r\n\r\n    &-title {\r\n        font-size: 2.4rem;\r\n        color: v.$blanco;\r\n        margin-bottom: 1.5rem;\r\n\r\n        @include m.tablet {\r\n            font-size: 2.6rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 3rem;\r\n        }\r\n    }\r\n\r\n    &-description {\r\n        font-size: 1.6rem;\r\n        color: v.$blanco;\r\n\r\n        @include m.tablet {\r\n            font-size: 1.8rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 2rem;\r\n        }\r\n    }\r\n}\r\n\r\n.requisitos {\r\n    &__titulo {\r\n        font-size: 3rem;\r\n        text-align: center;\r\n        margin-bottom: 3rem;\r\n\r\n        @include m.tablet {\r\n            font-size: 3.5rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            font-size: 4rem;\r\n        }\r\n    }\r\n\r\n    &__lista {\r\n        @include m.contenedor-md;\r\n        @include m.reset-lista;\r\n\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: start;\r\n        margin-left: auto;\r\n        margin-right: auto;\r\n    }\r\n\r\n    &__item {\r\n        padding: 1.5rem 0;\r\n        border-bottom: 1px solid lighten(v.$gris, 30%);\r\n        font-size: 1.6rem;\r\n        line-height: 1.6;\r\n\r\n        @include m.tablet {\r\n            font-size: 1.8rem;\r\n        }\r\n    }\r\n\r\n    &__nota {\r\n        font-size: 1.4rem;\r\n        color: v.$gris-oscuro;\r\n        text-align: center;\r\n        margin-top: 2rem;\r\n\r\n        @include m.tablet {\r\n            font-size: 1.5rem;\r\n        }\r\n    }\r\n\r\n    &__botones {\r\n        padding: 3rem 0;\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 2rem;\r\n        align-items: center;\r\n        justify-content: center;\r\n\r\n        @include m.tablet {\r\n            flex-direction: row;\r\n            gap: 3rem;\r\n        }\r\n    }\r\n\r\n    &__boton {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        width: 100%;\r\n        max-width: 30rem;\r\n        border-radius: 1rem;\r\n\r\n        &:hover {\r\n            background-color: v.$celeste;\r\n        }\r\n    }\r\n}\r\n\r\n//* nueva conexion \r\n.nuevaconexion {\r\n    flex: 1;\r\n    @include m.contenedor;\r\n    @include m.shadow;\r\n    margin-bottom: 10rem;\r\n    margin-top: 2rem;\r\n    padding: 2rem;\r\n    border-radius: 2rem;\r\n}\r\n\r\n.nuevaconexion__formulario {\r\n    background-color: v.$blanco;\r\n\r\n    margin-top: 5rem;\r\n    @include m.contenedor;\r\n\r\n    &__boton {\r\n        margin: 0 auto;\r\n        margin-top: 2rem;\r\n        background-color: v.$azul;\r\n        padding: 1.5rem 4rem;\r\n        color: v.$blanco;\r\n        font-size: 1.8rem;\r\n        font-weight: 700;\r\n        border: none;\r\n        transition-property: background-color;\r\n        transition-duration: .3s;\r\n        text-align: center;\r\n        width: 30rem;\r\n        display: inline-block;\r\n        border-radius: 1rem;\r\n\r\n        &:hover {\r\n            background-color: v.$celeste;\r\n            cursor: pointer;\r\n        }\r\n\r\n        &--rechazar {\r\n            background-color: v.$rojo;\r\n        }\r\n\r\n        &--asignar {\r\n            background-color: hsla(39, 100%, 50%, 1); // Amarillo intenso\r\n        }\r\n\r\n        &--aceptar {\r\n            background-color: v.$verde;\r\n        }\r\n\r\n    }\r\n}\r\n\r\n.formularioservicios {\r\n    &__fieldset {\r\n        @include m.card;\r\n        @include m.shadow;\r\n        border-radius: 1rem;\r\n        margin-bottom: 3rem;\r\n        background-color: #fff;\r\n    }\r\n\r\n    &__legend {\r\n        @include m.headings;\r\n        font-size: 2.4rem;\r\n        color: v.$azul;\r\n        border-bottom: 2px solid v.$azul;\r\n        padding-bottom: 1rem;\r\n        margin-bottom: 2rem;\r\n        text-align: center;\r\n    }\r\n\r\n    &__campo {\r\n        @include m.grid(1, 2rem);\r\n        margin-bottom: 2rem;\r\n\r\n        @include m.tablet {\r\n            display: grid;\r\n            grid-template-columns: auto 1fr;\r\n            column-gap: 2rem;\r\n            align-items: center;\r\n        }\r\n    }\r\n\r\n    &__label {\r\n        font-size: 1.6rem;\r\n        font-weight: v.$bold;\r\n        color: v.$gris-oscuro;\r\n    }\r\n\r\n    &__input {\r\n        padding: 1.2rem;\r\n        font-size: 1.6rem;\r\n        border-radius: 0.8rem;\r\n        border: 1px solid v.$gris;\r\n        transition: border-color 0.3s, box-shadow 0.3s;\r\n\r\n        &:focus {\r\n            border-color: v.$azul;\r\n            box-shadow: 0 0 0 3px rgba(0, 119, 182, 0.2);\r\n            outline: none;\r\n        }\r\n\r\n        &.error {\r\n            border-color: red;\r\n        }\r\n    }\r\n}\r\n\r\n\r\n.nuevaconexion__contenedor-botones {\r\n    @include m.grid(1, 2rem);\r\n\r\n    @include m.tablet {\r\n        @include m.grid(2, 2rem);\r\n    }\r\n\r\n}\r\n\r\n.nuevaconexion__modal {\r\n    display: none;\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background-color: rgba(0, 0, 0, 0.5);\r\n    justify-content: center;\r\n    align-items: center;\r\n    z-index: 1000;\r\n    padding: 2rem;\r\n\r\n    &--contenido {\r\n        background-color: v.$blanco;\r\n        padding: 3rem 2rem;\r\n        width: 100%;\r\n        max-width: 60rem;\r\n        border-radius: 1.5rem;\r\n        box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);\r\n        text-align: center;\r\n        animation: fadeIn 0.3s ease-in-out;\r\n\r\n        h2 {\r\n            font-size: 2.6rem;\r\n            color: v.$negro;\r\n            margin-bottom: 2rem;\r\n\r\n            @include m.tablet {\r\n                font-size: 3rem;\r\n            }\r\n        }\r\n\r\n        p {\r\n            font-size: 1.6rem;\r\n            color: v.$gris-oscuro;\r\n            margin-bottom: 2rem;\r\n            line-height: 1.6;\r\n\r\n            @include m.tablet {\r\n                font-size: 1.8rem;\r\n            }\r\n        }\r\n\r\n        .requisitos__boton {\r\n            @include m.boton(v.$azul, v.$blanco);\r\n            padding: 1.2rem 3rem;\r\n            font-size: 1.6rem;\r\n            border-radius: 1rem;\r\n            transition: background-color 0.3s ease-in-out;\r\n\r\n            &:hover {\r\n                background-color: v.$celeste;\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n// Animación para la aparición del modal\r\n@keyframes fadeIn {\r\n    from {\r\n        opacity: 0;\r\n        transform: scale(0.9);\r\n    }\r\n\r\n    to {\r\n        opacity: 1;\r\n        transform: scale(1);\r\n    }\r\n}\r\n\r\n.formulario_nueva_conexion__fieldset {\r\n    @include m.grid(2, 1rem);\r\n\r\n    @include m.desktop {\r\n        @include m.grid(3, 1rem);\r\n    }\r\n}\r\n\r\n.estadoconexion {\r\n    &__contenedor {\r\n        flex: 1;\r\n        @include m.contenedor-sm;\r\n        padding-left: 2rem;\r\n        padding-right: 2rem;\r\n        margin-bottom: 4rem;\r\n\r\n        @include m.tablet {\r\n            padding-left: 5rem;\r\n            padding-right: 5rem;\r\n        }\r\n\r\n        @include m.desktop {\r\n            padding-left: 10rem;\r\n            padding-right: 10rem;\r\n        }\r\n\r\n        &--ticket {\r\n            @include m.contenedor;\r\n            margin-bottom: 8rem;\r\n\r\n            @include m.tablet {\r\n                margin-bottom: 10rem;\r\n            }\r\n        }\r\n    }\r\n\r\n    &__formulario {\r\n        @include m.contenedor-sm;\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 2rem;\r\n        margin-bottom: 4rem;\r\n\r\n        @include m.tablet {\r\n            flex-direction: row;\r\n            align-items: center;\r\n            justify-content: flex-start;\r\n            gap: 2rem;\r\n            margin-bottom: 5rem;\r\n        }\r\n    }\r\n\r\n    &__contenedor-boton {\r\n        padding-top: 2rem;\r\n\r\n        @include m.tablet {\r\n            padding-top: 0;\r\n        }\r\n    }\r\n\r\n    &__boton-buscador {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        font-size: 1.4rem;\r\n        text-transform: uppercase;\r\n        width: 100%;\r\n        margin: 0;\r\n\r\n        @include m.tablet {\r\n            width: auto;\r\n            margin-left: 1rem;\r\n        }\r\n    }\r\n}\r\n\r\n.modalnuevaconexion {\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: rgba(0, 0, 0, 0.5);\r\n    display: none;\r\n    justify-content: center;\r\n    align-items: center;\r\n}\r\n\r\n.modalnuevaconexion-contenido {\r\n    background: white;\r\n    padding: 20px;\r\n    border-radius: 5px;\r\n    text-align: center;\r\n    display: flex;\r\n    flex-direction: column;\r\n\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.recibo {\r\n    &__contenedor {\r\n        padding-bottom: 15rem;\r\n        @include m.contenedor-l;\r\n\r\n        &--user {\r\n            padding-bottom: 0rem;\r\n        }\r\n    }\r\n\r\n    &__heading {\r\n        font-size: 3rem;\r\n        text-align: center;\r\n        color: v.$primario;\r\n        margin-bottom: 3rem;\r\n        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.2);\r\n    }\r\n\r\n    &__contenido {\r\n        padding: 3rem;\r\n        border-radius: 2rem;\r\n        background: linear-gradient(to right, #ffffff, #f0f4ff);\r\n        border: 2px solid v.$secundario;\r\n        @include m.shadow-lg;\r\n        display: grid;\r\n        grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\r\n        gap: 3rem;\r\n    }\r\n\r\n    &__datos,\r\n    &__contribuyente,\r\n    &__consumo {\r\n        background-color: #fff;\r\n        padding: 2rem;\r\n        border-radius: 1.5rem;\r\n        border-left: 8px solid v.$primario;\r\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\r\n\r\n        &:hover {\r\n            transform: translateY(-5px);\r\n            box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.15);\r\n        }\r\n    }\r\n\r\n    &__subtitulo {\r\n        font-size: 2rem;\r\n        color: v.$secundario;\r\n        margin-bottom: 1.5rem;\r\n        border-bottom: 2px solid v.$secundario;\r\n        padding-bottom: 0.5rem;\r\n    }\r\n\r\n    &__dato {\r\n        font-size: 1.6rem;\r\n        margin-bottom: 1rem;\r\n        color: #333;\r\n        line-height: 1.6;\r\n        padding-left: 0.5rem;\r\n        position: relative;\r\n\r\n        &::before {\r\n            content: \"•\";\r\n            color: v.$primario;\r\n            position: absolute;\r\n            left: 0;\r\n        }\r\n    }\r\n\r\n    &__label {\r\n        font-weight: bold;\r\n        color: v.$negro;\r\n    }\r\n\r\n    &__mensaje {\r\n        background-color: v.$secundario;\r\n        color: v.$blanco;\r\n        padding: 2rem;\r\n        margin: 2rem 0;\r\n        border-left: 1rem solid v.$primario;\r\n        border-radius: 1rem;\r\n        font-size: 2.4rem;\r\n        font-weight: bold;\r\n        text-align: center;\r\n        text-transform: uppercase;\r\n        @include m.shadow;\r\n\r\n        animation: mensajeAnimado 0.8s ease-in-out both;\r\n\r\n\r\n    }\r\n}\r\n\r\n@keyframes mensajeAnimado {\r\n    0% {\r\n        transform: scale(0.8);\r\n        opacity: 0;\r\n    }\r\n\r\n    100% {\r\n        transform: scale(1);\r\n        opacity: 1;\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.ayuda {\r\n    flex: 1;\r\n    background: linear-gradient(to right top, lighten(v.$azul, 20%), v.$blanco);\r\n    &__contenedor {\r\n        @include m.contenedor;\r\n        padding: 1rem 0 10rem 0;\r\n    }\r\n\r\n    &__titulo {\r\n        @include m.nombre-pagina;\r\n        @include m.texto-degradado(v.$azul, v.$azul-oscuro);\r\n        font-size: clamp(2.5rem, 5vw, 4rem);\r\n        letter-spacing: 0.1rem;\r\n    }\r\n\r\n    &__descripcion {\r\n        @include m.descripcion-pagina;\r\n        @include m.texto-fluido(1.6rem, 2.2rem);\r\n        color: darken(v.$gris-oscuro, 10%);\r\n    }\r\n\r\n    &__grid {\r\n        @include m.grid(2, 5rem);\r\n        margin-top: 5rem;\r\n\r\n        @include m.tablet {\r\n            grid-template-columns: 1fr;\r\n        }\r\n    }\r\n\r\n    &__item {\r\n        background: v.$blanco;\r\n        border-radius: 2.5rem;\r\n        padding: 4rem 3rem;\r\n        position: relative;\r\n        overflow: hidden;\r\n        @include m.shadow-lg;\r\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\r\n\r\n        &:hover {\r\n            transform: translateY(-1rem);\r\n            box-shadow: 0 25px 45px rgba(0, 119, 182, 0.3);\r\n        }\r\n\r\n        &::before {\r\n            content: '';\r\n            // position: absolute;\r\n            top: -50%;\r\n            left: -50%;\r\n            width: 200%;\r\n            height: 200%;\r\n            background: radial-gradient(circle at center, rgba(0, 119, 182, 0.05), transparent 70%);\r\n            transform: rotate(25deg);\r\n        }\r\n\r\n        &-titulo {\r\n            font-size: 2.4rem;\r\n            font-weight: v.$black;\r\n            color: v.$azul;\r\n            text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.05);\r\n            margin-bottom: 1.5rem;\r\n        }\r\n\r\n        &-descripcion {\r\n            font-size: 1.7rem;\r\n            line-height: 1.8;\r\n            color: v.$gris-oscuro;\r\n            margin-bottom: 2.5rem;\r\n        }\r\n\r\n        &-boton {\r\n            @include m.boton(v.$azul, v.$blanco);\r\n            border-radius: 1.2rem;\r\n            font-size: 1.6rem;\r\n            width: auto;\r\n            padding: 1rem 3rem;\r\n            text-transform: uppercase;\r\n            letter-spacing: 0.05rem;\r\n            box-shadow: 0 8px 15px rgba(0, 119, 182, 0.2);\r\n\r\n            &:hover {\r\n                transform: scale(1.05);\r\n            }\r\n        }\r\n    }\r\n\r\n    &__visor-pdf {\r\n        margin-top: 2rem;\r\n        margin-bottom: 3rem;\r\n        border-radius: 1.5rem;\r\n        overflow: hidden;\r\n        border: 2px solid lighten(v.$gris, 15%);\r\n        box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);\r\n        iframe {\r\n            width: 100%;\r\n            height: 80rem;\r\n            border: none;\r\n            background-color: v.$gris-claro;\r\n        }\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.formulario {\r\n\r\n    display: flex;\r\n    flex-direction: column;\r\n\r\n    &__fieldset {\r\n        border: none;\r\n        margin-top: 1rem;\r\n        padding: 0;\r\n    }\r\n\r\n    &__legend {\r\n        color: v.$gris;\r\n        font-size: 2.2rem;\r\n        margin-bottom: 2rem;\r\n    }\r\n\r\n    &__campo {\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 1rem;\r\n        margin: 1.5rem 0;\r\n    }\r\n\r\n    &__contenedor-icono {\r\n        display: flex;\r\n        border-radius: .5rem;\r\n        overflow: hidden;\r\n    }\r\n\r\n    &__icono {\r\n        background-color: v.$gris-oscuro;\r\n        width: 4rem;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n\r\n        i {\r\n            color: v.$blanco;\r\n            font-size: 2rem;\r\n        }\r\n    }\r\n\r\n    &__label {\r\n        display: block;\r\n        font-size: 1.8rem;\r\n        color: rgba(v.$negro, .8);\r\n    }\r\n\r\n    &__input,\r\n    &__select {\r\n        padding: 1rem;\r\n        border: 1px solid darken(v.$gris-claro, 20);\r\n        border-radius: .5rem;\r\n\r\n        &--file {\r\n            border: none;\r\n        }\r\n\r\n        &--sociales {\r\n            @extend .formulario__input;\r\n            flex: 1;\r\n            border-top-left-radius: 0;\r\n            border-bottom-left-radius: 0;\r\n        }\r\n    }\r\n\r\n    &__radio {\r\n        display: flex;\r\n        gap: 2rem;\r\n    }\r\n\r\n    &__texto {\r\n        margin-top: 3rem;\r\n    }\r\n\r\n    &__imagen {\r\n        max-width: 20rem;\r\n    }\r\n\r\n    &__listado {\r\n        @include m.tags;\r\n    }\r\n\r\n    &__submit {\r\n        @include m.boton(v.$azul, v.$blanco);\r\n        width: auto;\r\n        align-self: flex-start;\r\n\r\n        &--registrar,\r\n        &--full {\r\n            width: 100%;\r\n        }\r\n\r\n        &--registrarU {\r\n            width: 100%;\r\n            @include m.boton(v.$celeste, v.$blanco);\r\n\r\n        }\r\n    }\r\n}\r\n\r\n","@use 'base/variables' as v;\r\n\r\n.acciones {\r\n    margin-top: 3rem;\r\n    display: flex;\r\n    justify-content: space-between;\r\n\r\n    &--centrar {\r\n        @extend .acciones;\r\n        justify-content: center;\r\n    }\r\n\r\n    &__enlace {\r\n        color: v.$negro;\r\n        font-size: 1.4rem;\r\n        font-weight: v.$delgada;\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.horas {\r\n    @include m.reset-lista;\r\n    @include m.grid(1, 1rem);\r\n    @include m.tablet {\r\n        @include m.grid(2, 1rem);\r\n    }\r\n\r\n    &__hora {\r\n        color: v.$azul;\r\n        border: 1px solid v.$azul;\r\n        border-radius: 1rem;\r\n        padding: 1rem;\r\n        text-align: center;\r\n\r\n        &:hover { \r\n            cursor: pointer;\r\n        }\r\n\r\n        &--seleccionada {\r\n            @extend .horas__hora;\r\n            background-color: v.$azul;\r\n            color: v.$blanco;\r\n        }\r\n\r\n        &--deshabilitada {\r\n            @extend .horas__hora;\r\n            border: 1px solid v.$gris;\r\n            color: v.$gris;\r\n            opacity: .5;\r\n\r\n            &:hover {\r\n                cursor: not-allowed;\r\n            }\r\n        }\r\n    }\r\n}","/* 🔹 Miniaturas en el formulario */\r\n.formulario__imagenes img {\r\n    width: 100px; /* 🔥 Tamaño pequeño */\r\n    height: auto;\r\n    cursor: pointer;\r\n    transition: transform 0.3s ease-in-out;\r\n    border-radius: 5px;\r\n}\r\n\r\n.formulario__imagenes img:hover {\r\n    transform: scale(1.1);\r\n}\r\n\r\n/* 🔹 Modal (Imágenes en tamaño original) */\r\n.modal {\r\n    display: none;\r\n    position: fixed;\r\n    z-index: 1000;\r\n    left: 0;\r\n    top: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background-color: rgba(0, 0, 0, 0.8);\r\n    align-items: center;\r\n    justify-content: center;\r\n    flex-direction: column;\r\n}\r\n\r\n/* 🔹 Imagen dentro del modal sin reducirse */\r\n.modal img {\r\n    max-width: 90%;\r\n    max-height: 90vh;\r\n    object-fit: contain;\r\n}\r\n\r\n/* 🔹 Botón de cierre */\r\n.close {\r\n    position: absolute;\r\n    top: 15px;\r\n    right: 20px;\r\n    color: white;\r\n    font-size: 40px;\r\n    cursor: pointer;\r\n}\r\n\r\n/* 🔹 Botón de descarga visible */\r\n.descargar-btn {\r\n    margin-top: 20px;\r\n    background: #ffcc00;\r\n    color: #333;\r\n    font-size: 18px;\r\n    font-weight: bold;\r\n    padding: 10px 20px;\r\n    border-radius: 10px;\r\n    text-decoration: none;\r\n    transition: 0.3s;\r\n    box-shadow: 0px 0px 10px rgba(255, 204, 0, 0.8);\r\n}\r\n\r\n.descargar-btn:hover {\r\n    background: #ffaa00;\r\n    box-shadow: 0px 0px 20px rgba(255, 204, 0, 1);\r\n}\r\n","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.barra {\n    background-color: v.$azul;\n    &__contenido {\n        @include m.contenedor;\n        display: flex;\n        flex-direction: column;\n\n        @include m.desktop {\n            flex-direction: row;\n            align-items: center;\n            justify-content: space-between;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(1rem, 3rem);\n    }\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.navegacion {\n    display: flex;\n    flex-direction: column;\n\n    @include m.desktop {\n        flex-direction: row;\n    }\n\n    &__enlace {\n        color: v.$blanco;\n        font-size: 1.8rem;\n        padding: 2rem;\n        font-weight: v.$black;\n        text-transform: uppercase;\n        text-align: center;\n\n        &--actual,\n        &:hover {\n            background-color: v.$blanco;\n            color: v.$azul;\n        }\n    }\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n// ============================================\r\n// VARIABLES LOCALES DEL HEADER\r\n// ============================================\r\n.header {\r\n    --header-azul-profundo: #0a1628;\r\n    --header-azul-medio: #1e3a5f;\r\n    --header-cian: #00d4ff;\r\n    --header-cian-suave: #7dd3fc;\r\n    --header-blanco: #ffffff;\r\n    --header-gris-claro: #f0f9ff;\r\n    --header-sombra: 0 25px 50px -12px rgba(0, 0, 0, 0.25);\r\n    --header-radio: 1.6rem;\r\n    --header-transicion: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\r\n}\r\n\r\n// ============================================\r\n// HEADER PRINCIPAL\r\n// ============================================\r\n.header {\r\n    position: relative;\r\n    min-height: 85vh;\r\n    min-height: 85dvh;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    overflow: hidden;\r\n    background: linear-gradient(135deg, v.$azul-oscuro 0%, v.$azul 50%, #0f2847 100%);\r\n \r\n    // Patrón de puntos sutiles\r\n    &::before {\r\n        content: '';\r\n        position: absolute;\r\n        inset: 0;\r\n        background-image: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.03) 1px, transparent 0);\r\n        background-size: 40px 40px;\r\n        pointer-events: none;\r\n    }\r\n\r\n    // ============================================\r\n    // PARTÍCULAS DE AGUA ANIMADAS\r\n    // ============================================\r\n    &__particulas {\r\n        position: absolute;\r\n        inset: 0;\r\n        overflow: hidden;\r\n        pointer-events: none;\r\n        z-index: 0;\r\n\r\n        span {\r\n            position: absolute;\r\n            display: block;\r\n            width: 40px;\r\n            height: 40px;\r\n            background: v.$blanco;\r\n            border-radius: 50%;\r\n            animation: flotar 15s infinite ease-in-out;\r\n\r\n        &:nth-child(1)  { left: 10%;  top: 20%; width: 12px;  height: 12px;  } // ← Aumenta\r\n        &:nth-child(2)  { left: 20%;  top: 80%; width: 20px;  height: 20px;  } // ← Aumenta\r\n        &:nth-child(3)  { left: 35%;  top: 40%; width: 8px;   height: 8px;   } // ← Aumenta\r\n        &:nth-child(4)  { left: 50%;  top: 10%; width: 24px;  height: 24px;  } // ← Aumenta\r\n        &:nth-child(5)  { left: 65%;  top: 70%; width: 16px;  height: 16px;  } // ← Aumenta\r\n        &:nth-child(6)  { left: 80%;  top: 30%; width: 10px;  height: 10px;  } // ← Aumenta\r\n        &:nth-child(7)  { left: 90%;  top: 60%; width: 18px;  height: 18px;  } // ← Aumenta\r\n        &:nth-child(8)  { left: 15%;  top: 50%; width: 14px;  height: 14px;  } // ← Aumenta\r\n        &:nth-child(9)  { left: 45%;  top: 85%; width: 22px;  height: 22px;  } // ← Aumenta\r\n        &:nth-child(10) { left: 75%;  top: 15%; width: 12px;  height: 12px;  } // ← Aumenta\r\n        &:nth-child(11) { left: 30%;  top: 65%; width: 16px;  height: 16px;  } // ← Aumenta\r\n        &:nth-child(12) { left: 55%;  top: 45%; width: 20px;  height: 20px;  } // ← Aumenta\r\n        }\r\n    }\r\n\r\n    // ============================================\r\n    // ONDA DECORATIVA INFERIOR\r\n    // ============================================\r\n    &__onda {\r\n        position: absolute;\r\n        bottom: 0;\r\n        left: 0;\r\n        width: 100%;\r\n        height: 120px;\r\n        z-index: 2;\r\n        pointer-events: none;\r\n\r\n        svg {\r\n            width: 100%;\r\n            height: 100%;\r\n            display: block;\r\n        }\r\n\r\n        &-path {\r\n            fill: var(--header-gris-claro);\r\n            animation: onda-mover 3s ease-in-out infinite alternate;\r\n        }\r\n    }\r\n\r\n    // ============================================\r\n    // CONTENEDOR\r\n    // ============================================\r\n    &__contenedor {\r\n        @include m.contenedor;\r\n        position: relative;\r\n        z-index: 1;\r\n        width: 100%;\r\n        padding: 2rem;\r\n    }\r\n\r\n    // ============================================\r\n    // BARRA DE UTILIDAD (AUTH)\r\n    // ============================================\r\n    &__utilidad {\r\n        position: absolute;\r\n        top: 2rem;\r\n        right: 2rem;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 1.2rem;\r\n        z-index: 10;\r\n\r\n        @include m.tablet {\r\n            top: 3rem;\r\n            right: 0;\r\n            gap: 1.5rem;\r\n        }\r\n    }\r\n\r\n    &__enlace {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 0.6rem;\r\n        padding: 0.8rem 1.8rem;\r\n        color: rgba(255, 255, 255, 0.85);\r\n        text-decoration: none;\r\n        font-size: 1.4rem;\r\n        font-weight: 500;\r\n        border-radius: 100px;\r\n        background: rgba(255, 255, 255, 0.08);\r\n        border: 1px solid rgba(255, 255, 255, 0.1);\r\n        backdrop-filter: blur(10px);\r\n        transition: var(--header-transicion);\r\n        cursor: pointer;\r\n\r\n        &:hover,\r\n        &:focus-visible {\r\n            background: rgba(255, 255, 255, 0.15);\r\n            color: var(--header-blanco);\r\n            transform: translateY(-2px);\r\n            box-shadow: 0 8px 25px rgba(0, 0, 0, 0.2);\r\n        }\r\n\r\n        &:focus-visible {\r\n            outline: 2px solid var(--header-cian);\r\n            outline-offset: 3px;\r\n        }\r\n\r\n        &--primario {\r\n            background: var(--header-cian);\r\n            color: var(--header-azul-profundo);\r\n            border-color: var(--header-cian);\r\n            font-weight: 600;\r\n\r\n            &:hover {\r\n                background: var(--header-cian-suave);\r\n                box-shadow: 0 8px 25px rgba(0, 212, 255, 0.3);\r\n            }\r\n        }\r\n\r\n        &--admin {\r\n            background: rgba(0, 212, 255, 0.15);\r\n            border-color: rgba(0, 212, 255, 0.3);\r\n            color: var(--header-cian);\r\n\r\n            &:hover {\r\n                background: rgba(0, 212, 255, 0.25);\r\n            }\r\n        }\r\n    }\r\n\r\n    &__icono {\r\n        width: 1.6rem;\r\n        height: 1.6rem;\r\n        flex-shrink: 0;\r\n    }\r\n\r\n    &__form {\r\n        display: inline-flex;\r\n        margin: 0;\r\n    }\r\n\r\n    &__submit {\r\n        @extend .header__enlace;\r\n        font-family: inherit;\r\n        font-size: inherit;\r\n    }\r\n\r\n    // ============================================\r\n    // HERO CONTENT\r\n    // ============================================\r\n    &__hero {\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        text-align: center;\r\n        padding: 12rem 0 8rem;\r\n        max-width: 90rem;\r\n        margin: 0 auto;\r\n\r\n        @include m.tablet {\r\n            padding: 10rem 0 6rem;\r\n        }\r\n    }\r\n\r\n    // Badge superior\r\n    &__badge {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 0.8rem;\r\n        padding: 0.8rem 2rem;\r\n        background: v.$azul-oscuro;\r\n        border: 1px solid rgba(0, 212, 255, 0.2);\r\n        border-radius: 100px;\r\n        color: var(--header-cian-suave);\r\n        font-size: 1.3rem;\r\n        font-weight: 500;\r\n        letter-spacing: 0.05em;\r\n        text-transform: uppercase;\r\n        margin-bottom: 3rem;\r\n        backdrop-filter: blur(10px);\r\n        animation: badge-pulso 3s ease-in-out infinite;\r\n\r\n        &-punto {\r\n            width: 8px;\r\n            height: 8px;\r\n            background: var(--header-cian);\r\n            border-radius: 50%;\r\n            box-shadow: 0 0 10px var(--header-cian);\r\n            animation: punto-brillar 2s ease-in-out infinite;\r\n        }\r\n    }\r\n\r\n    // Logo principal\r\n    &__marca {\r\n        text-decoration: none;\r\n        margin-bottom: 2rem;\r\n        transition: transform 0.3s ease;\r\n\r\n        &:hover {\r\n            transform: scale(1.02);\r\n        }\r\n\r\n        &:focus-visible {\r\n            outline: 3px solid var(--header-cian);\r\n            outline-offset: 8px;\r\n            border-radius: 1rem;\r\n        }\r\n    }\r\n\r\n    &__logo {\r\n        font-family: 'JetBrains Mono', 'Fira Code', monospace;\r\n        font-size: clamp(3.5rem, 8vw, 7rem);\r\n        font-weight: 700;\r\n        margin: 0;\r\n        line-height: 1;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 0.3rem;\r\n        letter-spacing: -0.02em;\r\n\r\n        &-bracket {\r\n            color: var(--header-cian);\r\n            opacity: 0.7;\r\n            font-weight: 300;\r\n        }\r\n\r\n        &-texto {\r\n            background: linear-gradient(135deg, var(--header-blanco) 0%, var(--header-cian-suave) 50%, var(--header-cian) 100%);\r\n            -webkit-background-clip: text;\r\n            -webkit-text-fill-color: transparent;\r\n            background-clip: text;\r\n            filter: drop-shadow(0 0 30px rgba(0, 212, 255, 0.3));\r\n        }\r\n    }\r\n\r\n    // Eslogan\r\n    &__eslogan {\r\n        font-size: clamp(1.8rem, 3.5vw, 2.8rem);\r\n        font-weight: 400;\r\n        color: rgba(255, 255, 255, 0.8);\r\n        margin: 0 0 3rem;\r\n        line-height: 1.5;\r\n        max-width: 70ch;\r\n        text-wrap: balance;\r\n\r\n        &--acento {\r\n            color: var(--header-cian);\r\n            font-weight: 600;\r\n            position: relative;\r\n\r\n            &::after {\r\n                content: '';\r\n                position: absolute;\r\n                bottom: -2px;\r\n                left: 0;\r\n                width: 100%;\r\n                height: 2px;\r\n                background: var(--header-cian);\r\n                opacity: 0.5;\r\n                border-radius: 2px;\r\n            }\r\n        }\r\n    }\r\n\r\n    // Botones de acción\r\n    &__acciones {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        gap: 1.5rem;\r\n        justify-content: center;\r\n        margin-bottom: 5rem;\r\n    }\r\n\r\n    &__boton {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 1rem;\r\n        padding: 1.4rem 3rem;\r\n        font-size: 1.6rem;\r\n        font-weight: 600;\r\n        text-decoration: none;\r\n        border-radius: var(--header-radio);\r\n        transition: var(--header-transicion);\r\n        position: relative;\r\n        overflow: hidden;\r\n\r\n        &::before {\r\n            content: '';\r\n            position: absolute;\r\n            inset: 0;\r\n            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\r\n            transform: translateX(-100%);\r\n            transition: transform 0.6s ease;\r\n        }\r\n\r\n        &:hover::before {\r\n            transform: translateX(100%);\r\n        }\r\n\r\n        &--primario {\r\n            background: linear-gradient(135deg, var(--header-cian) 0%, #0099cc 100%);\r\n            color: var(--header-azul-profundo);\r\n            box-shadow: 0 10px 40px rgba(0, 212, 255, 0.3);\r\n\r\n            &:hover {\r\n                transform: translateY(-3px);\r\n                box-shadow: 0 15px 50px rgba(0, 212, 255, 0.4);\r\n            }\r\n\r\n            &:focus-visible {\r\n                outline: 3px solid var(--header-cian);\r\n                outline-offset: 4px;\r\n            }\r\n        }\r\n\r\n        &--secundario {\r\n            background: transparent;\r\n            color: var(--header-blanco);\r\n            border: 2px solid rgba(255, 255, 255, 0.2);\r\n\r\n            &:hover {\r\n                background: rgba(255, 255, 255, 0.1);\r\n                border-color: rgba(255, 255, 255, 0.4);\r\n                transform: translateY(-3px);\r\n            }\r\n\r\n            &:focus-visible {\r\n                outline: 3px solid var(--header-blanco);\r\n                outline-offset: 4px;\r\n            }\r\n        }\r\n\r\n        &-flecha {\r\n            width: 1.8rem;\r\n            height: 1.8rem;\r\n            transition: transform 0.3s ease;\r\n        }\r\n\r\n        &:hover &-flecha {\r\n            transform: translateX(4px);\r\n        }\r\n    }\r\n\r\n    // ============================================\r\n    // STATS ANIMADAS\r\n    // ============================================\r\n    &__stats {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 3rem;\r\n        flex-wrap: wrap;\r\n        padding: 2rem 4rem;\r\n        background: v.$azul-oscuro;\r\n        border: 1px solid rgba(255, 255, 255, 0.1);\r\n        border-radius: 2rem;\r\n        backdrop-filter: blur(20px);\r\n\r\n        @include m.tablet {\r\n            gap: 5rem;\r\n        }\r\n    }\r\n\r\n    &__stat {\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        gap: 0.5rem;\r\n\r\n        &-numero {\r\n            font-size: clamp(2.5rem, 5vw, 4rem);\r\n            font-weight: 700;\r\n            color: var(--header-cian);\r\n            font-family: 'JetBrains Mono', monospace;\r\n            line-height: 1;\r\n            text-shadow: 0 0 20px rgba(0, 212, 255, 0.3);\r\n        }\r\n\r\n        &-etiqueta {\r\n            font-size: 1.2rem;\r\n            color: rgba(255, 255, 255, 0.6);\r\n            text-transform: uppercase;\r\n            letter-spacing: 0.1em;\r\n            font-weight: 500;\r\n        }\r\n    }\r\n\r\n    &__stat-divisor {\r\n        width: 1px;\r\n        height: 4rem;\r\n        background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.2), transparent);\r\n\r\n        @include m.telefono {\r\n            display: none;\r\n        }\r\n    }\r\n}\r\n\r\n// ============================================\r\n// BARRA DE NAVEGACIÓN (GLASSMORPHISM STICKY)\r\n// ============================================\r\n.barra {\r\n    position: sticky;\r\n    top: 0;\r\n    z-index: 1000;\r\n    background: v.$azul;\r\n    backdrop-filter: blur(20px) saturate(180%);\r\n    -webkit-backdrop-filter: blur(20px) saturate(180%);\r\n    border-bottom: 1px solid rgba(0, 0, 0, 0.05);\r\n    box-shadow: 0 4px 30px rgba(0, 0, 0, 0.05);\r\n    transition: var(--header-transicion);\r\n\r\n    // Efecto de scroll\r\n    &.scrolled {\r\n        background: rgba(255, 255, 255, 0.95);\r\n        box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);\r\n    }\r\n\r\n    &__contenido {\r\n        @include m.contenedor;\r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n        padding: 1.2rem 2rem;\r\n        gap: 2rem;\r\n    }\r\n\r\n    &__marca {\r\n        text-decoration: none;\r\n        flex-shrink: 0;\r\n        transition: transform 0.3s ease;\r\n\r\n        &:hover {\r\n            transform: scale(1.05);\r\n        }\r\n\r\n        &:focus-visible {\r\n            outline: 2px solid var(--header-cian);\r\n            outline-offset: 4px;\r\n            border-radius: 0.6rem;\r\n        }\r\n    }\r\n\r\n    &__logo {\r\n        font-family: 'JetBrains Mono', 'Fira Code', monospace;\r\n        font-size: 2.2rem;\r\n        font-weight: 700;\r\n        color: v.$blanco;\r\n        margin: 0;\r\n        letter-spacing: -0.02em;\r\n\r\n        &-bracket {\r\n            color: var(--header-cian);\r\n            font-weight: 300;\r\n        }\r\n    }\r\n}\r\n\r\n// ============================================\r\n// NAVEGACIÓN PRINCIPAL\r\n// ============================================\r\n.navegacion {\r\n    display: none;\r\n    \r\n    @include m.tablet {\r\n        display: flex;\r\n        gap: 0.4rem;\r\n        align-items: center;\r\n    }\r\n\r\n    // Menú móvil\r\n    &--abierta {\r\n        display: flex;\r\n        flex-direction: column;\r\n        position: absolute;\r\n        top: 100%;\r\n        left: 0;\r\n        right: 0;\r\n        background: rgba(255, 255, 255, 0.98);\r\n        backdrop-filter: blur(20px);\r\n        padding: 2rem;\r\n        gap: 0.5rem;\r\n        box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);\r\n        border-top: 1px solid rgba(0, 0, 0, 0.05);\r\n        animation: menu-deslizar 0.3s ease-out;\r\n    }\r\n\r\n    &__enlace {\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        color: v.$blanco;\r\n        text-decoration: none;\r\n        font-weight: 500;\r\n        font-size: 1.4rem;\r\n        padding: 1rem 1.8rem;\r\n        border-radius: 1rem;\r\n        position: relative;\r\n        transition: var(--header-transicion);\r\n        overflow: hidden;\r\n\r\n        &::before {\r\n            content: '';\r\n            position: absolute;\r\n            inset: 0;\r\n            background: linear-gradient(135deg, rgba(0, 212, 255, 0.1) 0%, rgba(0, 212, 255, 0.05) 100%);\r\n            border-radius: inherit;\r\n            opacity: 0;\r\n            transform: scale(0.8);\r\n            transition: all 0.3s ease;\r\n        }\r\n\r\n        &:hover,\r\n        &:focus-visible {\r\n            color: var(--header-azul-profundo);\r\n\r\n            &::before {\r\n                opacity: 1;\r\n                transform: scale(1);\r\n            }\r\n\r\n            .navegacion__indicador {\r\n                width: 60%;\r\n                opacity: 1;\r\n            }\r\n        }\r\n\r\n        &:focus-visible {\r\n            outline: 2px solid var(--header-cian);\r\n            outline-offset: 2px;\r\n        }\r\n\r\n        &--actual {\r\n            color: var(--header-azul-profundo);\r\n            font-weight: 600;\r\n\r\n            &::before {\r\n                opacity: 1;\r\n                transform: scale(1);\r\n            }\r\n\r\n            .navegacion__indicador {\r\n                width: 60%;\r\n                opacity: 1;\r\n                background: var(--header-cian);\r\n            }\r\n        }\r\n    }\r\n\r\n    &__texto {\r\n        position: relative;\r\n        z-index: 1;\r\n    }\r\n\r\n    &__indicador {\r\n        position: absolute;\r\n        bottom: 0.6rem;\r\n        left: 50%;\r\n        transform: translateX(-50%);\r\n        width: 0;\r\n        height: 3px;\r\n        background: var(--header-cian);\r\n        border-radius: 3px;\r\n        opacity: 0;\r\n        transition: all 0.3s ease;\r\n    }\r\n\r\n    // Botón hamburguesa\r\n    &__toggle {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        width: 4.4rem;\r\n        height: 4.4rem;\r\n        background: rgba(0, 212, 255, 0.1);\r\n        border: none;\r\n        border-radius: 1.2rem;\r\n        cursor: pointer;\r\n        padding: 0;\r\n        transition: var(--header-transicion);\r\n\r\n        @include m.tablet {\r\n            display: none;\r\n        }\r\n\r\n        &:hover {\r\n            background: rgba(0, 212, 255, 0.2);\r\n        }\r\n\r\n        &:focus-visible {\r\n            outline: 2px solid var(--header-cian);\r\n            outline-offset: 2px;\r\n        }\r\n\r\n        .navegacion__icono,\r\n        .navegacion__icono::before,\r\n        .navegacion__icono::after {\r\n            display: block;\r\n            width: 2.2rem;\r\n            height: 2px;\r\n            background: var(--header-azul-profundo);\r\n            border-radius: 2px;\r\n            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\r\n        }\r\n\r\n        .navegacion__icono {\r\n            position: relative;\r\n\r\n            &::before,\r\n            &::after {\r\n                content: '';\r\n                position: absolute;\r\n                left: 0;\r\n            }\r\n\r\n            &::before { top: -7px; }\r\n            &::after { top: 7px; }\r\n        }\r\n\r\n        &[aria-expanded=\"true\"] {\r\n            background: rgba(0, 212, 255, 0.2);\r\n\r\n            .navegacion__icono {\r\n                background: transparent;\r\n\r\n                &::before {\r\n                    top: 0;\r\n                    transform: rotate(45deg);\r\n                }\r\n\r\n                &::after {\r\n                    top: 0;\r\n                    transform: rotate(-45deg);\r\n                }\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n// ============================================\r\n// ANIMACIONES KEYFRAMES\r\n// ============================================\r\n@keyframes flotar {\r\n    0%, 100% {\r\n        transform: translateY(0) scale(1);\r\n        opacity: 0.15;\r\n    }\r\n    50% {\r\n        transform: translateY(-100px) scale(1.2);\r\n        opacity: 0.3;\r\n    }\r\n}\r\n\r\n@keyframes onda-mover {\r\n    0% {\r\n        d: path(\"M0,60 C360,120 720,0 1080,60 C1260,90 1380,30 1440,60 L1440,120 L0,120 Z\");\r\n    }\r\n    100% {\r\n        d: path(\"M0,40 C360,80 720,100 1080,40 C1260,10 1380,70 1440,40 L1440,120 L0,120 Z\");\r\n    }\r\n}\r\n\r\n@keyframes badge-pulso {\r\n    0%, 100% {\r\n        box-shadow: 0 0 0 0 rgba(0, 212, 255, 0.2);\r\n    }\r\n    50% {\r\n        box-shadow: 0 0 0 10px rgba(0, 212, 255, 0);\r\n    }\r\n}\r\n\r\n@keyframes punto-brillar {\r\n    0%, 100% {\r\n        opacity: 1;\r\n        transform: scale(1);\r\n    }\r\n    50% {\r\n        opacity: 0.5;\r\n        transform: scale(1.3);\r\n    }\r\n}\r\n\r\n@keyframes menu-deslizar {\r\n    from {\r\n        opacity: 0;\r\n        transform: translateY(-10px);\r\n    }\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n// ============================================\r\n// REDUCED MOTION\r\n// ============================================\r\n@media (prefers-reduced-motion: reduce) {\r\n    .header__particulas span,\r\n    .header__onda-path,\r\n    .header__badge,\r\n    .header__badge-punto {\r\n        animation: none !important;\r\n    }\r\n\r\n    .header__boton::before {\r\n        display: none;\r\n    }\r\n}\r\n\r\n// ============================================\r\n// RESPONSIVE ADICIONAL\r\n// ============================================\r\n@include m.telefono {\r\n    .header {\r\n        min-height: auto;\r\n        padding-bottom: 4rem;\r\n\r\n        &__utilidad {\r\n            position: relative;\r\n            top: auto;\r\n            right: auto;\r\n            justify-content: center;\r\n            margin-bottom: 3rem;\r\n            flex-wrap: wrap;\r\n        }\r\n\r\n        &__hero {\r\n            padding: 4rem 0;\r\n        }\r\n\r\n        &__stats {\r\n            padding: 1.5rem 2rem;\r\n            gap: 1.5rem;\r\n        }\r\n\r\n        &__stat-divisor {\r\n            display: none;\r\n        }\r\n    }\r\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.footer {\n    background-color: v.$azul;\n    // margin-top: 5rem;\n    padding-top: 3rem;\n    color: v.$blanco;\n\n    &__grid {\n        padding-top: 3rem;\n        z-index: 2;\n        @include m.contenedor;\n        @include m.tablet {\n            @include m.grid(2, 3rem);\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 4rem);\n    }\n\n    &__texto {\n        line-height: 2;\n        text-align: center;\n        color: v.$blanco;\n        @include m.tablet {\n            text-align: left;\n        }\n    }\n\n    &__copyright {\n        background-color: darken(v.$azul, 10);\n        margin: 3rem 0 0 0;\n        padding: 2rem 0;\n        text-align: center;\n        font-size: 1.4rem;\n        font-weight: v.$black;\n\n        &--regular {\n            font-weight: v.$regular;\n        }\n    }\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.footer__bubbles {\r\n    z-index: 1;\r\n    background-color: v.$azul;\r\n    display: grid;\r\n    position: relative;\r\n    grid-area: footer;\r\n    min-height: 12rem;\r\n    .bubbles {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        right: 12rem;\r\n        height: 1rem;\r\n        background: v.$azul;\r\n        filter: url(\"#blob\");\r\n\r\n        .bubble {\r\n            position: absolute;\r\n            left: var(--position, 50%);\r\n            background: v.$azul;\r\n            border-radius: 100%;\r\n            animation: bubble-size var(--time, 4s) ease-in infinite var(--delay, 0s),\r\n                bubble-move var(--time, 4s) ease-in infinite var(--delay, 0s);\r\n            transform: translate(-50%, 100%);\r\n        }\r\n    }\r\n}\r\n\r\n\r\n@keyframes bubble-size {\r\n\r\n    0%,\r\n    75% {\r\n        width: var(--size, 4rem);\r\n        height: var(--size, 4rem);\r\n    }\r\n\r\n    100% {\r\n        width: 0rem;\r\n        height: 0rem;\r\n    }\r\n}\r\n\r\n@keyframes bubble-move {\r\n    0% {\r\n        bottom: -4rem;\r\n    }\r\n\r\n    100% {\r\n        bottom: var(--distance, 10rem);\r\n    }\r\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.menu-redes {\n    @include m.menu-social(v.$blanco, 2rem);\n    display: flex;\n    justify-content: center;\n    gap: 2rem;\n    margin: 4rem 0;\n    @include m.tablet {\n        justify-content: flex-end;\n    }\n}","@use 'base/variables' as v;\n\n.alerta {\n\n    padding: 1.5rem 1.5rem 1.5rem 3rem;\n    text-transform: uppercase;\n    margin: 1rem 0;\n    font-size: 1.2rem;\n    font-weight: v.$bold;\n\n    &__error {\n        background-color: lighten(v.$rojo, 60%);\n        border-left: .5rem solid v.$rojo;\n        color: v.$rojo;\n    }\n\n    &__exito {\n        background-color: lighten(v.$verde, 40%);\n        border-left: .5rem solid v.$verde;\n        color: darken(v.$verde, 20);\n    }\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboard {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: v.$gris-oscuro;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__nav {}\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__grid {\n        display: flex;\n        flex: 1;\n        overflow-y: auto;\n    }\n\n    &__sidebar {\n        flex-shrink: 0;\n        background: linear-gradient(180deg, lighten(v.$gris-oscuro, 5) 0%, lighten(v.$gris-oscuro, 15) 100%);\n        width: 14rem;\n        height: 100vh;\n        position: sticky;\n        top: 0;\n        box-shadow: 2px 0 8px rgba(0, 0, 0, 0.15);\n        display: flex;\n        flex-direction: column;\n        justify-content: space-between; // Puedes añadir un footer si deseas\n    }\n\n    &__menu {\n        padding: 2rem 1rem;\n        display: flex;\n        flex-direction: column;\n        gap: 1.5rem;\n    }\n\n    &__enlace {\n        color: lighten(v.$gris-oscuro, 40);\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 1rem 1rem;\n        text-decoration: none;\n        border-radius: 1rem;\n        cursor: pointer;\n        transition: all 300ms ease-in-out;\n\n        &:hover,\n        &--actual {\n            background-color: lighten(v.$gris-oscuro, 20);\n            color: v.$blanco;\n            transform: translateY(-2px);\n            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);\n            border: 1px solid rgba(255, 255, 255, 0.2);\n        }\n    }\n\n    &__icono {\n        font-size: 2.2rem;\n        margin-bottom: 1rem;\n    }\n\n    &__menu-texto {\n        margin-top:0.5rem;\n        font-size: 1rem;\n        text-transform: uppercase;\n        font-weight: v.$bold;\n        letter-spacing: 0.5px;\n        text-align: center;\n    }\n\n\n    &__footer {\n        padding: 1rem;\n        text-align: center;\n        color: lighten(v.$gris-oscuro, 45);\n        font-size: 1.5rem;\n        border-top: 1px solid rgba(255, 255, 255, 0.08);\n        background-color: rgba(255, 255, 255, 0.02);\n    }\n\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton {\n        @include m.boton(v.$azul, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        @include m.shadow;\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n    }\n\n    &__formulario {\n        @extend .dashboard__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__grafica {\n        @include m.contenedor-sm;\n    }\n\n    &__contenedor-buscador {\n        @include m.tablet {\n            display: flex;\n            justify-content: start;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__formulario__buscardor {\n        @include m.tablet {\n            display: flex;\n            justify-content: start;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton__buscardor {\n        @include m.boton(v.$azul, v.$blanco);\n        margin: 3rem;\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor__boton {\n        padding-top: 2.5rem;\n    }\n\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n    color: v.$negro;\r\n    overflow-x: auto;\r\n    display: block;\r\n\r\n    &__thead {\r\n        background-color: v.$gris;\r\n        color: v.$blanco;\r\n        text-transform: uppercase;\r\n        letter-spacing: 0.05em;\r\n        user-select: none;\r\n    }\r\n\r\n    &__th {\r\n        padding: 1rem 1.2rem;\r\n        text-align: left;\r\n        font-weight: bold;\r\n        border-bottom: 3px solid darken(v.$gris, 10%);\r\n        white-space: nowrap; // evitar que el texto se parta\r\n    }\r\n\r\n    &__tr {\r\n        transition: background-color 0.3s ease, box-shadow 0.3s ease;\r\n\r\n        &:nth-child(even) {\r\n            background-color: darken(v.$gris-claro, 20%);\r\n        }\r\n\r\n        &:hover {\r\n            background-color: lighten(v.$azul, 40%);\r\n            box-shadow: inset 4px 0 0 0 v.$azul;\r\n            cursor: pointer;\r\n        }\r\n    }\r\n\r\n    &__td {\r\n        padding: 1.5rem 1rem;\r\n        font-size: 1.8rem;\r\n        vertical-align: middle;\r\n        border-bottom: 1px solid lighten(v.$gris, 40%);\r\n        transition: background-color 0.3s ease;\r\n        white-space: nowrap;\r\n\r\n        &:hover {\r\n            background-color: lighten(v.$azul, 40%);\r\n            box-shadow: inset 4px 0 0 0 v.$azul;\r\n            cursor: pointer;\r\n            background-color: lighten(v.$blanco, 30%);\r\n        }\r\n\r\n        &--acciones {\r\n            @extend .table__td;\r\n            display: flex;\r\n            justify-content: flex-start;\r\n            align-items: center;\r\n            gap: 1.5rem;\r\n            flex-wrap: wrap;\r\n        }\r\n\r\n        button {\r\n            border: none;\r\n            font-size: 1.4rem;\r\n            padding: 0.5rem 1.2rem;\r\n            text-transform: uppercase;\r\n            font-weight: 700;\r\n            border-radius: 0.8rem;\r\n            transition: background-color 0.3s ease, color 0.3s ease, box-shadow 0.3s ease;\r\n            cursor: pointer;\r\n            user-select: none;\r\n\r\n            &:focus-visible {\r\n                outline: 3px solid v.$azul;\r\n                outline-offset: 3px;\r\n            }\r\n        }\r\n    }\r\n\r\n    &__accion {\r\n        all: unset;\r\n        text-transform: uppercase;\r\n        font-size: 1.4rem;\r\n        font-weight: 700;\r\n        padding: 0.4em 0.8em;\r\n        border-radius: 4px;\r\n        transition: background-color 0.3s ease, color 0.3s ease, box-shadow 0.3s ease;\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 0.4em;\r\n        user-select: none;\r\n\r\n        &--editar {\r\n            color: v.$azul;\r\n            background-color: rgba(2, 132, 199, 0.1);\r\n            border: 1.5px solid v.$azul;\r\n\r\n            &:hover,\r\n            &:focus {\r\n                background-color: v.$azul;\r\n                color: #fff;\r\n                box-shadow: 0 4px 8px rgba(2, 132, 199, 0.4);\r\n                outline: none;\r\n            }\r\n        }\r\n\r\n        &--eliminar {\r\n            color: v.$rojo;\r\n            background-color: rgba(220, 38, 38, 0.1);\r\n            border: 1.5px solid v.$rojo;\r\n\r\n            &:hover,\r\n            &:focus {\r\n                background-color: v.$rojo;\r\n                color: #fff;\r\n                box-shadow: 0 4px 8px rgba(220, 38, 38, 0.4);\r\n                outline: none;\r\n            }\r\n        }\r\n\r\n        &--asignar {\r\n            color: v.$negro;\r\n            background-color: rgba(0, 0, 0, 0.05);\r\n            border: 1.5px solid v.$negro;\r\n\r\n            &:hover,\r\n            &:focus {\r\n                background-color: v.$negro;\r\n                color: #fff;\r\n                box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);\r\n                outline: none;\r\n            }\r\n        }\r\n\r\n        @keyframes parpadeo-alerta {\r\n\r\n            0%,\r\n            100% {\r\n                background-color: v.$rojo-alerta;\r\n                ;\r\n                box-shadow: 0 0 5px v.$rojo-alerta;\r\n            }\r\n\r\n            50% {\r\n                background-color: darken(v.$rojo-alerta, 10%);\r\n                box-shadow: 0 0 20px v.$rojo-alerta;\r\n            }\r\n        }\r\n\r\n        @keyframes parpadeo-naranja {\r\n\r\n            0%,\r\n            100% {\r\n                background-color: v.$naranja-alerta;\r\n                box-shadow: 0 0 5px v.$naranja-alerta;\r\n            }\r\n\r\n            50% {\r\n                background-color: darken(v.$naranja-alerta, 10%);\r\n                box-shadow: 0 0 20px v.$naranja-alerta;\r\n            }\r\n        }\r\n\r\n\r\n        &--moroso {\r\n            color: v.$blanco;\r\n            background-color: v.$naranja-alerta;\r\n            border: 2px solid v.$naranja-alerta;\r\n            font-weight: bold;\r\n            animation: parpadeo-naranja 1s infinite;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n\r\n        &--corte {\r\n            color: v.$blanco;\r\n            background-color: v.$rojo-alerta;\r\n            border: 2px solid v.$rojo-alerta;\r\n            font-weight: bold;\r\n            animation: parpadeo-alerta 1s infinite;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n        }\r\n\r\n        &:focus-visible {\r\n            outline: 2px solid v.$azul;\r\n            outline-offset: 2px;\r\n        }\r\n    }\r\n\r\n    &__pendiente {\r\n        background-color: v.$amarillo;\r\n        color: v.$blanco;\r\n        border: none;\r\n        font-size: 1.5rem;\r\n        padding: 0.5rem 1rem;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        border-radius: 1rem;\r\n        transition: background-color 0.3s ease, color 0.3s ease;\r\n        user-select: none;\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n            background-color: darken(v.$amarillo, 10%);\r\n            color: lighten(v.$blanco, 10%);\r\n        }\r\n    }\r\n\r\n    &__completa {\r\n        background-color: v.$verde;\r\n        color: v.$blanco;\r\n        border-radius: 1rem;\r\n        padding: 0.5rem 1rem;\r\n        font-size: 1.5rem;\r\n        font-weight: 700;\r\n        user-select: none;\r\n        transition: background-color 0.3s ease;\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n            background-color: darken(v.$verde, 10%);\r\n        }\r\n    }\r\n\r\n    &__check {\r\n        width: 20px;\r\n        height: 20px;\r\n        accent-color: v.$azul;\r\n        cursor: pointer;\r\n        display: flex;\r\n        margin: 0 auto;\r\n        transform: scale(1.1);\r\n        transition: transform 0.2s ease, box-shadow 0.2s ease;\r\n        user-select: none;\r\n\r\n        &:hover {\r\n            transform: scale(1.3);\r\n            box-shadow: 0 0 6px rgba(2, 132, 199, 0.6);\r\n        }\r\n    }\r\n\r\n    // Responsividad\r\n    @include m.telefono {\r\n        font-size: 1.5rem;\r\n\r\n        &__th,\r\n        &__td {\r\n            padding: 1rem;\r\n        }\r\n\r\n        &__acciones {\r\n            gap: 1rem;\r\n        }\r\n    }\r\n\r\n    @include m.tablet {\r\n        display: table;\r\n        font-size: 1.4rem;\r\n\r\n        &__thead {\r\n            display: table-header-group;\r\n        }\r\n\r\n        &__tr {\r\n            display: table-row;\r\n        }\r\n\r\n        &__th,\r\n        &__td {\r\n            display: table-cell;\r\n            padding: 1rem 1.5rem;\r\n            white-space: normal; // permitir ajuste en tablet para mejor lectura\r\n        }\r\n\r\n        &__td--acciones {\r\n            flex-wrap: nowrap;\r\n            gap: 2rem;\r\n        }\r\n    }\r\n\r\n    @include m.desktop {\r\n\r\n        &__th,\r\n        &__td {\r\n            padding: 1.5rem 2rem;\r\n        }\r\n\r\n        &__td--acciones {\r\n            gap: 2.5rem;\r\n        }\r\n    }\r\n\r\n    &--scroll {\r\n        max-height: calc(7rem * 5 + 1rem); // 42px ≈ alto de una fila; puedes ajustar\r\n        overflow-y: auto;\r\n        border: 1px solid #ddd;\r\n        border-radius: 8px;\r\n\r\n        scrollbar-width: thin;\r\n        scrollbar-color: #ccc transparent;\r\n\r\n        &::-webkit-scrollbar {\r\n            width: 6px;\r\n        }\r\n\r\n        &::-webkit-scrollbar-thumb {\r\n            background-color: #ccc;\r\n            border-radius: 4px;\r\n        }\r\n\r\n        &::-webkit-scrollbar-track {\r\n            background: transparent;\r\n        }\r\n\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.paginacion {\r\n    margin-top: 5rem;\r\n    margin-bottom: 3rem;\r\n    display: flex;\r\n    gap: 1rem;\r\n    flex-wrap: wrap;\r\n    justify-content: center;\r\n    align-items: center;\r\n\r\n    @include m.tablet {\r\n        justify-content: flex-end;\r\n    }\r\n\r\n    &__enlace {\r\n        color: v.$azul;\r\n        font-size: 1.6rem;\r\n\r\n        &--texto {\r\n            padding: 1rem;\r\n            border-radius: .5rem;\r\n            border: 1px solid v.$azul;\r\n\r\n            &:hover {\r\n                background-color: v.$azul;\r\n                color: v.$blanco;\r\n            }\r\n        }\r\n        &--numero {\r\n            font-weight: v.$bold;\r\n            display: none;\r\n            @include m.tablet {\r\n                display: inline;\r\n            }\r\n        }\r\n        &--actual {\r\n            color: v.$gris;\r\n            font-weight: v.$bold;\r\n            display: none;\r\n            @include m.tablet {\r\n                display: inline;\r\n            }\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.listado-ponentes {\r\n    @include m.reset-lista;\r\n    @include m.grid(1, 1rem);\r\n\r\n    &__ponente {\r\n        color: v.$azul;\r\n        border: 1px solid v.$azul;\r\n        padding: 1rem;\r\n        border-radius: 1rem;\r\n        text-align: center;\r\n\r\n        &:hover {\r\n            cursor: pointer;\r\n            background-color: v.$azul;\r\n            color: v.$blanco;\r\n        }\r\n\r\n        &--seleccionado {\r\n            @extend .listado-ponentes__ponente;\r\n            background-color: v.$azul;\r\n            color: v.$blanco;\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.bloques {\r\n    @include m.contenedor;\r\n\r\n    @include m.tablet {\r\n        margin-top: 10rem;\r\n    }\r\n\r\n    &__grid {\r\n        @include m.grid(1, 3rem);\r\n\r\n        @include m.desktop {\r\n            @include m.grid(2, 3rem);\r\n        }\r\n    }\r\n}\r\n\r\n.bloque {\r\n    padding: 4rem;\r\n    color: v.$blanco;\r\n    border-radius: 2rem;\r\n    position: relative;\r\n    overflow: hidden;\r\n    box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.25);\r\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\r\n\r\n    // Efecto hover sutil pero elegante\r\n    &:hover {\r\n        transform: translateY(-1rem);\r\n        box-shadow: 0 2rem 4rem rgba(0, 0, 0, 0.35);\r\n    }\r\n\r\n    &__heading {\r\n        margin: 1rem 0 2.5rem 0;\r\n        font-size: 4rem;\r\n        font-weight: v.$bold;\r\n        text-align: center;\r\n        text-transform: uppercase;\r\n        letter-spacing: 0.05em;\r\n        text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    &__texto {\r\n        margin: 1rem 0;\r\n        font-size: 2rem;\r\n        line-height: 1.6;\r\n        text-align: center;\r\n        font-weight: v.$medium;\r\n\r\n        &--cantidad {\r\n            margin-top: 5rem;\r\n            font-weight: v.$black;\r\n            font-size: 6.5rem;\r\n            text-align: center;\r\n            text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.4);\r\n        }\r\n    }\r\n\r\n    @for $i from 1 through 8 {\r\n        &:nth-child(#{$i}) {\r\n\r\n            @if $i ==1 {\r\n                background-color: hsla(0, 100%, 30%, 1);\r\n                background-image:\r\n                    radial-gradient(at 40% 20%, hsla(28, 100%, 40%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 0%, hsla(189, 100%, 35%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 50%, hsla(355, 100%, 60%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 16% 20%, hsla(340, 100%, 45%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 100%, hsla(22, 100%, 50%, 0.5) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 100%, hsla(242, 100%, 35%, 0.5) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 0%, hsla(343, 100%, 45%, 0.4) 0px, transparent 50%);\r\n            }\r\n\r\n            @else if $i ==2 {\r\n                background-color: hsla(264, 80%, 20%, 1);\r\n                background-image:\r\n                    radial-gradient(at 40% 20%, hsla(274, 74%, 27%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 0%, hsla(267, 82%, 22%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 50%, hsla(272, 73%, 28%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 16% 20%, hsla(340, 39%, 11%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 100%, hsla(254, 52%, 25%, 0.5) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 100%, hsla(242, 100%, 30%, 0.5) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 0%, hsla(264, 80%, 28%, 0.5) 0px, transparent 50%);\r\n            }\r\n\r\n            @else if $i ==3 {\r\n                background-color: hsla(190, 100%, 25%, 1);\r\n                background-image:\r\n                    radial-gradient(at 40% 20%, hsla(137, 100%, 35%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 0%, hsla(72, 100%, 30%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 50%, hsla(121, 39%, 27%, 0.6) 0px, transparent 50%);\r\n            }\r\n\r\n            @else if $i ==4 {\r\n                background-color: hsla(243, 78%, 25%, 1);\r\n                background-image:\r\n                    radial-gradient(at 80% 0%, hsla(189, 100%, 35%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 50%, hsla(355, 43%, 30%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 100%, hsla(22, 100%, 40%, 0.5) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 100%, hsla(242, 100%, 35%, 0.5) 0px, transparent 50%);\r\n            }\r\n\r\n            @else if $i ==5 {\r\n                background-color: hsla(0, 100%, 30%, 1);\r\n                background-image:\r\n                    radial-gradient(at 40% 20%, hsla(28, 100%, 40%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 0%, hsla(189, 100%, 35%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 50%, hsla(355, 100%, 60%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 16% 20%, hsla(340, 100%, 45%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 100%, hsla(22, 100%, 50%, 0.5) 0px, transparent 50%);\r\n            }\r\n\r\n            @else if $i ==6 {\r\n                background-color: hsla(120, 70%, 25%, 1);\r\n                background-image:\r\n                    radial-gradient(at 40% 20%, hsla(140, 80%, 35%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 0%, hsla(100, 60%, 30%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 100%, hsla(160, 70%, 40%, 0.5) 0px, transparent 50%);\r\n            }\r\n\r\n            @else if $i ==7 {\r\n                background-color: hsla(35, 100%, 30%, 1);\r\n                background-image:\r\n                    radial-gradient(at 40% 20%, hsla(45, 100%, 40%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 0%, hsla(20, 90%, 35%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 50%, hsla(10, 100%, 45%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 100%, hsla(55, 100%, 35%, 0.5) 0px, transparent 50%);\r\n            }\r\n\r\n            @else if $i ==8 {\r\n                background-color: hsla(200, 80%, 25%, 1);\r\n                background-image:\r\n                    radial-gradient(at 40% 20%, hsla(210, 90%, 35%, 0.8) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 0%, hsla(190, 100%, 30%, 0.7) 0px, transparent 50%),\r\n                    radial-gradient(at 0% 50%, hsla(220, 70%, 40%, 0.6) 0px, transparent 50%),\r\n                    radial-gradient(at 80% 100%, hsla(180, 100%, 35%, 0.5) 0px, transparent 50%);\r\n            }\r\n        }\r\n    }\r\n}",".noticia__introduccion{\r\n    //recortar texto\r\n    font-size: 1.6rem;\r\n    display: -webkit-box;\r\n    -webkit-line-clamp: 10; //cuantas lineas de texto quieres\r\n    -webkit-box-orient: vertical;\r\n    overflow: hidden;\r\n    font-weight: normal;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n\r\n.eventos-registro {\r\n    @include m.contenedor;\r\n    margin-bottom: 6rem;\r\n    @include m.tablet {\r\n        display: flex;\r\n        align-items: flex-start; //alinear hacia arriba\r\n        gap: 2rem;\r\n    }\r\n    &__listado {\r\n        @include m.tablet {\r\n            flex: 0 0 60%;\r\n        }\r\n    }\r\n    &__grid {\r\n        @include m.grid(1, 3rem);\r\n        @include m.desktop {\r\n            @include m.grid(2, 3rem);\r\n        }\r\n    }\r\n    &__heading {\r\n        &--conferencias,\r\n        &--workshops {\r\n            white-space: nowrap;\r\n            @include m.texto-fluido(2rem, 5rem);\r\n        }\r\n        &--conferencias {\r\n            color: v.$azul;\r\n        }\r\n        &--workshops {\r\n            color: v.$secundario;\r\n            margin-top: 5rem;\r\n        }\r\n    }\r\n    &__fecha {\r\n        margin: 6rem 0 3rem 0;\r\n    }\r\n}\r\n\r\n.registro {//aside\r\n    background-color: v.$gris-claro;\r\n    padding: 3rem;\r\n    border-radius: 1rem;\r\n    @include m.tablet {\r\n        flex: 0 0 40%;\r\n        position: -webkit-sticky;//mantener fija el aside\r\n        position: sticky;\r\n        top: 3rem;\r\n    }\r\n    &__heading {\r\n        margin: 0 0 3rem 0;\r\n    }\r\n    &__evento { //de scripting con js \r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n        padding: 1rem;\r\n        &:nth-child(even) {\r\n            background-color: darken(v.$gris-claro, 3);//intercalar colores en el listado\r\n        }\r\n    }\r\n    &__nombre {\r\n        font-size: 2rem;\r\n        font-weight: v.$bold;\r\n        margin: 0;\r\n    }\r\n    &__eliminar {\r\n        all: unset;\r\n        color: v.$rojo;\r\n        &:hover {\r\n            cursor: pointer;\r\n        }\r\n    }\r\n\r\n    &__texto {\r\n        text-align: center;\r\n    }\r\n\r\n    &__regalo {\r\n        margin-top: 3rem;\r\n    }\r\n\r\n    &__label {\r\n        display: block;\r\n        font-size: 2.2rem;\r\n        font-weight: v.$bold;\r\n        margin-bottom: 1rem;\r\n    }\r\n    &__select {\r\n        width: 100%;\r\n        background-color: v.$blanco;\r\n        border: 1px solid v.$gris;\r\n        padding: 1rem;\r\n        border-radius: .5rem;\r\n    }\r\n}\r\n\r\n","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardUser {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: #4ac4f5;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n        overflow-y: scroll;\n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton {\n        @include m.boton(v.$celeste, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        @include m.shadow;\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n\n        &--solicitud {\n            @extend .dashboardUser__contenedor;\n            @include m.contenedor;\n\n        }\n    }\n\n\n    &__formulario {\n        @extend .dashboardUser__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__mensaje {\n        padding-top: 3rem;\n        text-align: center;\n    }\n\n    //nav\n    &__navegacion {\n        padding-top: 4rem;\n        @include m.contenedor-md;\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            @include m.grid(3, 2rem);\n\n        }\n    }\n\n    &__navegacion-enlace {\n        all: unset;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        background-color: v.$celeste;\n        border-radius: 2rem;\n        padding: 2rem;\n\n        &:hover {\n            cursor: pointer;\n            background-color: darken($color: v.$celeste, $amount: 20%);\n        }\n    }\n\n\n    &__navegacion-icono {\n        color: v.$blanco;\n        font-size: 6rem;\n        padding-bottom: 1rem;\n    }\n\n    &__navegacion-texto {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    &__navegacion-etiqueta {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    //division en crear\n    &__gridCreate {\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            @include m.grid(2, 2rem);\n\n        }\n    }\n\n    &__panel {\n        @include m.contenedor;\n    }\n\n\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.authUser__body {\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    min-height: 90vh;\r\n    background: linear-gradient(90deg, #e2e2e2, #c9d6ff);\r\n}\r\n\r\n.authUser {\r\n\r\n    @include m.desktop {\r\n        position: relative;\r\n        width: 1050px;\r\n        height: 750px;\r\n        background: #fff;\r\n        margin: 20px;\r\n        border-radius: 30px;\r\n        box-shadow: 0 0 30px rgba(0, 0, 0, .2);\r\n        overflow: hidden;\r\n    }\r\n    @include m.telefono{\r\n    }\r\n\r\n\r\n    &__titulo {\r\n        font-size: 36px;\r\n        margin: -10px 0;\r\n    }\r\n\r\n    &__texto {\r\n        font-size: 14.5px;\r\n        margin: 15px 0;\r\n    }\r\n\r\n    &__form {\r\n        position: absolute;\r\n        right: 0;\r\n        width: 50%;\r\n        height: 100%;\r\n        background: #fff;\r\n        display: flex;\r\n        align-items: center;\r\n        color: #333;\r\n        text-align: center;\r\n        padding: 40px;\r\n        z-index: 1;\r\n        transition: .6s ease-in-out 1.2s, visibility 0s 1s;\r\n    }\r\n\r\n    &.active &__form {\r\n        right: 50%;\r\n    }\r\n\r\n    &__form--registrar {\r\n        visibility: hidden;\r\n    }\r\n\r\n    &.active &__form--registrar {\r\n        visibility: visible;\r\n    }\r\n\r\n\r\n    &__input {\r\n        position: relative;\r\n        margin: 30px 0;\r\n\r\n        input {\r\n            width: 100%;\r\n            padding: 13px 50px 13px 20px;\r\n            background: #eee;\r\n            border-radius: 8px;\r\n            border: none;\r\n            outline: none;\r\n            font-size: 16px;\r\n            color: #333;\r\n            font-weight: 500;\r\n\r\n            &::placeholder {\r\n                color: #888;\r\n                font-weight: 400;\r\n            }\r\n        }\r\n\r\n        .authUser__icono {\r\n            position: absolute;\r\n            right: 20px;\r\n            top: 50%;\r\n            transform: translateY(-50%);\r\n            font-size: 20px;\r\n        }\r\n    }\r\n\r\n    &__recuperar {\r\n        margin: -15px 0 15px;\r\n\r\n        &-enlace {\r\n            font-size: 14.5px;\r\n            color: #333;\r\n        }\r\n    }\r\n\r\n    &__boton {\r\n        width: 100%;\r\n        height: 48px;\r\n        background: v.$azul;\r\n        border-radius: 8px;\r\n        box-shadow: 0 0 10px rgba(0, 0, 0, .1);\r\n        border: none;\r\n        cursor: pointer;\r\n        font-size: 16px;\r\n        color: v.$blanco;\r\n        font-weight: 600;\r\n\r\n        &:hover {\r\n            background-color: v.$blanco;\r\n            color: v.$azul;\r\n            cursor: pointer;\r\n            border: 2px solid v.$negro;\r\n            /* Borde blanco y no tan grueso */\r\n        }\r\n\r\n        &--ingresar {\r\n            margin-top: 1rem;\r\n            width: 30%;\r\n        }\r\n\r\n        &--registrar {\r\n            margin-top: 1rem;\r\n            width: 30%;\r\n        }\r\n    }\r\n\r\n    &__alternar {\r\n        position: absolute;\r\n        width: 100%;\r\n        height: 100%;\r\n\r\n        &::before {\r\n            content: '';\r\n            position: absolute;\r\n            left: -250%;\r\n            width: 300%;\r\n            height: 100%;\r\n            background: v.$azul;\r\n            border-radius: 150px;\r\n            z-index: 2;\r\n            transition: 1.8s ease-in-out;\r\n        }\r\n    }\r\n\r\n    &.active &__alternar::before {\r\n        left: 50%;\r\n    }\r\n\r\n    &__alternar-panel {\r\n        position: absolute;\r\n        width: 50%;\r\n        height: 100%;\r\n        color: #fff;\r\n        display: flex;\r\n        flex-direction: column;\r\n        justify-content: center;\r\n        align-items: center;\r\n        z-index: 2;\r\n        transition: .6s ease-in-out;\r\n\r\n        &--izquierda {\r\n            left: 0;\r\n            transition-delay: 1.2s;\r\n        }\r\n\r\n        &--derecha {\r\n            right: -50%;\r\n            transition-delay: .6s;\r\n        }\r\n    }\r\n\r\n    &.active &__alternar-panel--izquierda {\r\n        left: -50%;\r\n        transition-delay: .6s;\r\n    }\r\n\r\n    &.active &__alternar-panel--derecha {\r\n        right: 0;\r\n        transition-delay: 1.2s;\r\n    }\r\n}\r\n\r\n@media screen and (max-width: 650px) {\r\n    .authUser {\r\n        height: calc(100vh - 40px);\r\n\r\n        &__form {\r\n            bottom: 0;\r\n            width: 100%;\r\n            height: 70%;\r\n        }\r\n\r\n        &.active &__form {\r\n            right: 0;\r\n            bottom: 30%;\r\n        }\r\n\r\n        &__alternar::before {\r\n            left: 0;\r\n            top: -270%;\r\n            width: 100%;\r\n            height: 300%;\r\n            border-radius: 20vw;\r\n        }\r\n\r\n        &.active &__alternar::before {\r\n            left: 0;\r\n            top: 70%;\r\n        }\r\n    }\r\n}\r\n\r\n@media screen and (max-width: 400px) {\r\n    .authUser__form {\r\n        padding: 20px;\r\n    }\r\n\r\n    .authUser__alternar-panel h1 {\r\n        font-size: 30px;\r\n    }\r\n}\r\n","/* Box model universal */\r\n*,\r\n*:after,\r\n*:before {\r\n    box-sizing: border-box;\r\n    margin: 0;\r\n    padding: 0;\r\n}\r\n\r\n/* Clearfix */\r\n.clearfix::after {\r\n    content: '';\r\n    display: table;\r\n    clear: both;\r\n}\r\n\r\n/* Enlaces sin subrayado */\r\na {\r\n    color: inherit;\r\n    text-decoration: none;\r\n}\r\n\r\n/* Contenedor general */\r\n.login {\r\n    flex: 1;\r\n    width: 100%;\r\n    max-width: 525px;\r\n    min-height: 670px;\r\n    margin: auto;\r\n    position: relative;\r\n    background: url(../img/iglesia-huaro.jpg) no-repeat center;\r\n    background-size: cover;\r\n    box-shadow: 0 12px 15px rgba(0, 0, 0, 0.24), 0 17px 50px rgba(0, 0, 0, 0.19);\r\n    border-radius: 2rem;\r\n    margin-top: 1rem;\r\n    margin-bottom: 7rem;\r\n    display: flex;\r\n    /* Asegura comportamiento flexible */\r\n    align-items: center;\r\n}\r\n\r\n\r\n/* Contenedor interno */\r\n.login__inner {\r\n    width: 100%;\r\n    padding: 90px 70px 110px 70px;\r\n    background: rgba(40, 57, 101, 0.9);\r\n    border-radius: 2rem;\r\n    height: 100%;\r\n    /* Asegura que tome todo el alto del contenedor padre */\r\n    min-height: 670px;\r\n    /* Fuerza el alto mínimo igual en todas */\r\n    display: flex;\r\n    flex-direction: column;\r\n    justify-content: center;\r\n    /* Centra el contenido verticalmente */\r\n}\r\n\r\n\r\n/* Ocultar radio buttons y checkbox */\r\n.login__tab,\r\n.login__check {\r\n    display: none;\r\n}\r\n\r\n/* Tabs superiores (Sign In / Sign Up) */\r\n.login__label--tab {\r\n    font-size: 22px;\r\n    margin-right: 15px;\r\n    display: inline-block;\r\n    padding-bottom: 5px;\r\n    border-bottom: 2px solid transparent;\r\n    color: #aaa;\r\n    cursor: pointer;\r\n}\r\n\r\n/* Tab activo */\r\n.login__tab--signin:checked+.login__label--tab,\r\n.login__tab--signup:checked+.login__label--tab {\r\n    color: #fff;\r\n    border-color: #1161ee;\r\n}\r\n\r\n/* Contenedor del formulario */\r\n.login__form {\r\n    padding-top: 2rem;\r\n    position: relative;\r\n}\r\n\r\n/* Secciones SignIn y SignUp ocultas inicialmente */\r\n.login__section {\r\n    display: none;\r\n    opacity: 0;\r\n    visibility: hidden;\r\n    transition: opacity 0.3s ease-in-out;\r\n}\r\n\r\n/* Mostrar sección correspondiente según tab activo */\r\n.login__tab--signin:checked~.login__form .login__section--signin,\r\n.login__tab--signup:checked~.login__form .login__section--signup {\r\n    display: block;\r\n    opacity: 1;\r\n    visibility: visible;\r\n}\r\n\r\n/* Agrupación de campos */\r\n.login__group {\r\n    margin-bottom: 15px;\r\n}\r\n\r\n/* Etiquetas e inputs */\r\n.login__label,\r\n.login__input,\r\n.login__button {\r\n    width: 100%;\r\n    display: block;\r\n    color: #fff;\r\n}\r\n\r\n.login__label {\r\n    font-size: 2rem;\r\n    color: #aaa;\r\n    margin-bottom: 5px;\r\n}\r\n\r\n.login__input,\r\n.login__button {\r\n    padding: 15px 20px;\r\n    border-radius: 25px;\r\n    border: none;\r\n    background: rgba(255, 255, 255, 0.1);\r\n}\r\n\r\n/* Ocultar texto de password */\r\n.login__input[data-type=\"password\"] {\r\n    -webkit-text-security: disc;\r\n}\r\n\r\n/* Botón de envío */\r\n.login__button {\r\n    background: #1161ee;\r\n    cursor: pointer;\r\n    text-transform: uppercase;\r\n    font-weight: bold;\r\n    transition: background 0.3s;\r\n}\r\n\r\n.login__button:hover {\r\n    background: #0d47c6;\r\n}\r\n\r\n/* Checkbox personalizado */\r\n.login__label--checkbox {\r\n    display: flex;\r\n    align-items: center;\r\n    font-size: 12px;\r\n    color: #aaa;\r\n    cursor: pointer;\r\n}\r\n\r\n.login__label--checkbox .login__icon {\r\n    width: 15px;\r\n    height: 15px;\r\n    margin-right: 8px;\r\n    border-radius: 2px;\r\n    background: rgba(255, 255, 255, 0.1);\r\n    position: relative;\r\n}\r\n\r\n.login__label--checkbox .login__icon::before,\r\n.login__label--checkbox .login__icon::after {\r\n    content: '';\r\n    position: absolute;\r\n    background: #fff;\r\n    transition: all 0.2s ease-in-out;\r\n}\r\n\r\n.login__label--checkbox .login__icon::before {\r\n    width: 5px;\r\n    height: 2px;\r\n    bottom: 6px;\r\n    left: 3px;\r\n    transform: scale(0) rotate(0deg);\r\n}\r\n\r\n.login__label--checkbox .login__icon::after {\r\n    width: 10px;\r\n    height: 2px;\r\n    top: 6px;\r\n    right: 0;\r\n    transform: scale(0) rotate(0deg);\r\n}\r\n\r\n/* Activación del checkbox */\r\n.login__check:checked+.login__label--checkbox .login__icon {\r\n    background: #1161ee;\r\n}\r\n\r\n.login__check:checked+.login__label--checkbox .login__icon::before {\r\n    transform: scale(1) rotate(45deg);\r\n}\r\n\r\n.login__check:checked+.login__label--checkbox .login__icon::after {\r\n    transform: scale(1) rotate(-45deg);\r\n}\r\n\r\n/* Línea divisora */\r\n.login__hr {\r\n    height: 2px;\r\n    margin: 60px 0 50px 0;\r\n    background: rgba(255, 255, 255, 0.2);\r\n}\r\n\r\n/* Footer del login */\r\n.login__foot-link {\r\n    text-align: center;\r\n}\r\n\r\n.login__link {\r\n    color: #fff;\r\n    font-size: 14px;\r\n}\r\n\r\n.login__label--switch {\r\n    cursor: pointer;\r\n    font-size: 14px;\r\n    color: #aaa;\r\n    display: block;\r\n    margin-top: 10px;\r\n}",".userPerfil__contenedor {\r\n    background-color: #ffd399;\r\n    background-image:\r\n        radial-gradient(at 43% 24%, hsla(38, 62%, 78%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 2% 21%, hsla(20, 64%, 79%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 89% 57%, hsla(292, 79%, 70%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 32% 61%, hsla(326, 78%, 63%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 0% 97%, hsla(217, 89%, 63%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 74% 52%, hsla(86, 67%, 72%, 1) 0px, transparent 50%),\r\n        radial-gradient(at 98% 87%, hsla(144, 95%, 79%, 1) 0px, transparent 50%);\r\n    border-radius: 20px;\r\n\r\n    padding-bottom: 10rem;\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.estadoServicio {\r\n    @include m.contenedor-md;\r\n    margin: 4rem auto;\r\n\r\n    &__titulo {\r\n        @include m.nombre-pagina;\r\n        font-weight: 900;\r\n        color: v.$azul;\r\n        text-align: center;\r\n        margin-bottom: 3rem;\r\n    }\r\n\r\n    &__card {\r\n        background-color: v.$blanco;\r\n        border-radius: 1rem;\r\n        padding: 2.5rem 3rem;\r\n        box-shadow: rgba(0, 0, 0, 0.08) 0px 4px 15px;\r\n        margin-bottom: 2.5rem;\r\n        transition: box-shadow 0.3s ease;\r\n\r\n        &:hover {\r\n            box-shadow: rgba(0, 0, 0, 0.15) 0px 8px 30px;\r\n        }\r\n\r\n        @include m.tablet {\r\n            display: flex;\r\n            gap: 3rem;\r\n            flex-wrap: wrap;\r\n        }\r\n    }\r\n\r\n    &__section {\r\n        flex: 1 1 45%;\r\n        min-width: 280px;\r\n    }\r\n\r\n    &__subtitulo {\r\n        font-family: v.$fuente_principal;\r\n        font-weight: 700;\r\n        font-size: 2rem;\r\n        color: v.$gris-oscuro;\r\n        margin-bottom: 1.5rem;\r\n        border-bottom: 2px solid v.$azul;\r\n        padding-bottom: 0.5rem;\r\n    }\r\n\r\n    &__dato {\r\n        font-size: 1.6rem;\r\n        color: v.$gris-oscuro;\r\n        margin-bottom: 1rem;\r\n        line-height: 1.5;\r\n    }\r\n\r\n    &__etiqueta {\r\n        font-weight: 600;\r\n        color: v.$azul;\r\n        margin-right: 0.6rem;\r\n    }\r\n}","@use 'base/mixins' as m;\r\n@use 'base/variables' as v;\r\n\r\n.historial-grafica {\r\n    @include m.contenedor-sm;\r\n    background-color: lighten(v.$gris-claro, 5%);\r\n    padding: 3rem;\r\n    border-radius: 2rem;\r\n    margin-bottom: 4rem;\r\n    position: relative;\r\n    overflow: hidden;\r\n    @include m.shadow-lg;\r\n\r\n    &::before {\r\n        content: \"\";\r\n        position: absolute;\r\n        top: -40px;\r\n        right: -40px;\r\n        width: 100px;\r\n        height: 100px;\r\n        background-color: v.$azul;\r\n        opacity: 0.1;\r\n        border-radius: 50%;\r\n    }\r\n\r\n    canvas {\r\n        width: 100% !important;\r\n        height: auto !important;\r\n        display: block;\r\n        margin-top: 2rem;\r\n    }\r\n\r\n    &__titulo {\r\n        @include m.headings;\r\n        font-size: 2.4rem;\r\n        text-align: center;\r\n        @include m.texto-degradado(v.$azul, v.$secundario);\r\n        margin-bottom: 1rem;\r\n    }\r\n\r\n    &__descripcion {\r\n        font-size: 1.6rem;\r\n        text-align: center;\r\n        color: v.$gris-oscuro;\r\n        margin-bottom: 2rem;\r\n    }\r\n\r\n    &__icono {\r\n        font-size: 4rem;\r\n        text-align: center;\r\n        margin-bottom: 1rem;\r\n    }\r\n\r\n    &__resumen {\r\n        margin-top: 2rem;\r\n        text-align: center;\r\n        font-size: 1.6rem;\r\n\r\n        p {\r\n            margin: 0.5rem 0;\r\n            color: v.$negro;\r\n            font-weight: v.$bold;\r\n\r\n            span {\r\n                color: v.$azul;\r\n                font-weight: v.$black;\r\n            }\r\n        }\r\n    }\r\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardtecnico {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: v.$tecnico;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__contenido {\n        width: 100%;\n        padding: 1rem 1rem 3rem 1rem;\n\n        @include m.tablet {\n            padding: 1rem 5rem 3rem 5rem;\n        }\n\n        & h2 {\n            text-align: center;\n        }\n    }\n\n    &__contenedor-boton {\n        @include m.tablet {\n            display: flex;\n            justify-content: flex-end;\n            margin-bottom: 5rem;\n        }\n    }\n\n    &__boton {\n        @include m.boton(v.$tecnico, v.$blanco);\n        margin-left: 1rem;\n        text-transform: uppercase;\n        font-size: 1.4rem;\n\n        @include m.tablet {\n            width: auto;\n        }\n    }\n\n    &__contenedor {\n        background-color: v.$blanco;\n        padding: 2rem;\n        border-radius: 1rem;\n        margin-top: 5rem;\n    }\n\n\n    &__formulario {\n        @extend .dashboardtecnico__contenedor;\n        @include m.contenedor-md;\n    }\n\n    &__mensaje {\n        padding-top: 3rem;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n    }\n\n    //nav\n    &__grid {\n        padding-top: 6rem;\n        @include m.contenedor-l;\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            // Asigna más espacio a la primera columna (por ejemplo, 2/3 del ancho total)\n            display: grid;\n            grid-template-columns: 2fr 1fr;\n            gap: 2rem;\n        }\n    }\n\n    &__recomendaciones {\n        line-height: 3rem;\n    }\n\n    &__navegacion {\n        padding-top: 3rem;\n\n        @include m.grid(1, .5rem);\n\n        @include m.tablet {\n            @include m.grid(2, 1rem);\n\n        }\n    }\n\n    &__navegacion-enlace {\n        all: unset;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        background-color: v.$tecnico;\n        border-radius: 2rem;\n        padding: 2rem;\n        width: 25rem;\n        margin: 0 auto;\n\n        &:hover {\n            cursor: pointer;\n            background-color: darken($color: v.$tecnico, $amount: 20%);\n        }\n    }\n\n\n\n    &__navegacion-icono {\n        color: v.$blanco;\n        font-size: 6rem;\n        padding-bottom: 1rem;\n    }\n\n    &__navegacion-texto {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    &__navegacion-etiqueta {\n        color: v.$blanco;\n        padding-top: 1rem;\n        text-align: center;\n    }\n\n    //division en crear\n    &__gridCreate {\n        @include m.grid(1, 2rem);\n\n        @include m.tablet {\n            @include m.grid(2, 2rem);\n\n        }\n    }\n\n\n\n}","@use 'base/mixins' as m;\n@use 'base/variables' as v;\n\n.dashboardTesorero {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    background-color: v.$gris-claro;\n\n    &__header {\n        background-color: v.$tesorero;\n        padding: 2rem;\n    }\n\n    &__header-grid {\n        display: flex;\n        flex-direction: column;\n\n        @include m.tablet {\n            flex-direction: row;\n            justify-content: space-between;\n            align-items: center;\n        }\n    }\n\n    &__logo {\n        @include m.logo;\n        @include m.texto-fluido(2rem, 3rem);\n    }\n\n    &__nav {}\n\n    &__form {\n        display: flex;\n        justify-content: center;\n    }\n\n    &__submit--logout {\n        @include m.enlace;\n    }\n\n    &__grid {\n        display: flex;\n        flex: 1;\n        overflow-y: auto;\n    }\n\n    &__sidebar {\n        background-color: lighten(v.$tesorero, 10);\n        width: 12rem;\n    }\n\n    &__menu {\n        padding: 1rem;\n        display: flex;\n        flex-direction: column;\n        gap: 1rem;\n    }\n\n    &__enlace {\n        color: lighten(v.$tesorero, 40);\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 2rem;\n        transition: 300ms background-color ease-in-out, 300ms color ease, 300ms border-radius ease;\n\n        &:hover,\n        &--actual {\n            background-color: lighten(v.$tesorero, 20);\n